(function(){"use strict";window.NITI_OLD_EXAMS=[{"id":"archive-2555-s-1-1","year":"2555","semester":"ภาคฤดูร้อน","number":1,"page":1,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2555 ภาคฤดูร้อน · ข้อ 1","sections":["1299"],"otherSections":[],"question":"ข้ อ 1. นายแก้ว กับ นายขวดท าสัญ ญากัน ด้ว ยวาจาให้น ายขวดมี สิ ท ธิ เ ก็ บ กิ น บนที่ ดิ น ของนายแก้ว เป็ น\nเวลา 5 ปี เมื่ อนายขวดเข้า มาใช้สิ ท ธิ เก็ บ กิ นได้ 3 ปี นายแก้วขายที่ ดินให้นายถ้วย นายถ้วยต้องการท า\nประโยชน์ในที่ดินด้วยตนเอง จึงไม่ยอมให้นายขวดมาใช้สิทธิเก็บกินบนที่ดินอีก\nดังนี้ ให้วินิจฉัยว่า นายขวดจะอ้างสิ ทธิเก็บกินบนที่ดินแปลงนี้ อีก 2 ปี ขึ้นต่อสู ้ได้หรื อไม่ นายถ้วย\nจะต้องยอมให้นายขวดใช้สิทธิเก็บกินจนครบ 5 ปี หรื อไม่ เพราะเหตุใด จงอธิบาย","rule":"มาตรา 1299 วรรคแรก ภายในบังคับแห่ งบทบัญญัติในประมวลกฎหมายนี้ หรื อกฎหมายอื่น ท่าน\nว่ า การได้ ม าโดยนิ ติ ก รรมซึ่ งอสั ง หาริ มทรั พ ย์ห รื อทรั พ ยสิ ท ธิ อัน เกี่ ย วกั บ อสั ง หาริ มทรั พ ย์ น้ ั นไม่\nบริ บูรณ์ เว้นแต่นิติกรรมจะได้ทาเป็ นหนังสื อและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่","application":"ตามกฎหมาย การได้มาซึ่งอสังหาริ มทรัพย์หรื อทรัพยสิ ทธิอนั เกี่ยวกับอสังหาริ มทรัพย์โดยทางนิติ\nกรรมนั้น จะบริ บู ร ณ์ เ ป็ นทรั พ ยสิ ท ธิ ไ ด้ จะต้อ งท าเป็ นหนัง สื อ และจดทะเบี ย นการได้ม ากับ พนัก งาน\nเจ้าหน้าที่ ซึ่งถ้าฝ่ าฝื นจะมีผลเป็ นเพียงบุคคลสิ ทธิ ใช้กล่าวอ้างได้เฉพาะคู่สัญญาเท่านั้น ไม่สามารถยกขึ้น\nกล่าวอ้างต่อบุคคลภายนอกได้ (มาตรา 1299 วรรคแรก)\nกรณี ตามอุทาหรณ์ การที่นายแก้วกับนายขวดทาสัญญากันด้วยวาจา ให้นายขวดมีสิทธิเก็บกินบนที่ดินของ\nนายแก้วเป็ นเวลา 5 ปี นั้น ถือว่านายขวดเป็ นผูไ้ ด้มาซึ่ งทรัพยสิ ทธิ ในอสังหาริ มทรัพย์โดยนิ ติกรรม เมื่อ\nไม่ ไ ด้ท าเป็ นหนัง สื อและจดทะเบี ย นกับ พนัก งานเจ้า หน้า ที่ สิ ท ธิ ก ารได้ม าดัง กล่า วจึ ง ไม่ บ ริ บู ร ณ์ เ ป็ น\nทรัพยสิ ทธิ แต่มีผลผูกพันเป็ นบุคคลสิ ทธิระหว่างนายแก้วกับนายขวดเท่านั้น\nดังนั้น เมื่อต่อมานายแก้วขายที่ดินให้นายถ้วย นายถ้วยจึงไม่ตอ้ งผูกพันในข้อตกลงที่นายแก้วมีต่อ\nนายขวด และนายขวดไม่สามารถอ้างการได้สิทธิเก็บกินบนที่ดินขึ้นต่อสู ้กบั นายถ้วยได้ นายถ้วยจึงไม่ตอ้ ง\nให้นายขวดใช้เก็บกินบนที่ดินนั้นต่อไปแต่อย่างใด","conclusion":"สรุป นายถ้วยไม่ตอ้ งให้นายขวดใช้สิทธิเก็บกินจนครบ 5 ปี","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2555-s-3-2","year":"2555","semester":"ภาคฤดูร้อน","number":3,"page":2,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2555 ภาคฤดูร้อน · ข้อ 3","sections":["1367","1377"],"otherSections":["1378"],"question":"ข้ อ 3. นายกล้าทาสัญญาขายที่ดิน น.ส.3 ของตนให้กบั นายเข้ม โดยเป็ นการทาสัญญาซื้ อขายกันเองและมี\nการชาระราคาที่ดินให้นายกล้าครบถ้วน และนายกล้าก็ส่งมอบที่ดินให้นายเข้มแล้ว หลังจากนายเข้มสร้าง\nบ้านอยู่ในที่ดินนั้นติดต่อกันได้ห้าปี นายกล้าถึงแก่ความตาย นายแก้วบุตรของนายกล้าได้จดทะเบียนรับ\nมรดกที่ดินแปลงนั้น แล้วแจ้งให้นายเข้มย้ายออกไปจากที่ดินนั้น แต่นายเข้มอ้างว่าที่ดินเป็ นของตน และ\nไม่ยอมย้ายออกไป ต่อจากนั้นอีก 4 เดือน นายแก้วจึงฟ้องขับไล่และเรี ยกที่ดินคืนจากนายเข้ม\nดังนี้ให้วินิจฉัยว่า ระหว่างนายแก้วกับนายเข้ม ผูใ้ ดมีสิทธิในที่ดินพิพาทดีกว่ากัน และนายเข้มต้อง\nออกไปจากที่ดินนั้นหรื อไม่ เพราะเหตุใด","rule":"มาตรา 1367 บุ ค คลใดยึดถื อทรั พ ย์สิ น โดยเจตนาจะยึดถื อ เพื่ อตน ท่ า นว่า บุ ค คลนั้นได้ซ่ ึ ง สิ ท ธิ\nครอบครอง\nมาตรา 1377 วรรคหนึ่ ง ถ้า ผูค้ รอบครองสละเจตนาครอบครอง หรื อไม่ ยึดถื อทรั พ ย์สิ นต่อไป\nไซร้ การครอบครองย่อมสิ้ นสุ ดลง\nมาตรา 1378 การโอนไปซึ่งการครอบครองนั้น ย่อมทาได้โดยส่งมอบทรัพย์สินที่ครอบครอง","application":"ตามอุทาหรณ์ การที่นายกล้าทาสัญญาขายที่ดิน น.ส.3 ของตนให้กบั นายเข้ม โดยเป็ นการทาสัญญา\nซื้ อขายกันเองนั้น สัญญาซื้ อขายที่ดินระหว่างนายกล้ากับนายเข้มย่อมตกเป็ นโมฆะเพราะไม่ได้จดทะเบียน\nกับพนักงานเจ้าหน้าที่ แต่อย่างไรก็ตาม เนื่องจากที่ดินดังกล่าวเป็ นที่ดิน น.ส.3 ซึ่งมีเพียงสิ ทธิครอบครอง\nและการซื้ อขายดังกล่าวได้มีการชาระราคาครบถ้วนและได้มีการส่ งมอบที่ดินให้แก่นายเข้มผูซ้ ้ื อแล้ว การ\nครอบครองที่ ดินของนายกล้าผูข้ ายจึ งสิ้ นสุ ดลงตามมาตรา 1377 วรรคแรก เพราะนายกล้าได้สละเจตนา\nครอบครองและไม่ได้ยึดถือที่ดินนั้นต่อไปแล้ว ส่ วนนายเข้มก็ได้ซ่ ึ งสิ ทธิ ครอบครองที่ดินนั้นแล้วโดยการ\nส่งมอบทรัพย์สินที่ครอบครองตามมาตรา 1378 และนายเข้มได้เข้ายึดถือที่ดินนั้นด้วยเจตนายึดถือเพื่อตนใน\nฐานะเจ้าของตามมาตรา 1367\nแต่ต่อมาอีก 5 ปี เมื่อนายกล้าถึงแก่ความตาย\nดังนี้ แม้นายแก้วบุตรของนายกล้าจะได้จดทะเบียนรับมรดกที่ดินนั้นแล้วแจ้งให้นายเข้มย้ายออกไป\nจากที่ดินนั้น นายเข้มก็ไม่ตอ้ งย้ายออกไปจากที่ดินนั้นตามที่นายแก้วต้องการ เพราะนายเข้มเป็ นผูม้ ีสิทธิ\nครอบครองเหนื อที่ดินนั้นดีกว่านายแก้ว เนื่องจากนายแก้วผูร้ ับมรดกไม่มีสิทธิ ดีกว่านายกล้าเจ้ามรดกตาม\nหลักที่วา่ “ผูร้ ับโอนไม่มีสิทธิดีกว่าผูโ้ อน” นัน่ เอง","conclusion":"สรุป นายเข้มมีสิทธิในที่ดินพิพาทดีกว่านายแก้ว และนายเข้มไม่ตอ้ งย้ายออกไปจากที่ดินนั้น","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2555-s-4-3","year":"2555","semester":"ภาคฤดูร้อน","number":4,"page":3,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2555 ภาคฤดูร้อน · ข้อ 4","sections":["1382","1387"],"otherSections":["1388"],"question":"ข้ อ 4. นายแห้วเป็ นเจ้า ของที่ ดิ นแปลงหนึ่ ง อยู่ติ ดกับ ทางสาธารณะซึ่ ง เป็ นทางดิ นลูก รั ง กว้า งสองเมตร\nครึ่ ง นายแห้วจึงได้ใช้ทางผ่านที่ดินของนายมัน โดยทาเป็ นถนนลาดยางกว้างสามเมตรเพื่อใช้รถปิ๊ กอัพผ่าน\nเข้าออกระหว่างที่ดินของตนกับถนนพหลโยธินซึ่งสะดวกกว่า หลังจากนายแห้วใช้ทางผ่านที่ดินของนาย\nมันติดต่อกันเป็ นเวลากว่าสิ บปี โดยนายมันไม่รู้เรื่ องแต่อย่างใด ต่อมานายแห้วได้สร้างโรงงานในที่ดินของ\nตน ทาให้ตอ้ งใช้รถยนต์บรรทุกสิ บล้อผ่านเข้าออกเพื่อขนส่งสิ นค้าวันละหลายเที่ยว นายแห้วจึงเปลี่ยนจาก\nถนนลาดยางเป็ นถนนคอนกรี ตกว้า งหกเมตร หลัง จากนั้น นายมันรู ้ เรื่ องจึ ง มาปรึ ก ษาท่ า น เพราะไม่\nต้องการให้นายแห้วใช้ถนนนั้นผ่านที่ดินของตน\nดัง นี้ ใ ห้ท่ า นวิ นิจฉัย ว่า ระหว่า งนายแห้ วกับ นายมันมี สิ ท ธิ และหน้า ที่ เ หนื อที่ ดิ นแปลงดัง กล่ า ว\nอย่างไร จงอธิบาย","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1387 อสังหาริ มทรัพย์อาจต้องตกอยู่ในภาระจายอมอันเป็ นเหตุให้เจ้าของต้องยอมรับกรรม\nบางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรื อต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยูใ่ นกรรมสิ ทธิ์ทรัพย์สิน\nนั้นเพื่อประโยชน์แก่อสังหาริ มทรัพย์อื่น\nมาตรา 1388 เจ้ า ของสามยทรั พ ย์ ไ ม่ มี สิ ทธิ ท าการเปลี่ ย นแปลงในภารยทรั พ ย์ หรื อใน\nสามยทรัพย์ ซึ่งทาให้เกิดภาระเพิ่มขึ้นแก่ภารยทรัพย์","application":"กรณี ต ามอุ ท าหรณ์ การที่ น ายแห้ว ได้ใ ช้ท างผ่ า นที่ ดิ น ของนายมัน โดยท าเป็ นถนนลาดยาง\nกว้า ง 3 เมตร ผ่ า นที่ ดิ น ของนายมัน เพื่ อ ใช้ร ถปิ๊ กอัพ ผ่ า นเข้า ออกระหว่ า งที่ ดิ น ของนายแห้ ว กับ ถนน\nพหลโยธิน โดยนายมันไม่รู้เรื่ องติดต่อกันเป็ นเวลาเกิน 10 ปี แล้ว ย่อมถือว่านายแห้วได้ภาระจายอมเหนื อ\nที่ ดิ น ของนายมัน โดยอายุค วามปรปั ก ษ์ คื อ การได้ม าซึ่ ง ภาระจ ายอมโดยอายุค วาม ตามมาตรา 1387,\n1401 และมาตรา 1382\nต่อมาการที่นายแห้วได้สร้างโรงงานในที่ดินของตน และต้องการใช้รถยนต์บรรทุกสิ บล้อผ่านเข้า\nออกเพื่อขนส่ งสิ นค้าวันละหลายเที่ยว นายแห้วจึงเปลี่ยนจากถนนลาดยางเป็ นถนนคอนกรี ตกว้าง 6 เมตร\nนั้น การกระทาดังกล่าวของนายแห้วเป็ นเรื่ องที่เจ้าของสามยทรัพย์ทาการเปลี่ยนแปลงในภารยทรัพย์ซ่ ึงทา\nให้เกิดภาระเพิ่มขึ้นแก่ภารยทรัพย์\nดังนั้น นายแห้วจะกระทาไม่ได้ตามมาตร 1388","conclusion":"สรุป นายแห้วได้ภาระจายอมเป็ นถนนลาดยางกว้าง 3 เมตร ผ่านที่ดินของนายมันแล้ว และนายมัน\nจะห้ามนายแห้วไม่ให้ใช้ทางภาระจายอมนั้นไม่ได้ แต่นายแห้วจะเปลี่ยนถนนลาดยางซึ่งเดิมกว้าง 3 เมตร\nเป็ นถนนคอนกรี ตกว้าง 6 เมตรไม่ได้\nการสอบไล่ภาค 2 ปี การศึกษา 2555\nข้อสอบกระบวนวิชา LAW2001 (LA 201),(LW 204)\nกฎหมายแพ่งและพาณิชย์ว่าด้วยทรัพย์\nคาแนะนา ข้อสอบเป็ นอัตนัยล้วนมี 4 ข้อ","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2555-2-3-7","year":"2555","semester":"ภาค 2","number":3,"page":7,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2555 ภาค 2 · ข้อ 3","sections":["1382","1387","1401"],"otherSections":["1374"],"question":"ข้ อ 3. น้ าแบ่งขายที่ดินของน้ าให้ฟ้าโดยทั้งน้ าและฟ้าตกลงให้ที่ดินของฟ้ามีทางเข้าออกสู่ ทางสาธารณะผ่าน\nที่ดินแปลงของน้ าในส่ วนที่เหลือ แต่ไม่ได้จดทะเบียนการได้มา เมื่อฟ้าซื้ อที่ดินจากน้ ามาแล้ว ได้เข้ามาปลูก\nบ้านอยูอ่ าศัยในที่ดินแปลงนั้น แทนที่จะเดินในทางที่ตกลงไว้กบั น้ า\nฟ้ า กลับ ใช้ท างผ่า นในส่ วนอื่ นของที่ ดินของน้ า โดยไม่ บ อกน้ า และยัง ท าถนนคอนกรี ต เพื่ อ ให้\nรถยนต์เข้าออก นอกจากนั้นฟ้ายังเข้ามาในที่ดินของน้ าโดยเข้ามาทิ้งขยะในที่ดินของน้ าทุกวันด้วย ฟ้าได้ทา\nเช่นนี้ตลอดกว่าสิ บปี โดยน้ าไม่ทราบ เมื่อน้ าทราบจึงได้มาห้ามและบอกให้ฟ้าเลิกใช้ถนนที่ฟ้าสร้างให้มาใช้\nถนนเส้นที่ตกลงเดิม และเลิกเข้ามาทิ้งขยะในที่ดินของน้ า ฟ้าตกลงเลิกทิ้งขยะ แต่ถนนฟ้าไม่ยอมเพราะถนน\nที่ตนสร้างสะดวกสบายกว่า แต่พอผ่านมาได้สามเดือนฟ้าได้เข้าทิ้งขยะในที่ดินของน้ าอีก คราวนี้ น้ าทนไม่\nไหว หนึ่งเดือนหลังจากนั้น น้ าจึงได้ฟ้องต่อศาลให้ฟ้าเลิกทิ้งขยะและรื้ อถนนที่ฟ้าสร้างออกไป\nให้ท่านวินิจฉัยถึงสิ ทธิของฟ้าในถนนที่ฟ้าสร้าง และการทิ้งขยะในที่ดินของน้ า","rule":"มาตรา 1374 ถ้าผูค้ รอบครองถูกรบกวนในการครอบครองทรัพย์สิน เพราะมีผสู ้ อดเข้าเกี่ยวข้องโดย\nมิชอบด้วยกฎหมายไซร้ ท่านว่าผูค้ รอบครองมีสิทธิ จะให้ปลดเปลื้องการรบกวนนั้นได้ ถ้าเป็ นที่น่าวิตกว่า\nจะยังมีการรบกวนอีก ผูค้ รอบครองจะขอต่อศาลให้สั่งห้ามก็ได้\nการฟ้องคดีเพื่อปลดเปลื้องการรบกวนนั้น ท่านว่าต้องฟ้องภายในปี หนึ่งนับแต่เวลาถูกรบกวน\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1387 อสังหาริ มทรัพย์อาจต้องตกอยู่ในภาระจายอมอันเป็ นเหตุให้เจ้าของต้องยอมรับกรรม\nบางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรื อต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยูใ่ นกรรมสิ ทธิ์ทรัพย์สิน\nนั้นเพื่อประโยชน์แก่อสังหาริ มทรัพย์อื่น\nมาตรา 1401 ภาระจายอมอาจได้มาโดยอายุความ ท่านให้นาบทบัญญัติว่าด้วยอายุความได้สิทธิ อนั\nกล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บงั คับโดยอนุโลม","application":"กรณีตามอุทาหรณ์ มีประเด็นที่จะต้องวินิจฉัย 2 ประเด็น คือ\nประเด็นที่ 1 เกี่ยวกับสิ ทธิของฟ้าในถนนที่ฟ้าสร้าง\nการที่น้ าแบ่งขายที่ดินของน้ าให้ฟ้า และตกลงให้ฟ้ามีทางเข้าออกสู่ ทางสาธารณะผ่านที่ดินแปลงของน้ าใน\nส่ วนที่เหลือนั้น ถือว่าฟ้าได้ภาระจายอมโดยทางนิ ติกรรม และแม้ไม่ได้จดทะเบียนการได้มาก็สามารถใช้\nบังคับกันได้ในระหว่างคู่กรณี แต่เมื่อฟ้าซื้อที่ดินจากน้ ามาแล้วและได้เข้ามาปลูกบ้านอยู่อาศัยในที่ดินแปลง\nนั้น แทนที่จะเดินเข้าออกในทางที่ตกลงไว้กบั น้ า กลับใช้ทางผ่านในส่ วนอื่นของที่ดินของน้ าโดยไม่บอก\nน้ า และยังทาถนนคอนกรี ตเพื่อให้รถยนต์เข้าออกจนครบกาหนด 10 ปี โดยที่น้ าไม่ทราบ กรณี น้ ีจึงถือได้ว่า\nฟ้าซึ่งเป็ นเจ้าของสามยทรัพย์ได้ใช้ประโยชน์ในภารยทรัพย์ (ที่ดินของน้ า) โดยสงบและโดยเปิ ดเผย และ\nด้วยเจตนาจะได้สิทธิ ภาระจายอมในภารยทรัพย์น้ นั ดังนั้นฟ้าย่อมได้ภาระจายอมในถนนที่ฟ้าสร้างโดยการ\nครอบครองปรปักษ์ตามมาตรา 1382 ประกอบมาตรา 1401 และน้ าซึ่งเป็ นเจ้าของภารยทรัพย์จะฟ้องให้ฟ้ารื้ อ\nถนนที่ฟ้าสร้างออกไปไม่ได้ ตามมาตรา 1387\nประเด็นที่ 2 เกี่ยวกับการทิ้งขยะของฟ้าในที่ดินของน้ า\nการที่ฟ้าได้นาขยะมาทิ้งในที่ดินของน้ าทุกวันนั้น ถือว่าน้ าผูค้ รอบคอรงที่ดินถูกฟ้ ารบกวนการครอบครอง\nโดยมิ ช อบด้ว ยกฎหมาย น้ าจึ ง มี สิ ท ธิ บ อกห้ า มและให้ ฟ้ า เลิ ก เข้า มาทิ้ ง ขยะในที่ ดิ น ของน้ าได้ ต าม\nมาตรา 1374 วรรคแรก และเมื่ อฟ้ า ตกลงเลิ กทิ้ ง ขยะแล้ว การรบกวนการครอบครองย่อมระงับไป แต่\nอย่างไรก็ตาม เมื่อปรากฏว่า พอผ่านมาได้สามเดือนฟ้าได้เข้ามาทิ้งขยะในที่ดินของน้ าอีก จึงถือว่าน้ าได้ถูก\nรบกวนการครอบครองอีก ดังนั้นน้ าจึงมีสิทธิ ฟ้องเป็ นคดีต่อศาล เพื่อให้ศาลสั่งห้ามไม่ให้ฟ้านาขยะเข้ามา\nทิ้งในที่ดินของน้ าได้ แต่ตอ้ งฟ้องภายใน 1 ปี นับแต่วนั ที่ถูกรบกวนตามมาตรา 1374 วรรคสอง และตาม\nข้อเท็จจริ งน้ าได้ฟ้องคดีต่อศาลหลังจากถูกฟ้ากระทาการดังกล่าวได้หนึ่ งเดือน ดังนั้นน้ าจึงสามารถฟ้องศาล\nเพื่อสัง่ ให้ฟ้าเลิกทิง้ ขยะในที่ดินของน้ าตามมาตรา 1374 ได้","conclusion":"สรุ ป ฟ้าได้ภาระจายอมในถนนที่ฟ้าสร้างโดยการครอบครองปรปักษ์ น้ าจะฟ้องศาลเพื่อให้ศาลสั่ง\nให้ฟ้ารื้ อถนนที่ฟ้าสร้างออกไปไม่ได้ แต่น้ าสามารถฟ้องศาลเพื่อให้ศาลสั่งให้ฟ้าเลิกทิ้งขยะในที่ดินของน้ า\nได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2555-2-4-9","year":"2555","semester":"ภาค 2","number":4,"page":9,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2555 ภาค 2 · ข้อ 4","sections":["1367","1375","1382","1387","1401"],"otherSections":["1399"],"question":"ข้ อ 4. แสงท านาบนที่ ดินมื อเปล่า แปลงหนึ่ ง ของโสม โดยที่ แสงเข้า ในผิ ด คิ ด ว่า เป็ นที่ ดิน ที่ ซ้ื อ มาจาก\nสอง และใช้ทางผ่านที่ดินสี่ แปลงเพื่อเข้าไปทานาบนที่ดินของโสมแปลงนั้น ที่ดินแปลงแรกที่เดินผ่านเป็ น\nของสี แปลงที่สองเป็ นของสวย แปลงที่สามเป็ นที่ดินซึ่ งเตรี ยมไว้สร้ างโรงพยาบาลของรั ฐแต่ยงั ไม่ ไ ด้\nก่อสร้าง แปลงที่สี่เป็ นที่ดินของสด แสงใช้ทางผ่านที่ดินของสี ของสวย ที่ดินของโรงพยาบาล และที่ดิน\nของสดมาตลอดสิ บกว่าปี แล้ว ต่อมาจังหวัดได้เข้ามาก่อสร้างโรงพยาบาล ตอนก่อสร้างอยู่หนึ่ งปี กว่า แสง\nต้องไปใช้ทางอื่นผ่านเข้าไปทานาบนที่ดินแปลงที่แสงครอบครอง เมื่อสร้างโรงพยาบาลเสร็จ แสงกลับมาใช้\nทางผ่า นทางเดิ ม ของสี ของสวย ผ่า นที่ ดินของโรงพยาบาล และที่ ดินของสดอี ก สดห้า มไม่ ใ ห้แสงใช้\nทางผ่านที่ดินของตน เพราะว่าภาระจายอมในที่ดินมือเปล่าที่ผา่ นที่ดินของสดได้สิ้นไปแล้ว\nให้ท่านอธิบายกับแสงถึงสิ ทธิที่ จะใช้ทางผ่านที่ดินทั้งสี่ แปลงว่าแสง มีสิทธิหรื อไม่มีสิทธิอย่างไร\nบ้าง เพราะเหตุใด และที่ดินของโสมที่แสงเข้าไปครอบครองทานา โสมฟ้องศาลเรี ยกคืนได้หรื อไม่ เพราะ\nเหตุใด","rule":"มาตรา 1367 บุ ค คลใดยึดถื อทรั พ ย์สิ น โดยเจตนาจะยึดถื อ เพื่ อตน ท่ า นว่า บุ ค คลนั้นได้ซ่ ึ ง สิ ท ธิ\nครอบครอง\nมาตรา 1375 ถ้า ผู ้ค รอบครองถู ก แย่ ง การครอบครองโดยมิ ช อบด้ว ยกฎหมายไซร้ ท่ า นว่ า ผู ้\nครอบครองมีสิทธิจะได้คืนซึ่งการครอบครอง เว้นแต่อีกฝ่ ายหนึ่งมีสิทธิเหนือทรัพย์สินดีกว่า ซึ่งจะเป็ นเหตุ\nให้เรี ยกคืนจากผูค้ รอบครองได้\nการฟ้ อ งคดี เ พื่ อ เอาคื น ซึ่ งการครอบครองนั้ น ท่ า นว่ า ต้อ งฟ้ อ งภายในหนึ่ งปี นั บ แต่ เ วลาถู ก แย่ ง การ\nครอบครอง\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1387 อสังหาริ มทรัพย์อาจต้องตกอยู่ในภาระจายอมอันเป็ นเหตุให้เจ้าของต้องยอมรับกรรม\nบางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรื อต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยูใ่ นกรรมสิ ทธิ์ทรัพย์สิน\nนั้นเพื่อประโยชน์แก่อสังหาริ มทรัพย์อื่น\nมาตรา 1399 ภาระจายอมนั้น ถ้ามิได้ใช้สิบปี ท่านว่าย่อมสิ้ นไป\nมาตรา 1401 ภาระจายอมอาจได้มาโดยอายุความ ท่านให้นาบทบัญญัติว่าด้วยอายุความได้สิทธิอนั\nกล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บงั คับโดยอนุโลม","application":"กรณีตามอุทาหรณ์ ประเด็นแรกที่ตอ้ งวินิจฉัย คือ\nแสงมี สิทธิ หรื อไม่มีสิทธิ อย่างไรบ้างที่จะใช้ทางผ่านที่ ดินทั้งสี่ แปลง เห็นว่า การที่แสงทานาบน\nที่ดินมือเปล่าแปลงหนึ่งของโสม โดยที่แสงเข้าใจผิดคิดว่าเป็ นที่ดินของตนที่ซ้ื อมาจากสองนั้น ถือเป็ นกรณี\nที่ แ สงยึ ด ถื อ ที่ ดิ น โดยเจตนาจะยึด ถื อ เพื่ อ ตน ดัง นั้ น แสงจึ ง ได้สิ ท ธิ ค รอบครองในที่ ดิ น ของโสมตาม\nมาตรา 1367\nเมื่อปรากฏข้อเท็จจริ งว่า แสงใช้ทางผ่านที่ดินสี่ แปลงเพื่อเข้าไปทานาบนที่ดินของโสม โดยที่ดินแปลงแรก\nเป็ นของสี แปลงที่สองเป็ นของสวย แปลงที่สามเป็ นที่ดินซึ่งเตรี ยมไว้สร้างโรงพยาบาลของรัฐ แต่ยงั ไม่ได้\nก่อสร้าง แปลงที่สี่เป็ นที่ดินของสด\nดัง นี้ การที่ แ สงใช้ท างผ่ า นที่ ดิ น แปลงแรก แปลงที่ ส อง และแปลงที่ สี่ น้ ั น ย่ อ มถื อ ว่ า แสงผู ้\nครอบครองสามยทรัพย์ได้ใช้ประโยชน์ในภารยทรัพย์โดยความสงบ เปิ ดเผย และมีเจตนาจะได้สิทธิภาระจา\nยอมในภารยทรัพย์แล้ว เมื่อแสงเดินผ่านที่ดินทั้งสามแปลงมาตลอด 10 ปี กว่าแล้ว ย่อมทาให้แสงได้ภาระจา\nยอมโดยการครอบครองปรปั ก ษ์ บ นที่ ดิ น ของสี ของสวย และของสดตามมาตรา 1401 ประกอบ\nมาตรา 1382 และ 1387 ส่ วนที่ดินแปลงที่สาม ซึ่ งเตรี ยมสร้างโรงพยาบาลซึ่ งเป็ นของรัฐนั้นถือเป็ นสาธารณ\nสมบัติของแผ่นดิน จึงครอบครองปรปักษ์ไม่ได้ ดังนั้นแม้แสงจะใช้เป็ นทางเดินผ่านนานเท่าใดก็ย่อมไม่ได้\nภาระจายอมโดยการครอบครองปรปักษ์ และรัฐย่อมมีสิทธิฟ้องไม่ให้แสงใช้ทางผ่านที่ดินได้\nและเมื่อปรากฏว่า ต่อมาจังหวัดได้เข้ามาก่อสร้างโรงพยาบาล โดยใช้เวลาก่อสร้างอยู่หนึ่ งปี กว่า และแสง\nต้องไปใช้ทางอื่นผ่านเข้าไปทานาบนที่ดินแปลงที่แสงครอบครอง ซึ่ งเมื่อสร้างโรงพยาบาลเสร็ จแสงก็\nกลับมาใช้ทางผ่านทางเดิมของสี ของสวย ผ่านที่ดินของโรงพยาบาล และที่ดินของสดอีกนั้น กรณี น้ ียงั ไม่\nถื อว่า ภาระจายอมบนที่ ดินทั้ง สามแปลงของสี ของสวย และของสดนั้น สิ้ นไปแต่ อย่า งใด เพราะตาม\nมาตรา 1399 นั้นได้กาหนดไว้ว่า ภาระจายอมจะสิ้ นไปโดยระยะเวลา ก็ต่อเมื่อมิได้มีการใช้ต้ งั แต่สิบปี ขึ้น\nไป ดังนั้น แสงจึงมีสิทธิ ที่จะใช้ทางผ่า นที่ดินทั้งสามแปลง สดจะห้ามไม่ไห้แสงใช้ทางผ่านที่ดินของตน\nไม่ได้\nประเด็นที่สอง ที่ตอ้ งวินิจฉัยคือ\nที่ดินของโสมที่แสงเข้าไปครอบครองทานา โสมฟ้องศาลเรี ยกคืนได้หรื อไม่ เห็นว่า แม้ตามข้อเท็จจริ ง\nโสมจะถูกแสงแย่งการครอบครองที่ดินโดยมิชอบด้วยกฎหมาย ตามมาตรา 1375 วรรคแรก อันทาให้โสม\nผูค้ รอบครองที่ดินมีสิทธิ ฟ้องเรี ยกคืนที่ดินจากแสงได้ก็ตาม แต่การฟ้องคดีเพื่อเอาคืนซึ งการครอบครอง\nนั้น มาตรา 1375 วรรคสอง กาหนดว่าจะต้องฟ้องภายในหนึ่งปี นับแต่เวลาถูกแย่งการครอบครอง\nดังนั้น เมื่อระยะเวลานับแต่วนั ที่แสงแย่งการครอบครองที่ดินมาจากโสมนั้น ล่วงเวลามาเกินหนึ่งปี\nแล้ว โสมจึงฟ้องเรี ยกคืนไม่ได้","conclusion":"สรุป แสงมีสิทธิหรื อไม่มีสิทธิอย่างไรบ้างที่จะใช้ทางผ่านที่ดินทั้งสี่ แปลงเป็ นไปตามที่ได้อธิบายไว้\nข้างต้น และที่ดินของโสมที่แสงเข้าไปครอบครองทานา โสมจะฟ้องศาลเรี ยกคืนไม่ได้\nการสอบไล่ภาค 1 ปี การศึกษา 2555\nข้อสอบกระบวนวิชา LAW2001 (LA 201),(LW 204)\nกฎหมายแพ่งและพาณิชย์ว่าด้วยทรัพย์\nคาแนะนา ข้อสอบเป็ นอัตนัยล้วนมี 4 ข้อ","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2555-1-1-12","year":"2555","semester":"ภาค 1","number":1,"page":12,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2555 ภาค 1 · ข้อ 1","sections":["1299"],"otherSections":[],"question":"ข้ อ 1. ชัย ท าสั ญญายกที่ ดินมี โฉนดแปลงหนึ่ ง ตี ใ ช้หนี้ ใ ห้เชิ ดเจ้า หนี้ แต่ ท้ งั สองยัง ไม่ ไ ด้จดทะเบี ย นกับ\nพนักงานเจ้าหน้าที่ หลังจากชัยส่งมอบที่ดินให้เชิดครอบครองได้สามปี เกียรติเจ้าหนี้ ของชัยได้ฟ้องศาลให้\nชัยชาระหนี้ และศาลพิพากษาให้เกียรติชนะคดี เกียรติจึงนาเจ้าพนักงานบังคับคดีเข้ายึดที่ดินแปลงที่ชยั เคย\nทาสัญญาตีใช้หนี้ให้เชิดไปแล้ว เพื่อออกขายทอดตลาดนาเงินมาใช้หนี้เกียรติ\nเชิ ดรู ้ เรื่ องจึ ง ร้ องขัดทรั พย์โดยอ้า งว่า เชิ ดเป็ นเจ้าของที่ ดินแปลงนั้น เพราะชัยเอาที่ ดินนั้นตี ใช้หนี้ ใ ห้ ตน\nแล้ว เจ้าพนักงานบังคับคดีจึงไม่มีสิทธินาออกขายทอดตลาด\nดังนี้ ให้วินิจฉัยว่า เชิดจะร้องขัดทรัพย์ได้หรื อไม่ เพราะเหตุใด","rule":"มาตรา 1299 วรรคแรก ภายในบังคับแห่ งบทบัญญัติในประมวลกฎหมายนี้ หรื อกฎหมายอื่น ท่าน\nว่ า การได้ ม าโดยนิ ติ ก รรมซึ่ งอสั ง หาริ มทรั พ ย์ห รื อทรั พ ยสิ ท ธิ อัน เกี่ ย วกั บ อสั ง หาริ มทรั พ ย์ น้ ั นไม่\nบริ บูรณ์ เว้นแต่นิติกรรมจะได้ทาเป็ นหนังสื อและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่","application":"ตามกฎหมาย การได้มาซึ่งอสังหาริ มทรัพย์หรื อทรัพยสิ ทธิอนั เกี่ยวกับอสังหาริ มทรัพย์โดยทางนิ ติ\nกรรมนั้น จะบริ บู รณ์ เป็ นทรั พ ยสิ ท ธิ ไ ด้ จะต้องท าเป็ นหนัง สื อและจดทะเบี ย นการได้ม ากับ พนัก งาน\nเจ้าหน้าที่ ซึ่งถ้าฝ่ าฝื นจะมีผลเป็ นเพียงบุคคลสิ ทธิ ใช้กล่าวอ้างได้เฉพาะคู่สัญญาเท่านั้น ไม่สามารถยกขึ้น\nกล่าวอ้างต่อบุคคลภายนอกได้ (มาตรา 1299 วรรคแรก)\nกรณี ตามอุทาหรณ์ การที่ชยั ทาสัญญายกที่ดินมีโฉนดแปลงหนึ่ งตีใช้หนี้ ให้แก่เชิดนั้น ถือว่าเชิดเป็ นผูไ้ ด้มา\nซึ่งทรัพยสิ ทธิอนั เกี่ยวกับอสังหาริ มทรัพย์โดยทางนิ ติกรรม เมื่อปรากฏว่าสัญญาดังกล่าวไม่ได้จดทะเบียน\nกับ พนัก งานเจ้า หน้า ที่ นิ ติ ก รรมจึ ง ไม่ บ ริ บู ร ณ์ ใ นฐานะทรั พ ยสิ ท ธิ เชิ ด จะยกสั ญ ญานี้ ขึ้ น เป็ นข้อ ต่ อสู ้\nบุคคลภายนอกไม่ได้ แต่ยงั คงมีผลบังคับระหว่างชัยกับเชิดในฐานะบุคคลสิ ทธิตามมาตรา 1299 วรรคแรก\nดังนั้น เมื่อปรากฏข้อเท็จจริ งว่า เกียรติเจ้าหนี้ ของชัยได้ฟ้องศาลให้ชยั ชาระหนี้ และศาลได้พิพากษาให้\nเกียรติชนะคดี เกียรติจึงสามารถนาเจ้าพนักงานบังคับคดีเข้ายึดที่ดินแปลงที่ชยั เคยทาสัญญาตีใช้หนี้ ให้เชิด\nเพื่อออกขายทอดตลาดนาเงินมาใช้หนี้ เกียรติได้ เชิดจะร้องขัดทรัพย์โดยอ้างว่าเชิดเป็ นเจ้าของที่ดินแปลง\nนั้น เพราะชัย เอาที่ ดินนั้นตี ใ ช้หนี้ ใ ห้ตนแล้ว เจ้า พนัก งานบัง คับ คดี จึง ไม่ มี สิ ท ธิ นาออกขายทอดตลาด\nไม่ได้ เพราะสัญญานาอสังหาริ มทรั พย์คือที่ ดินดังกล่าวตี ใช้หนี้ ไม่ได้จดทะเบี ยนการได้มากับพนักงาน\nเจ้าหน้าที่ การโอนกรรมสิ ทธิ์ จึงถือว่าไม่บริ บูรณ์ในฐานะทรัพยสิ ทธิ เชิ ดจึ งเอาสัญญาดังกล่าวขึ้นต่ อสู ้\nเกียรติไม่ได้\nดังนั้นเกียรติซ่ ึงเป็ นเจ้าหนี้ ตามคาพิพากษา และเป็ นบุคคลภายนอกจึงมีสิทธิในที่ดินดีกว่าเชิด และ\nสามารถนายึดที่ดินพิพาทได้","conclusion":"สรุ ป เชิดจะร้องขัดทรัพย์ไม่ได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2555-1-3-13","year":"2555","semester":"ภาค 1","number":3,"page":13,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2555 ภาค 1 · ข้อ 3","sections":["1367","1368","1377"],"otherSections":["1380"],"question":"ข้ อ 3. พุธครอบครองที่ดินมือเปล่าแปลงหนึ่ งร่ วมกับนายศุกร์ เมื่อครอบครองไปได้หนึ่ งปี พุธกับศุกร์ ทา\nสัญญาเป็ นหนัง สื อตกลงขายส่ วนของตนให้กับ ศุ ก ร์ โดยพุ ธ ตกลงกับ ศุ ก ร์ ว่า ตนยัง ไม่ ต้องรื้ อถอนบ้า น\nออกไป คงอยู่อาศัยในที่ดินนั้นต่อไปได้ พุธอยู่ต่อมาได้หนึ่งปี พุธได้ขายที่ดินแปลงนั้นให้จนั ทร์ โดยจันทร์\nสุ จริ ต เพราะเห็นพุธอยู่ในที่ดินแปลงนั้นมานานแล้ว และจันทร์ เชื่อที่พุธบอกว่าศุกร์ เช่าที่ดินแปลงนั้นจาก\nพุธ ต่อมาเมื่อศุกร์ไปยืน่ ขอออกโฉนดที่ดิน จันทร์ได้มาคัดค้าน\nตามข้อเท็จจริ งนี้ ถ้าท่านเป็ นศาล จะวินิจฉัยคดีน้ ีอย่างไร เพราะเหตุใด","rule":"มาตรา 1367 บุ ค คลใดยึดถื อทรั พ ย์สิ น โดยเจตนาจะยึดถื อ เพื่ อตน ท่ า นว่า บุ ค คลนั้นได้ซ่ ึ ง สิ ท ธิ\nครอบครอง\nมาตรา 1368 บุคคลอาจได้มาซึ่งสิ ทธิครอบครองโดยผูอ้ ื่นยึดถือไว้ให้\nมาตรา 1377 วรรคหนึ่ ง ถ้า ผูค้ รอบครองสละเจตนาครอบครอง หรื อไม่ ยึดถื อทรั พ ย์สิ น ต่ อ ไป\nไซร้ การครอบครองย่อมสิ้ นสุ ดลง\nมาตรา 1380 การโอนไปซึ่ งการครอบครองย่อมเป็ นผลแม้ผูโ้ อนยังยึดถือทรัพย์สินอยู่ ถ้าผูโ้ อน\nแสดงเจตนาว่าต่อไปจะยึดถือทรัพย์สินนั้นแทนผูร้ ับโอน\nถ้าทรัพย์สินนั้นผูแ้ ทนของผูโ้ อนยึดถืออยู่ การโอนไปซึ่ งการครอบครองจะทาโดยผูโ้ อนสั่งผูแ้ ทนว่า ต่อไป\nให้ยดึ ถือทรัพย์สินไว้แทนผูร้ ับโอนก็ได้","application":"กรณี ตามอุทาหรณ์ การที่พุธทาสัญญาเป็ นหนังสื อตกลงขายที่ดินมือเปล่าส่ วนของตนให้กับศุก ร์\nนั้ น ถื อ ว่ า พุ ธ ได้ส ละการครอบครองในที่ ดิ น แล้ว สิ ท ธิ ก ารครอบครองที่ ดิ น ของพุ ธ จึ ง สิ้ น สุ ด ลงตาม\nมาตรา 1377 วรรคแรก และถึงแม้พุธจะยังคงอาศัยอยู่ในที่ดินดังกล่าวต่อไป การโอนที่ดินดังกล่าวก็เป็ นผล\nแล้ว เพราะเป็ นการโอนตามมาตรา 1380 ซึ่งบัญญัติวา่ การโอนไปซึ่งการครอบครองย่อมเป็ นผลแม้ผโู ้ อนยัง\nยึดถือทรัพย์สินอยู่ ถ้าผูโ้ อนแสดงเจตนาว่าต่อไปจะยึดถือทรัพย์สินนั้นแทนผูร้ ับโอน และกรณี น้ ีถือเป็ นกรณี\nที่ศุกร์ได้สิทธิครอบครองที่ดินโดยมีผอู ้ ื่นยึดถือไว้ให้ตามมาตรา 1368\nดั ง นั้ น แม้พุ ธ จะยัง คงอาศั ย อยู่ ใ นที่ ดิ น แปลงนั้ นต่ อ ไม่ ก็ ไ ม่ ท าให้ ไ ด้ สิ ท ธิ ค รอบครองตาม\nมาตรา 1367 ศุกร์ยอ่ มมีสิทธิครอบครองที่ดินมือเปล่าแปลงนั้นดีกว่าพุธ\nเมื่อปรากฏข้อเท็จจริ งว่า ต่อมาศุกร์ ได้ไปยื่นขอออกโฉนดที่ดินแปลงนั้น กรณี น้ ี ถึงแม้พุธจะขายที่ดินแปลง\nนั้นให้จนั ทร์ แล้ว โดยจันทร์ สุจริ ต เพราะเห็นพุธอยู่ในที่ดินแปลงนั้นมานานแล้ว และเชื่อที่พุธบอกว่าศุกร์\nเช่าที่ดินแปลงนั้นจากพุธก็ตาม แต่เมื่อที่ดินแปลงนั้นเป็ นของศุกร์ซ่ ึ งมีสิทธิยื่นขอออกโฉนดได้ จันทร์จึงไม่\nมีสิทธิคดั ค้าน เพราะถือว่าจันทร์รับโอนที่ดินแปลงนั้นมาจากผูท้ ี่ไม่มีสิทธิในที่ดินแต่อย่างใด","conclusion":"สรุ ป ถ้าข้าพเจ้าเป็ นศาล จะวินิจฉัยคดีน้ ี ว่าศุกร์ มีสิทธิ ที่จะยื่นขอออกโฉนดที่ดินแปลงนี้ ได้ เพราะ\nที่ดินเป็ นของศุกร์ จันทร์ไม่มีสิทธิคดั ค้าน","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2555-1-4-15","year":"2555","semester":"ภาค 1","number":4,"page":15,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2555 ภาค 1 · ข้อ 4","sections":["1382","1387","1401"],"otherSections":[],"question":"ข้ อ 4. แดงเป็ นเจ้าของที่ดินแปลงหนึ่ ง แดงให้ดาเช่าที่ดินปลูกบ้านอาศัยอยู่ เมื่อเข้าไปปลูกบ้านบนที่ดิน\nแปลงนั้น ไฟฟ้ายังเข้าไม่ถึง แดงได้บอกให้ดาวางเสา สายไฟฟ้าผ่านที่ดินของขาวเข้าไปใช้ในที่ดินได้ โดย\nแดงบอกกับดาว่าตนได้ขออนุญาตขาวเจ้าของที่ดินแล้ว แต่ความจริ งไม่ใช่ แดงไม่เคยขอหรื อบอกขาวเลย ดา\nจึงได้วางเสาและสายไฟฟ้าผ่านที่ดินของขาว นอกจากนั้นยังได้สร้างศาลาที่พกั ไว้หน้าที่ดินของขาว ดาเช่า\nที่ ดินปลูก บ้า นและวางสายไฟฟ้ า มาได้ห้า ปี เหลื องได้ม าขอซื้ อบ้า นหลัง นี้ จากดาและเช่ า ที่ ดินของแดง\nต่อ เหลืองซื้ อบ้านและอยู่อาศัยในที่ดินแปลงนี้ ใช้เสาสายไฟฟ้าผ่านที่ดินของขาว และใช้ศาลาที่พกั หน้า\nที่ ดิ น ของขาวเพื่ อ ขึ้ น รถยนต์ โ ดยสารประจ ามาได้ เ จ็ ด ปี ขาวได้ ม าแจ้ ง ให้ เ หลื อ งรื้ อเสาไฟฟ้ า และ\nสายไฟฟ้า และศาลาที่พกั ออกไปจากที่ดินของตน และทาที่ดินให้เป็ นดังเดิม มิฉะนั้นจะฟ้องร้องต่อศาล\nให้ท่านให้คาแนะนาต่อเหลืองว่า เหลืองจะต้องรื้ อเสา สายไฟฟ้า และศาลาออกไปหรื อไม่ เพราะ\nเหตุใด","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1387 อสังหาริ มทรัพย์อาจต้องตกอยู่ในภาระจายอมอันเป็ นเหตุให้เจ้าของต้องยอมรับกรรม\nบางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรื อต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยูใ่ นกรรมสิ ทธิ์ทรัพย์สิน\nนั้นเพื่อประโยชน์แก่อสังหาริ มทรัพย์อื่น\nมาตรา 1401 ภาระจายอมอาจได้มาโดยอายุความ ท่านให้นาบทบัญญัติว่าด้วยอายุความได้สิทธิ อนั\nกล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บงั คับโดยอนุโลม","application":"โดยหลัก การได้ภาระจายอมโดยอายุความ เป็ นการได้ทรัพยสิ ทธิเกี่ยวกับอสังหาริ มทรัพย์โดยทาง\nอื่ น นอกจากนิ ติ ก รรม ซึ่ งตามมาตรา 1401 บัญ ญัติ ใ ห้ น าบทบัญ ญัติ ว่ า ด้ ว ยอายุ ค วามได้ สิ ท ธิ ต าม\nมาตรา 1387 มาใช้บ ัง คับ โดยอนุ โ ลม กล่ า วคื อ ต้อ งเป็ นการครอบครองทรั พ ย์สิ น ของผู ้อื่ น โดยความ\nสงบ เปิ ดเผย และเจตนาเป็ นเจ้าของและครอบครองติดต่อกันเป็ นเวลา 10 ปี\nแต่อย่างไรก็ตาม ภาระจายอมจะเกิดมีข้ ึนได้ก็เพื่อประโยชน์แก่อสังหาริ มทรัพย์อื่นซึ่ งเรี ยกว่าสามยทรัพย์\nเท่านั้น ตามมาตรา 1387 ดังนั้น ถ้าเป็ นการใช้อสังหาริ มทรัพย์เพื่อประโยชน์ส่วนตัวแม้จะใช้ติดต่อกันนาน\nเกินกว่า 10 ปี ก็ไม่ทาให้เกิดภาระจายอมโดยอายุความขึ้นได้\nกรณีตามอุทาหรณ์ การที่แดงได้บอกให้ดาวางเสาและสายไฟฟ้าผ่านที่ดินของขาวเข้าไปใช้ในที่ดินได้ โดย\nแดงบอกกับดาว่าตนได้ขออนุญาตขาวเจ้าของที่ดินแล้ว แต่ความจริ งแดงไม่เคยขอหรื อบอกขาวเลย ดาจึง\nได้วางเสาและสายไฟฟ้าผ่านที่ดินของขาวนั้น ถือเป็ นกรณี ที่ดาไม่ได้มีเจตนาจะยึดถือเป็ นเจ้าของที่ดินของ\nขาว เพื่อให้ได้ภาระจายอมแต่อย่างใด เพราะการที่แดงบอกกับดาว่าตนได้ขออนุญาตขาวแล้วนั้น แสดงว่า\nการวางเสาและสายไฟฟ้าของดา เป็ นการแสดงเจตนาขออาศัยวางผ่านที่ดินของขาวเท่านั้น จึงไม่ก่อให้เกิด\nเจตนาปรปักษ์ อันจะทาให้ได้ภาระจายอมมาโดยอายุความตามมาตรา 1401 ประกอบมาตรา 1382\nส่ วนกรณี ศาลาที่พกั นั้น ถือเป็ นการที่ดาสร้างขึ้นเพื่อประโยชน์ส่วนตัว ไม่ใช่เป็ นการใช้ที่ดินของขาวเพื่อ\nประโยชน์แก่อสังหาริ มทรัพย์อื่นแต่อย่างใด จึงไม่ก่อให้เกิดภาระจายอม ดังนั้นแม้วา่ ดาจะใช้ศาลาที่พกั นั้น\nนานเท่าใด ก็ไม่ทาให้ได้ภาระจายอมเหนื อที่ดินของขาวโดยอายุความปรปั กษ์ตามมาตรา 1401 ประกอบ\nมาตรา 1382 และมาตรา 1387\nดังนั้น แม้จะปรากฏข้อเท็จจริ งว่า เหลืองได้มาขอซื้อบ้านต่อจากดาและเช่าที่ดินแดงต่อโดยยังคงใช้\nเสาและสายไฟฟ้าผ่านที่ดินของขาว และใช้ศาลาที่พกั หน้าที่ดินของขาวเพื่อขึ้นรถยนต์โดยสารประจามาได้\nเจ็ดปี ก็ตาม เหลืองก็ไม่สามารถนับอายุความภาระจายอมต่อจากดาได้ เพราะการใช้ที่ดินของขาววางเสาและ\nสายไฟฟ้าดาไม่ได้มีเจตนาปรปักษ์ ส่ วนการใช้ศาลาที่พกั ก็ไม่ก่อให้เกิดภาระจายอม ดังนั้นเมื่อขาวเจ้าของ\nที่ดินได้มาแจ้งให้เหลืองรื้ อเสาและสายไฟฟ้า รวมทั้งศาลาที่พกั ออกไปจากที่ดินของตน และทาที่ดินให้เป็ น\nดังเดิม เหลืองจะต้องรื้ อเสาไฟ สายไฟฟ้า และศาลาที่พกั ออกไป","conclusion":"สรุ ป ข้าพเจ้าจะให้คาแนะนาต่อเหลืองว่า เหลืองจะต้องรื้ อเสาไฟฟ้ า สายไฟฟ้า และศาลาออกไป\nจากที่ดินของขาว\nการสอบไล่ ภาคฤดูร้อน ปี การศึกษา 2554\nข้อสอบกระบวนวิชา LAW2001 (LA 201),(LW 204)\nกฎหมายแพ่งและพาณิชย์ว่าด้วยทรัพย์\nคาแนะนา ข้อสอบเป็ นอัตนัยล้วนมี 4 ข้อ","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2554-s-1-17","year":"2554","semester":"ภาคฤดูร้อน","number":1,"page":17,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2554 ภาคฤดูร้อน · ข้อ 1","sections":["1299"],"otherSections":[],"question":"ข้ อ 1. เบี้ ย วท าสั ญญาอนุ ญาตให้ก ลมท าทางภาระจายอมเป็ นถนนผ่า นที่ ดิ นของเบี้ ย ว โดยไม่ มี ก าหนด\nระยะเวลา แต่สัญญาดัง กล่า วไม่ ไ ด้จดทะเบี ย นกับ พนัก งานเจ้า หน้า ที่ หลัง จากกลมใช้ท างภาระจายอม\nได้ 5 ปี เบี้ยวก็ถึงแก่ความตาย แบนบุตรของเบี้ยวได้จดทะเบียนรับมรดกที่ดินแปลงนั้นในฐานะทายาทโดย\nธรรม และแบนได้ทาสัญญาขายที่ดินดังกล่าวให้กบั สมปอง\nหลังจากจดทะเบียนรับโอนกรรมสิ ทธิ์แล้ว สมปองจึงห้ามไม่ให้กลมใช้ทางภาระจายอมอีกต่อไป แต่กลม\nอ้างสัญญาที่ตนทาไว้กบั เบี้ยวขึ้นต่อสู ้วา่ ตนยังสามารถใช้ทางภาระจายอมได้ต่อไป\nดังนี้ สมปองจะห้ามไม่ให้กลมใช้ทางภาระจายอมต่อไปได้หรื อไม่ และข้อต่อสู้ของกลมรับฟั งได้\nหรื อไม่ เพราะเหตุใด","rule":"มาตรา 1299 ภายในบังคับแห่ งบทบัญญัติในประมวลกฎหมายนี้ หรื อกฎหมายอื่ น ท่านว่า การ\nได้มาโดยนิ ติกรรมซึ่งอสังหาริ มทรัพย์หรื อทรัพยสิ ทธิ อนั เกี่ยวกับอสังหาริ มทรัพย์น้ นั ไม่บริ บูรณ์ เว้นแต่นิติ\nกรรมจะได้ทาเป็ นหนังสื อและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่","application":"ตามกฎหมาย การได้มาซึ่งอสังหาริ มทรัพย์หรื อทรัพยสิ ทธิอนั เกี่ยวกับอสังหาริ มทรัพย์โดยทางนิติ\nกรรมนั้น จะบริ บู รณ์ เป็ นทรั พ ยสิ ท ธิ ไ ด้ จะต้องท าเป็ นหนัง สื อและจดทะเบี ย นการได้ม ากับ พนัก งาน\nเจ้าหน้าที่ ซึ่งถ้าฝ่ าฝื นจะมีผลเป็ นเพียงบุคคลสิ ทธิ ใช้กล่าวอ้างได้เฉพาะคู่สัญญาเท่านั้น ไม่สามารถยกขึ้น\nกล่าวอ้างต่อบุคคลภายนอกได้ (มาตรา 1299 วรรคแรก)\nกรณี ตามอุทาหรณ์ การที่เบี้ยวทาสัญญาอนุญาตให้กลมทาทางภาระจายอมเป็ นถนนผ่านที่ดินของเบี้ยวโดย\nไม่ มี ก าหนดระยะเวลานั้น กลมจึ ง เป็ นผูไ้ ด้ม าซึ่ ง ทรั พ ยสิ ท ธิ อัน เกี่ ย วกับ อสั ง หาริ ม ทรั พ ย์โ ดยทางนิ ติ\nกรรม แต่เมื่อปรากฏว่าสัญญาดังกล่าวไม่ได้จดทะเบียนกับพนักงานเจ้าหน้าที่ นิ ติกรรมจึงไม่บริ บูรณ์ใน\nฐานะทรัพยสิ ทธิ และจะยกขึ้นเป็ นข้อต่อสู ้บุคคลภายนอกไม่ได้ แต่ยงั คงมีผลบังคับระหว่างเบี้ยวกับกลม\nซึ่งเป็ นคู่สัญญาในฐานะบุคคลสิ ทธิตามมาตรา 1299 วรรคแรก\nต่อมาเมื่อเบี้ยวถึงแก่ความตาย แบนบุตรของเบี้ยวได้จดทะเบียนรับมรดกที่ดินแปลงนั้นในฐานะทายาทโดย\nธรรม อันเป็ นการรับทรัพย์มรดกตามกฎหมายว่าด้วยมรดก ดังนั้น แบนผูร้ ับมรดกจึงต้องรับไปทั้งสิ ทธิ\nและหน้าที่ของเบี้ยวเจ้ามรดกที่มีต่อกลมดังกล่าวด้วย\nอย่างไรก็ตาม เมื่อปรากฏข้อเท็จจริ งว่า แบนได้ทาสัญญาขายที่ดินดังกล่าวให้กบั สมปอง และสมปองได้จด\nทะเบี ย นรั บ โอนกรรมสิ ท ธิ์ แล้ว สมปองย่ อ มเป็ นเจ้า ของกรรมสิ ท ธิ์ ในที่ ดิ น แปลงนั้ น และถื อ เป็ น\nบุคคลภายนอก\nดังนั้น เมื่อภาระจายอมดังกล่าวไม่บริ บูรณ์ในฐานะทรัพยสิ ทธิ จึงไม่สามารถบังคับใช้กบั สมปอง\nซึ่ งเป็ นบุคคลภายนอกได้ สมปองในฐานะเจ้าของกรรมสิ ทธิ์ จึงมีสิทธิ ห้ามไม่ให้กลมใช้ทางภาระจายอม\nต่อไปได้ และข้อต่อสู ้ของกลมที่วา่ ตนทาสัญญาไว้กบั เบี้ยวจึงยังสามารถใช้ทางภาระจายอมได้ต่อไปนั้นรับ\nฟั งไม่ได้ เพราะกลมไม่สามารถยกสัญญาที่ ไม่บริ บูรณ์ น้ ันขึ้นต่อสู ้กับสมปองได้ตามเหตุผลที่ กล่าวแล้ว\nข้างต้น","conclusion":"สรุป สมปองจะห้ามไม่ให้กลมใช้ทางภาระจายอมต่อไปได้ และข้อต่อสู้ของกลมรับฟังไม่ได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2554-s-2-18","year":"2554","semester":"ภาคฤดูร้อน","number":2,"page":18,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2554 ภาคฤดูร้อน · ข้อ 2","sections":["144"],"otherSections":["1332"],"question":"ข้อ 2. มัน่ ได้ซ้ือพระเครื่ ององค์หนึ่งในราคา 5,000 บาท จากร้านพุทธศิลป์ ซึ่งเปิ ดร้านจาหน่ายพระเครื่ องและ\nวัตถุมงคลที่ขา้ งวัดมหาธาตุ ท่าพระจันทร์ ซึ่งเป็ นแหล่งจาหน่ายพระเครื่ องและวัตถุมงคลต่างๆ โดยมัน่ ไม่รู้\nว่าพระเครื่ ององค์ดงั กล่าวเป็ นของเมฆที่ถูกคนร้ายขโมยไป\nและนาไปขายที่ร้านพุทธศิลป์ ในราคา 2,000 บาท หลังจากซื้ อพระเครื่ องดังกล่าวแล้ว มัน่ ได้นาไปใส่ กรอบ\nทองค าเป็ นเงิ น 20,000 บาท ต่ อ มาเจ้า หน้า ที่ ต ารวจจับ คนร้ า ยได้ และสื บ ทราบว่า พระของกลางอยู่ ที่\nมัน่ ดังนี้ ให้วินิจฉัยว่า เมฆจะเรี ยกให้มนั่ คืนพระเครื่ ององค์น้ นั พร้อมกรอบทองให้กบั ตนได้หรื อไม่ และ\nระหว่างมัน่ กับเมฆมีสิทธิเรี ยกร้องใดๆต่อกันได้บา้ ง เพราะเหตุใด","rule":"มาตรา 144 ส่ วนควบของทรัพย์ หมายความว่า ส่ วนซึ่งโดยสภาพแห่งทรัพย์หรื อโดยจารี ตประเพณี\nแห่ งท้องถิ่นเป็ นสาระสาคัญในความเป็ นอยู่แห่ งทรัพย์น้ นั และไม่อาจแยกจากกันได้นอกจากจะทาลาย ทา\nให้บุบสลาย หรื อทาให้ทรัพย์น้ นั เปลี่ยนแปลงรู ปทรงหรื อสภาพไป\nเจ้าของทรัพย์ยอ่ มมีกรรมสิ ทธิ์ในส่ วนควบของทรัพย์น้ นั\nมาตรา 1332 บุคคลผูซ้ ้ื อทรัพย์สินมาโดยสุ จริ ตในการขายทอดตลาด หรื อในท้องตลาด หรื อจาก\nพ่อค้าซึ่งขายของชนิดนั้น ไม่จาต้องคืนให้แก่เจ้าของแท้จริ ง เว้นแต่เจ้าของจะชดใช้ราคาที่ซ้ือมา","application":"ตามกฎหมาย บุ ค คลผู ้ซ้ื อ ทรั พ ย์สิ น มาโดยสุ จ ริ ต จากการขายทอดตลาดของเอกชน หรื อ ใน\nท้องตลาด หรื อจากพ่อค้าซึ่ งขายของชนิ ดนั้น ย่อมได้รับความคุม้ ครองตามมาตรา 1332 คือ แม้เจ้าของ\nทรัพย์สินที่แท้จริ งจะติดตามทวงคืน ก็ไม่จาต้องคืนทรัพย์สินให้แก่เจ้าของ เว้นแต่เจ้าของทรัพย์สินนั้นจะ\nชดใช้ราคาที่ตนซื้อมา\nกรณีตามอุทาหรณ์ การที่มนั่ ซื้อพระเครื่ องดังกล่าวจากร้านพุทธศิลป์ ซึ่งเปิ ดร้านจาหน่ายพระเครื่ องและวัตถุ\nมงคลที่ขา้ งวัดมหาธาตุ ท่าพระจันทร์ ซึ่งเป็ นแหล่งจาหน่ายพระเครื่ องและวัตถุมงคลต่างๆ โดยมัน่ ไม่รู้ว่า\nพระเครื่ ององค์น้ นั เป็ นของเมฆที่ถูกคนร้ายขโมยไปและนาไปขายที่ร้านพุทธศิลป์ นั้น มัน่ ย่อมเป็ นบุคคลผู ้\nซื้ อทรั พ ย์สิ นมาโดยสุ จริ ตจากท้องตลาด และจากพ่ อค้าซึ่ งขายสิ นค้า ชนิ ดนั้น ดัง นั้นมัน่ จึ ง ได้รับ ความ\nคุม้ ครองตามมาตรา 1332 คือ มัน่ ไม่จาต้องคืนพระเครื่ ององค์น้ นั ให้กบั เมฆ แม้เมฆจะเป็ นเจ้าของที่แท้จริ งก็\nตาม เว้นเสี ยแต่ว่าเมฆจะชดใช้ราคาพระเครื่ องที่มนั่ ได้ซ้ื อมา คือ 5,000 บาท เมฆจึงจะสามารถเรี ยกให้มนั่\nคืนพระเครื่ ององค์น้ นั ได้\nส่ วนกรณี ที่มนั่ นาพระเครื่ องไปใส่ กรอบทองคาเป็ นเงิ น 20,000 บาทนั้น เมื่อปรากฏว่ากรอบพระทองคา\nไม่ใช่สาระสาคัญในความเป็ นอยู่ของพระเครื่ อง จึงไม่ถือเป็ นส่ วนควบของพระเครื่ อง ตามมาตรา 144 อัน\nจะทาให้เมฆเจ้าของทรัพย์ได้กรรมสิ ทธิ์ในกรอบพระทองคาด้วยแต่อย่างใด\nดังนั้น กรอบพระทองคาจึงยังคงเป็ นกรรมสิ ทธิ์ ของมัน่ เมฆไม่มีสิทธิ เรี ยกเอากรอบพระทองคา\nจากมัน่","conclusion":"สรุป หากเมฆต้องการจะเรี ยกให้มนั่ คืนพระเครื่ อง จะต้องชดใช้เงินให้แก่มนั่ 5,000 บาท ส่วนกรอบ\nพระทองคานั้น เมฆไม่มีสิทธิเรี ยกเอากรอบพระทองคาจากมัน่","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2554-s-3-19","year":"2554","semester":"ภาคฤดูร้อน","number":3,"page":19,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2554 ภาคฤดูร้อน · ข้อ 3","sections":["1382"],"otherSections":["1384"],"question":"ข้อ 3. นายแมนเข้าไปทานาในที่ดินมีโฉนดแปลงหนึ่ งของนางมัง่ มีมาได้ 4 ปี ต่อมานายแมนถูกศาลพิพากษา\nจาคุกเป็ นเวลา 1 ปี 6 เดือน เมื่อออกจากคุกแล้ว นายแมนได้เข้าไปครอบครองทานาในที่ดินของนางมัง่ มี\nอีก 4 ปี 6 เดือน\nให้ท่ า นวินิจฉัย ว่า นายแมนอ้า งกรรมสิ ท ธิ์ ในการครอบครองปรปั ก ษ์บ นที่ ดินของนางมั่ง มี ไ ด้\nหรื อไม่ จงอธิบาย","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1384 “ถ้าผูค้ รอบครองขาดยึดถือทรัพย์สินโดยไม่สมัคร และได้คืนภายในเวลาหนึ่งปี นับแต่\nวันขาดยึดถือ หรื อได้คืนโดยฟ้องคดีภายในกาหนดนั้นไซร้ ท่านมิให้ถือว่าการครอบครองสะดุดหยุดลง”","application":"กรณี ตามอุทาหรณ์ โดยหลักแล้วการได้ก รรมสิ ทธิ์ ในอสัง หาริ มทรัพย์โดยการครอบครองปรปั ก ษ์ตาม\nมาตรา 1382 จะประกอบด้วยหลักเกณฑ์ดงั นี้\n1. เป็ นทรัพย์สินของผูอ้ ื่น โดยผูอ้ ื่นมีกรรมสิ ทธิ์\n2. ได้ครอบครองโดยความสงบ\n3. ครอบครองโดยเปิ ดเผย\n4. ครอบครองโดยเจตนาเป็ นเจ้าของ\n5. ครอบครองติดต่อกันมาเป็ นเวลา 10 ปี\nสาหรับการครอบครองติดต่อกันนั้น จะต้องเป็ นกรณี ที่ผคู ้ รอบครองได้ครอบครองหรื อยึดถือทรัพย์สินนั้น\nตลอดเรื่ อยมาโดยไม่มีเจตนาสละการครอบครอง หรื อขาดการยึดถือโดยใจสมัครในบางช่วงบางตอน และ\nถ้าหากเป็ นการขาดการยึดถือโดยไม่สมัครใจ เพราะมีเหตุมาขัดขวาง กฎหมายถือว่าการขาดการยึดถือนั้น\nไม่ ท าให้อายุค วามการครอบครองสะดุ ด หยุดลง หากได้ท รั พ ย์สิ นคื น ภายใน 1 ปี นับ แต่วนั ที่ ข าดการ\nยึดถือ ทั้งนี้ตามมาตรา 1384\nกรณีตามอุทาหรณ์ ประเด็นที่ตอ้ งวินิจฉัยมีวา่ นายแมนจะอ้างกรรมสิ ทธิ์ในการครอบครองปรปักษ์บนที่ดิน\nของนางมัง่ มีได้หรื อไม่ เห็นว่า การที่นายแมนเข้าไปครอบครองปรปั กษ์ทานาในที่ดินมีโฉนดของนางมัง่ มี\nมาได้ 4 ปี และต่อมาได้ถูกศาลพิพากษาจาคุกนั้น ถือเป็ นกรณี ที่นายแมนขาดการยึดถือที่ดินโดยไม่สมัค ร\nใจ เนื่องจากมีเหตุมาขัดขวางหรื อไม่มีเจตนาสละการครอบครอง แต่อย่างไรก็ตาม เมื่อปรากฏว่านายแมน\nไม่อาจกลับเข้าครอบครองที่ดินอีกได้ภายใน 1 ปี นับแต่วนั ที่ขาดการยึดถือ เนื่องจากศาลพิพากษาจาคุกนาย\nแมน 1 ปี 6 เดือน จึงมีผลทาให้การครอบครองของนายแมนสิ้ นสุ ดลง ตามมาตรา 1384\nดังนั้น แม้ต่อมานายแมนจะพ้นโทษจาคุก และกลับเข้าครอบครองปรปั กษ์ที่ดินของนางมัง่ มีอีก นายแมนก็\nไม่ ส ามารถจะน าระยะเวลาการครอบครองเดิ ม (4 ปี ) มานั บ รวมกั บ การครอบครองขณะตนถู ก\nจาคุก (1 ปี 6 เดือน) และภายหลังออกจากคุก (4 ปี 6 เดือน) ได้ หากนายแมนจะนับก็ตอ้ งเริ่ มนับตั้งแต่เมื่อ\nออกจากคุกแล้วมาครอบครองใหม่ จึงเท่ากับนายแมนเพิ่งครอบครองปรปั กษ์ได้เพียง 4 ปี 6 เดือ ซึ่งยังไม่\nครบ 10 ปี นายแมนจึ ง ยั ง ไม่ ไ ด้ ก รรมสิ ทธิ์ ในการครอบครองปรปั ก ษ์ ที่ ดิ น ของนางมั่ ง มี ต าม\nมาตรา 1382 ดังนั้น นายแมนจะอ้างกรรมสิ ทธิ์ในการครอบครองปรปักษ์ที่ดินของนางมัง่ มีไม่ได้","conclusion":"สรุป นายแมนอ้างกรรมสิ ทธิ์ในการครอบครองปรปักษ์บนที่ดินของนางมัง่ มีไม่ได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2554-s-4-20","year":"2554","semester":"ภาคฤดูร้อน","number":4,"page":20,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2554 ภาคฤดูร้อน · ข้อ 4","sections":["1387","1299"],"otherSections":["1399"],"question":"ข้อ 4. จันทร์จดทะเบียนภาระจายอมให้องั คารใช้น้ าในบ่อน้ าซึ่งอยูใ่ นที่ดินของจันทร์ได้ หลังจากที่องั คารใช้\nน้ าจากบ่อของจันทร์ มาได้ 5 ปี อังคารก็ไม่เคยมาใช้น้ าจากบ่อน้ านี้ อีกถึง 5 ปี ต่อมาอังคารขายที่ดินให้กับ\nพุธ เมื่อพุธซื้อที่ดินแล้วจึงมาใช้น้ าในที่ดินของจันทร์\nดังนี้ จันทร์จะไม่อนุญาตให้พุธนาน้ าจากบ่อน้ าของตนไปใช้ได้หรื อไม่ จงอธิบาย","rule":"มาตรา 1387 อสังหาริ มทรัพย์อาจต้องตกอยู่ในภาระจายอมอันเป็ นเหตุให้เจ้าของต้องยอมรับกรรม\nบางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรื อต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยูใ่ นกรรมสิ ทธิ์ทรัพย์สิน\nนั้นเพื่อประโยชน์แก่อสังหาริ มทรัพย์อื่น\nมาตรา 1399 ภาระจายอมนั้น ถ้ามิได้ใช้สิบปี ท่านว่าย่อมสิ้ นไป","application":"ตามกฎหมาย ภาระจ ายอมนั้ นเป็ นทรั พ ย์ สิ นที่ มี ข้ ึ นเพื่ อ ประโยชน์ กั บ อสั ง หาริ มทรั พ ย์\nอื่ น (มาตรา 1387) ดัง นั้น ภาระจ ายอมจึ ง ตกติ ด ไปกับ อสั ง หาริ ม ทรั พ ย์ท้ ัง ภารทรั พ ย์แ ละสามยทรั พ ย์\nเสมอ ไม่ว่าอสังหาริ มทรัพย์ท้ งั สองนั้นจะโอนไปเป็ นของบุคคลใด เว้นแต่จะตกลงกันเป็ นอย่างอื่น และ\nหากไม่ได้ใช้ภาระจายอมติดต่อกันเป็ นเวลา 10 ปี ภาระจายอมนั้นย่อมระงับสิ้ นไปตามมาตรา 1399 ซึ่ งถือ\nเป็ นอายุความเสี ยสิ ทธิ\nกรณี ตามอุทาหรณ์ การที่จนั ทร์ จดทะเบียนภาระจายอมให้องั คารมีสิทธิ ใช้น้ าในบ่อน้ า ซึ่งอยู่ในที่ดินของ\nจันทร์ ได้น้ นั ภาระจายอมดังกล่าวย่อมบริ บูรณ์เป็ นทรัพยสิ ทธิ (มาตรา 1299 วรรคแรก) และการที่องั คาร\nได้ใช้น้ าจากบ่อน้ าในที่ดินของจันทร์ เพียง 5 ปี แล้วก็ไม่เคยมาใช้น้ าจากบ่อน้ านี้ อีกเลยเป็ นเวลาถึง 5 ปี\nนั้น เมื่อปรากฏว่าการที่ไม่ได้ใช้ภาระจายอมนั้นยังไม่ถึง 10 ปี จึงยังไม่มีผลทาให้ภาระจายอมที่มีอยู่ระงับ\nไปตามมาตรา 1399\nและเมื่อปรากฏข้อเท็จจริ งว่าต่อมาอังคารขายที่ดินให้กบั พุธ พุธผูร้ ับโอนที่ดินมาจึงเป็ นเจ้าของกรรมสิ ทธิ์\nในที่ ดิ น และมี สิ ท ธิ ใ นภาระจ ายอมดั ง กล่ า ว คื อ มี สิ ท ธิ เ ข้ า ไปใช้ น้ าจากบ่ อ น้ าในที่ ดิ น ของจั น ทร์\nได้ (มาตรา 1387) ดั ง นั้ น เมื่ อ ภาระจ ายอมดั ง กล่ า วเป็ นทรั พ ยสิ ท ธิ ผู ก พัน อยู่ กั บ ทรั พ ย์สิ นที่ เ ป็ น\nอสังหาริ มทรัพย์ จันทร์จึงไม่มีสิทธิหา้ มพุธไม่ให้มาใช้น้ าจากบ่อน้ าซึ่งอยูใ่ นที่ดินของตนได้","conclusion":"สรุป จันทร์จะไม่อนุญาตให้พุธนาน้ าจากบ่อน้ าของตนไปใช้ไม่ได้\nการสอบไล่ภาค 1 ปี การศึกษา 2554\nข้อสอบกระบวนวิชา LAW2001 (LA 201),(LW 204)\nกฎหมายแพ่งและพาณิชย์ว่าด้วยทรัพย์\nคาแนะนา ข้อสอบเป็ นอัตนัยล้วนมี 4 ข้อ","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2554-1-1-22","year":"2554","semester":"ภาค 1","number":1,"page":22,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2554 ภาค 1 · ข้อ 1","sections":["144","146","1299"],"otherSections":[],"question":"ข้อ 1. เข้มทาสัญญาอนุญาตให้ป้อมสร้างบ้านอยูใ่ นที่ดินมีโฉนดของตนเป็ นเวลา 20 ปี โดยสัญญามีขอ้ ความ\nระบุว่า เมื่อครบกาหนด 20 ปี แล้วให้บา้ นตกเป็ นกรรมสิ ทธิ์ ของเข้มเจ้าของที่ดินทันที แต่สัญญาดังกล่าว\nไม่ ไ ด้จดทะเบี ย นกับ พนัก งานเจ้า หน้า ที่ หลัง จากป้ อมสร้ า งบ้า นอยู่ใ นที่ ดิ นของเข้ม ครบก าหนด 20 ปี\nแล้ว เข้มแจ้งให้ป้อมย้ายออกไปจากบ้านและที่ดินนั้น เพราะต้องการจะขายบ้านและที่ดินนั้น\nแต่ป้อมยังคงอาศัยอยู่ในบ้านและที่ดินต่อไป หลังจากนั้นอี ก 5 เดือนเข้มได้ทาสัญญาและจดทะเบียนกับ\nพนักงานเจ้าหน้าที่ขายบ้านพร้อมที่ดินนั้นให้แหม่ม เมื่อป้อมรู ้เรื่ องดังกล่าว ป้อมจึงทาสัญญาขายบ้านหลัง\nนั้นให้แตน โดยให้แตนรื้ อถอนบ้านออกไป ดังนี้\nให้วินิจฉัยว่า แตนจะรื้ อถอนบ้านออกไปได้หรื อไม่ และระหว่างแตนกับแหม่มผูใ้ ดมีกรรมสิ ทธิ์ใน\nบ้านพิพาทดีกว่ากัน เพราะเหตุใด","rule":"มาตรา 144 ส่ วนควบของทรัพย์ หมายความว่า ส่ วนซึ่งโดยสภาพแห่งทรัพย์หรื อโดยจารี ตประเพณี\nแห่ งท้องถิ่นเป็ นสาระสาคัญในความเป็ นอยู่ของทรัพย์น้ นั และไม่อาจแยกจากกันได้นอกจากจะทาลาย ทา\nให้บุบสลาย หรื อทาให้ทรัพย์น้ นั เปลี่ยนแปลงรู ปทรงหรื อสภาพไป\nเจ้าของทรัพย์ยอ่ มมีกรรมสิ ทธิ์ในส่ วนควบของทรัพย์น้ นั\nมาตรา 146 ทรัพย์ซ่ ึ งติดกับที่ดินหรื อติดกับโรงเรื อนเพียงชั่วคราวไม่ถือว่าเป็ นส่ วนควบกับที่ ดิน\nหรื อโรงเรื อนนั้น ความข้อนี้ ให้ใช้บงั คับแก่โรงเรื อนหรื อสิ่ งปลูกสร้างอย่างอื่น ซึ่งผูม้ ีสิทธิในที่ดินของผูอ้ ื่น\nใช้สิทธิน้ นั ปลูกสร้างไว้ในที่ดินนั้นด้วย\nมาตรา 1299 วรรคแรก ภายในบังคับแห่ งบทบัญญัติในประมวลกฎหมายนี้ หรื อกฎหมายอื่น ท่าน\nว่า การได้มาโดยนิ ติกรรมซึ่งอสังหาริ มทรัพย์หรื อทรัพยสิ ทธิ อนั เกี่ยวกับอสังหาริ มทรัพย์น้ นั ไม่บริ บูรณ์ เว้น\nแต่นิติกรรมจะได้ทาเป็ นหนังสื อและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่","application":"ตามกฎหมาย การได้มาซึ่งอสังหาริ มทรัพย์หรื อทรัพยสิ ทธิอนั เกี่ยวกับอสังหาริ มทรัพย์โดยทางนิ ติ\nกรรมนั้น จะบริ บู ร ณ์ เ ป็ นทรั พ ยสิ ท ธิ ไ ด้ จะต้อ งท าเป็ นหนัง สื อ และจดทะเบี ย นการได้ม ากับ พนัก งาน\nเจ้าหน้าที่ ซึ่งถ้าฝ่ าฝื นจะมีผลเป็ นเพียงบุคคลสิ ทธิ ใช้กล่าวอ้างได้เฉพาะคู่สัญญาเท่านั้น ไม่สามารถยกขึ้น\nกล่าวอ้างต่อบุคคลภายนอกได้ (มาตรา 1299 วรรคแรก)\nกรณีตามอุทาหรณ์ การที่เข้มทาสัญญาอนุญาตให้ป้อมสร้างบ้านในที่ดินมีโฉนดของตนเป็ นเวลา 20 ปี ป้อม\nจึงเป็ นผูม้ ีสิทธิ เหนื อพื้นดินของเข้ม อันเป็ นการได้มาซึ่งทรัพยสิ ทธิอนั เกี่ยวกับอสังหาริ มทรัพย์โดยทางนิ ติ\nกรรม เมื่อปรากฏว่านิติกรรมดังกล่าวเพียงแต่ทาเป็ นหนังสื อไม่ได้จดทะเบียนกับพนักงานเจ้าหน้าที่ ย่อมมี\nผลทาให้นิติกรรมนั้นไม่บริ บูรณ์ในฐานะทรัพยสิ ทธิ แต่ยงั คงมีผลบังคับระหว่างเข้มกับป้อมในฐานะบุคคล\nสิ ทธิตามมาตรา 1299 วรรคแรก ดังนั้น บ้านจึงยังไม่เป็ นส่วนควบของที่ดิน เพราะป้อมเป็ นผูม้ ีสิทธิในที่ดิน\nของผูอ้ ื่นและได้ใช้สิทธิน้ นั ปลูกสร้างไว้ตามมาตรา 146\nแต่อย่างไรก็ตาม เมื่อครบกาหนด 20 ปี สิ ทธิ ในที่ดินของเข้มที่ป้อมมีอยู่ยอ่ มสิ้ นสุ ดลง เนื่องจากข้อความใน\nสัญญาก าหนดให้บ ้านตกเป็ นกรรมสิ ทธิ์ ของเข้ม ทันที เมื่อครบ 20 ปี จึ ง เท่ า กับ ป้ อมได้แสดงเจตนาสละ\nกรรมสิ ทธิ์ในบ้านไว้ล่วงหน้าแล้ว\nดังนั้น บ้านจึงตกเป็ นกรรมสิ ทธิ์ของเข้มในฐานะที่เป็ นส่ วนควบของที่ดินตามมาตรา 144 เข้มจึงมี\nสิ ทธิทาสัญญาและจดทะเบียนขายบ้านพร้อมที่ดินให้กบั แหม่มได้ และแหม่มผูร้ ับโอนย่อมมีกรรมสิ ทธิ์ ใน\nบ้านและที่ดินนั้นโดยสมบูรณ์\nส่ วนกรณี ของแตนนั้นเมื่ อป้ อมไม่มีกรรมสิ ทธิ์ ในบ้านหลังดังกล่าวแล้ว ป้ อมจึงไม่สามารถนาบ้านไปทา\nสัญญาขายให้กบั แตนได้ ดังนั้น แตนผูร้ ับโอนตามสัญญาซื้อขายจึงไม่มีสิทธิในบ้านดีไปกว่าป้ อมผูโ้ อนและ\nไม่สามารถรื้ อถอนบ้านออกไปได้","conclusion":"สรุ ป แหม่มเป็ นผูท้ ี่มีกรรมสิ ทธิ์ ในบ้านพิพาทดีกว่าแตน และแตนไม่สามารถรื้ อถอนบ้านออกไป\nจากที่ดินนั้นได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2554-1-4-25","year":"2554","semester":"ภาค 1","number":4,"page":25,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2554 ภาค 1 · ข้อ 4","sections":["1382"],"otherSections":["1385"],"question":"ข้ อ 4. แสงดาวซื้ อที่ดินแปลงหนึ่ งมาจากสันทราย โดยแสงดาวคิดว่าที่ดินแปลงนี้ เป็ นที่ดินมือเปล่ายังไม่มี\nโฉนด เมื่อสันทรายส่งมอบการครอบครองให้ แสงดาวจึงเข้าไปปลูกบ้านครอบครองทาไร่ ออ้ ยอยู่บนที่ดิน\nแปลงนั้น ความจริ งที่ดินแปลงนั้นเป็ นที่ดินมีโฉนดเป็ นกรรมสิ ทธิ์ ของสุ ดสวย สันทรายได้ครอบครองทา\nประโยชน์มาเป็ นเวลากว่าห้าปี ก่อนที่จะขายให้แสงดาว แต่ในระหว่างห้าปี สุ ดสวยเจ้าของที่ดินได้มาล้อม\nรั้วลวดหนามเพื่อมิให้ใครเข้ามาบุกรุ กที่ดินแปลงนั้น ทาให้สันทรายเข้าไปทาไร่ ไม่ได้อยูเ่ ก้าเดือน เมื่อรั้วพัง\nลงสันทรายจึงเข้าไปทาไร่ ต่อได้สามปี หลังจากนั้นได้ขายที่ดินแปลงนั้นให้แสงดาว แสงดาวปลูกบ้านทาไร่\nอ้อยมาได้ห้าปี สุ ดสวยได้ให้แสงดาวออกไปจากที่ ดินแปลงนั้น แสงดาวไม่ยอมออกไปจากที่ดินแปลง\nนั้น โดยอ้างว่าสุ ดสวยหมดระยะเวลาเรี ยกคืนการครอบครองที่ดินแปลงนั้นจากตนแล้ว\nข้ออ้างของแสงดาวรับฟังได้หรื อไม่ ให้นกั ศึกษาอธิบาย","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1385 ถ้าโอนการครอบครองแก่ กัน ผูร้ ั บโอนจะนับเวลาซึ่ งผูโ้ อนครอบครองอยู่ก่อนนั้น\nรวมเข้า กับ เวลาครอบครองของตนก็ ไ ด้ ถ้า ผูร้ ั บ โอนนับ รวมเช่ นนั้น และถ้า มี ข ้อบกพร่ อ งในระหว่ า ง\nครอบครองของผูโ้ อนไซร้ ท่านว่าข้อบกพร่ องนั้นอาจยกขึ้นเป็ นข้อต่อสู ้ผรู ้ ับโอนได้","application":"โดยหลั ก แล้ ว การได้ ก รรมสิ ทธิ์ ในอสั ง หาริ มทรั พ ย์ โ ดยการครอบครองปรปั กษ์ ต าม\nมาตรา 1382 จะต้องประกอบด้วยหลักเกณฑ์ดงั นี้ คือ\n1. เป็ นทรัพย์สินของผูอ้ ื่นโดยผูอ้ ื่นมีกรรมสิ ทธิ์\n2. ได้ครอบครองโดยความสงบ\n3. ครอบครองโดยเปิ ดเผย\n4. ครอบครองโดยเจตนาเป็ นเจ้าของ\n5. ครอบครองติดต่อกันมาเป็ นเวลา 10 ปี\nกรณี ตามอุทาหรณ์ การที่สันทรายได้ครอบครองทาประโยชน์ในที่ดินของสุ ดสวยมาเป็ นเวลากว่า\nห้าปี ก่อนที่จะขายให้แสงดาวนั้น เมื่อปรากฏว่าในระหว่างห้าปี สุ ดสวยได้มาล้อมรั้วลวดหนามในที่ดินแปลง\nนั้น ท าให้สันทรายเข้า ไปท าไร่ ไ ม่ ไ ด้อยู่เก้า เดื อน และเมื่ อรั้ วพัง ลงสั นทรายจึ ง เข้า ไปท าไร่ ต่ อได้ส าม\nปี ดังนั้น การครอบครองที่ดินช่วงแรกกับช่วงหลังของสันทรายจึงไม่ติดต่อกัน แสงดาวจึงรับโอนเวลาการ\nครอบครองที่ดินจากสันทรายได้เพียงสามปี เพราะการครอบครองช่วงแรกของสันทรายมีขอ้ บกพร่ องตาม\nมาตรา 1385\nเมื่อข้อเท็จจริ งระบุวา่ หลังจากซื้อที่ดินมา แสงดาวปลูกบ้านทาไร่ ออ้ ยในที่ดินมาได้หา้ ปี ซึ่งเมื่อรวมกับการ\nครอบครองของสันทรายแล้ว ย่อมถือว่าแสงดาวครอบครองที่ดินได้เพียงแปดปี ตามมาตรา 1385 แสงดาว\nจึงยังไม่ได้กรรมสิ ทธิ์โดยการครอบครองปรปักษ์ตามมาตรา 1382\nดังนั้น ข้ออ้างของแสงดาวที่ว่าสุ ดสวยหมดระยะเวลาการเรี ยกคืนการครอบครองที่ ดินแปลงนั้น\nจากตนแล้ว จึงรับฟั งไม่ได้ เพราะที่ดินของสุ ดสวยเป็ นที่ดินที่มีกรรมสิ ทธิ์ไม่ใช่ที่ดินมือเปล่า สุ ดสวยใน\nฐานะเจ้าของกรรมสิ ทธิ์ยอ่ มมีสิทธิติดตามเอาคืนที่ดินของตนจากผูไ้ ม่มีสิทธิได้ทุกเมื่อ","conclusion":"สรุป ข้ออ้างของแสงดาวรับฟังไม่ได้\nการสอบไล่ ภาคฤดูร้อน ปี การศึกษา 2553\nข้อสอบกระบวนวิชา LAW2001 (LA 201),(LW 204)\nกฎหมายแพ่งและพาณิชย์ว่าด้วยทรัพย์\nคาแนะนา ข้อสอบเป็ นอัตนัยล้วนมี 4 ข้อ","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2553-s-1-27","year":"2553","semester":"ภาคฤดูร้อน","number":1,"page":27,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาคฤดูร้อน · ข้อ 1","sections":["1299","1382"],"otherSections":[],"question":"ข้ อ 1. นายเสื อครอบครองปรปักษ์ที่ดินมีโฉนดของนายช้างเป็ นเวลา 12 ปี แต่ยงั ไม่ได้จดทะเบียนเปลี่ยนชื่อ\nในโฉนดเป็ นชื่อของตน ต่อมานายช้างได้นาที่ดินแปลงนี้ ไปขายให้กบั นายกวางโดยทาสัญญาเป็ นหนังสื อ\nและจดทะเบี ย นกับ พนัก งานเจ้า หน้า ที่ และนายกวางก็ ไ ม่ รู้เรื่ องการครอบครองปรปั ก ษ์ข องนายเสื อ มา\nก่อน หลังจากนั้น 1 ปี นายกวางถึงแก่ความตาย น.ส.หนูบุตรของนายกวางได้จดทะเบียนรับโอนกรรมสิ ทธิ์\nที่ดินมรดกแปลงนี้ในฐานะทายาทโดยธรรม และได้ฟ้องขับไล่นายเสื อให้ออกจากที่ดินแปลงนั้น\nนายเสื อต่อสู ้ว่าตนได้กรรมสิ ทธิ์ ที่ดินแปลงนี้ โดยการครอบครองปรปั กษ์แล้ว น.ส.หนูได้ที่ดินมาโดยไม่ได้\nเสี ยค่าตอบแทนย่อมไม่มีสิทธิดีกว่าตน\nดังนี้ ให้ท่านวินิจฉัยว่าข้อต่อสู้ของนายเสื อรับฟังได้หรื อไม่","rule":"มาตรา 1299 วรรคสอง ถ้ามีผไู ้ ด้มาซึ่งอสังหาริ มทรัพย์ หรื อทรัพยสิ ทธิอนั เกี่ยวกับอสังหาริ มทรัพย์โดยทาง\nอื่นนอกจากนิ ติกรรม สิ ทธิ ของผูไ้ ด้มานั้น ถ้ายังมิได้จดทะเบียนไซร้ ท่านว่าจะมีการเปลี่ยนแปลงทาง\nทะเบียนไม่ได้ และสิ ทธิ อนั ยังมิได้จดทะเบียนนั้น มิให้ยกเป็ นข้อต่อสู้บุคคลภายนอกผูไ้ ด้สิทธิมาโดยเสี ย\nค่าตอบแทนและโดยสุจริ ตและได้จดทะเบียนสิ ทธิโดยสุจริ ตแล้ว","application":"กรณีตามอุทาหรณ์ การที่นายเสื อครอบครองปรปักษ์ที่ดินมีโฉนดของนายช้างเป็ นเวลา 12 ปี ถือว่า\nนายเสื อได้กรรมสิ ทธิ์ ในที่ดินของนายช้างโดยการครอบครองปรปั กษ์ (ป.พ.พ. มาตรา 1382) อันเป็ นการ\nได้มาซึ่งอสังหาริ มทรัพย์โดยทางอื่นนอกจากนิติกรรมตามมาตรา 1299 วรรคสอง ดังนั้น เมื่อนายเสื อยังมิได้\nจดทะเบียนเปลี่ยนชื่ อในโฉนดเป็ นชื่ อของตน และระหว่างนั้นนายช้างได้ขายที่ ดินแปลงนี้ ใ ห้กับ นายก\nวาง โดยท าสั ญ ญาเป็ นหนัง สื อ และจดทะเบี ย นกับ พนัก งานเจ้า หน้า ที่ และนายกวางก็ ไ ม่ รู้ เ รื่ อ งการ\nครอบครองปรปั กษ์ของนายเสื อมาก่อน จึงทาให้สิทธิการได้มาของนายเสื อไม่สามารถยกขึ้นต่อสู ้นายกวาง\nผูเ้ ป็ นบุคคลภายนอกซึ่ งได้สิทธิ ในที่ดินนี้ มาโดยสุ จริ ต (ไม่รู้เรื่ องการครอบครองปรปักษ์ของนายเสื อ) และ\nโดยเสี ยค่าตอบแทน (ซื้อ) และจดทะเบียนสิ ทธิของตนโดยสุจริ ตแล้วได้\nและเมื่อข้อเท็จจริ งปรากฏว่า น.ส.หนูได้จดทะเบียนรับโอนกรรมสิ ทธิ์ที่ดินมรดกแปลงนี้มาในฐานะทายาท\nโดยธรรมของนายกวาง จึงถือเป็ นผูส้ ื บสิ ทธิของนายกวาง ผูซ้ ่ ึ งมีสิทธิ ในที่ดินพิพาทดีกว่านายเสื อมาตั้งแต่\nแรกแล้ว น.ส.หนูจึงมีสิทธิในที่ดินพิพาทดีกว่านายเสื อด้วย\nดั งนั้น ข้อต่อสู้ข องนายเสื อที่ ว่า ตนได้ก รรมสิ ท ธิ์ ในที่ ดินแปลงนี้ โดยการครอบครองปรปั ก ษ์\nแล้ว น.ส.หนูได้ที่ดินมาโดยไม่ได้เสี ยค่าตอบแทนย่อมไม่มีสิทธิดีกว่าตนจึงรับฟังไม่ได้","conclusion":"สรุป ข้อต่อสู้ของนายเสื อรับฟังไม่ได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2553-s-3-29","year":"2553","semester":"ภาคฤดูร้อน","number":3,"page":29,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาคฤดูร้อน · ข้อ 3","sections":["1377","1382"],"otherSections":["1385"],"question":"ข้ อ 3. นายดาครอบครองปรปั กษ์ทานาในที่ดินมีโฉนดของนายแดงมาได้ 4 ปี นายดาถึงแก่กรรมนายเขียว\nบุตรของนายดาปฏิเสธไม่สนใจที่จะครอบครองต่อจึงปล่อยที่ดินให้รกร้างอยู่ 10 เดือน ต่อมานายเขียวตก\nงานจึงเปลี่ยนใจเข้าไปทานาบนที่ดินของนายแดงอีกได้นาน 6 ปี นายแดงจึงฟ้องขับไล่นายเขียวออกจาก\nที่ดินแปลงนั้น\nให้ท่านวินิจฉัยว่า นายเขียวจะได้สิทธิอย่างใดจากการที่ตนครอบครองที่ดินต่อจากนายดาบิดาของ\nตนหรื อไม่ จงอธิบาย","rule":"มาตรา 1377 วรรคแรก ถ้า ผูค้ รอบครองสละเจตนาครอบครอง หรื อ ไม่ ยุด ถื อ ทรั พ ย์สิ น ต่ อไป\nไซร้ การครอบครองย่อมสุ ดสิ้ นลง\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1385 ถ้าโอนการครอบครองแก่ กัน ผูร้ ั บโอนจะนับเวลาซึ่ งผูโ้ อนครอบครองอยู่ก่อนนั้น\nรวมเข้า กับ เวลาครอบครองของตนก็ ไ ด้ ถ้า ผู ร้ ั บ โอนนับ รวมเช่ น นั้น และถ้า มี ข ้อ บกพร่ อ งในระหว่า ง\nครอบครองของผูโ้ อนไซร้ ท่านว่าข้อบกพร่ องนั้นอาจยกขึ้นเป็ นข้อต่อสู ้ผรู ้ ับโอนได้","application":"โดยหลั ก แล้ ว การได้ ก รรมสิ ทธิ์ ในอสั ง หาริ มทรั พ ย์ โ ดยการครอบครองปรปั กษ์ ต าม\nมาตรา 1382 จะต้องประกอบด้วยหลักเกณฑ์ดงั นี้ คือ\n1 เป็ นทรัพย์สินของผูอ้ ื่นโดยผูอ้ ื่นมีกรรมสิ ทธิ์\n2 ได้ครอบครองโดยความสงบ\n3 ครอบครองโดยเปิ ดเผย\n4 ครอบครองโดยเจตนาเป็ นเจ้าของ\n5 ครอบครองติดต่อกันมาเป็ นเวลา 10 ปี\nกรณีตามอุทาหรณ์ การที่นายเขียวบุตรของนายดาปฏิเสธไม่สนใจครอบครองปรปักษ์ที่ดินของนาย\nแดงต่อจากนายดาบิ ดาซึ่ งถึงแก่กรรมนั้น ย่อมถือว่านายเขียวสละเจตนาครอบครองที่ดินพิพาทแล้ว อายุ\nความการครอบครองปรปักษ์จึงสิ้ นสุ ดลงตามมาตรา 1377 วรรคแรก\nดังนั้น แม้ต่อมาอีก 10 เดือน หลังจากทิ้งร้ างไป นายเขียวจะเข้ามาครอบครองที่ดินของนายแดงอีก 6 ปี ก็\nตาม นายเขี ย วก็ ไ ม่ ส ามารถน าเอาระยะเวลาการครอบครองของนายด าผู ้เ ป็ นบิ ด ามานับ รวมกับ การ\nครอบครองของตนเองตามมาตรา 1385 ได้\nดั งนั้น เมื่ อนายเขี ย วครอบครองปรปั กษ์ที่ นาแปลงนี้ ได้เพี ยง 6 ปี ซึ่ ง ยัง ไม่ ถึง 10 ปี จึ ง ไม่ ค รบ\nหลักเกณฑ์ตามมาตรา 1382 ที่จะทาให้ได้กรรมสิ ทธิ์ โดยการครอบครองปรปั กษ์นายเขียวจึงยังไม่ได้สิทธิ\nใดๆบนที่ดินแปลงนี้","conclusion":"สรุป นายเขียวไม่ได้สิทธิใดๆจากการที่ตนครอบครองที่ดินต่อจากนายดาผูเ้ ป็ นบิดา","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2553-s-4-30","year":"2553","semester":"ภาคฤดูร้อน","number":4,"page":30,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาคฤดูร้อน · ข้อ 4","sections":["1382","1401","1299"],"otherSections":["1390"],"question":"ข้อ 4. อาทิตย์เป็ นเจ้าของที่นาแปลงหนึ่ง ทุกๆปี ในฤดูทานาอาทิตย์ตอ้ งใช้ทางผ่านบนที่ดินของจันทร์เพื่อเข้า\nไปท านาในที่ นาของอาทิ ตย์ โดยจันทร์ ไ ม่ ท ราบมาก่ อ นว่ า อาทิ ตย์ม าเดิ นผ่ า นที่ ดิ น ของตน อาทิ ตย์ใ ช้\nทางผ่านบนที่ดินของจันทร์ มาได้กว่า 10 ปี โดยมิได้ไปจดทะเบียน ต่อมาจันทร์ ทราบจึงทารั้วกั้นที่ดินเพื่อ\nไม่ให้อาทิตย์เดินผ่าน\nดังนี้ อาทิตย์จะมีสิทธิ อา้ งหลักกฎหมายเรื่ องใดมาต่อสู ้จนั ทร์ เพื่อมิให้จนั ทร์ ทารั้วกั้นมิให้อาทิ ตย์\nเดินผ่านหรื อไม่ จงอธิบาย","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1390 ท่านมิให้เจ้าของภารยทรัพย์ประกอบกรรมใด ๆ อันจะเป็ นเหตุให้ประโยชน์แห่งภาระ\nจายอมลดไป หรื อเสื่ อมความสะดวก\nมาตรา 1401 ภาระจายอมอาจได้มาโดยอายุความ ท่านให้นาบทบัญญัติว่าด้วยอายุความได้สิทธิ อนั\nกล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บงั คับโดยอนุโลม","application":"การได้ภาระจายอมโดยอายุความครอบครองปรปักษ์ตามมาตรา 1401 นั้น บัญญัติให้นาอายุความได้\nสิ ทธิตามมาตรา 1382 มาบังคับใช้โดยอนุโลม กล่าวคือ ต้องเป็ นกรณี ที่เจ้าของสามยทรัพย์ได้ใช้ประโยชน์\nในภารยทรั พ ย์ โดยความสงบ เปิ ดเผย และมี เจตนาจะได้สิ ท ธิ ภาระจายอมในภารยทรั พ ย์ โดยต้องใช้\nประโยชน์ติดต่อกันเป็ นเวลา 10 ปี\nกรณี ตามอุทาหรณ์ การที่อาทิตย์ใช้ทางผ่านบนที่ดินของจันทร์เพื่อเข้าไปทานาบนที่ดินของอาทิตย์เอง โดย\nจันทร์ไม่ทราบมาก่อนนั้น ถือเป็ นกรณีที่อาทิตย์เจ้าของสามยทรัพย์ได้ใช้ประโยชน์ในภารยทรัพย์โดยความ\nสงบ เปิ ดเผย และมีเจตนาจะได้สิทธิ ภาระจายอมในภารยทรัพย์แล้ว เมื่ออาทิตย์ใช้ทางผ่านบนที่ดินของ\nจันทร์ มาได้กว่า 10 ปี ย่อมทาให้อาทิตย์ได้ภาระจายอมโดยอายุความปรปั กษ์ตามมาตรา 1401 ประกอบ\nมาตรา 1382\nและเมื่ออาทิตย์ได้ภาระจายอมบนที่ดินของจันทร์ โดยอายุความปรปั กษ์ ซึ่ งถือเป็ นการได้ทรัพยสิ ทธิ ใน\nอสังหาริ มทรัพย์ตามมาตรา 1299 วรรคสองแล้ว (แม้ยงั ไม่ได้จดทะเบียนสิ ทธิก็เป็ นทรัพยสิ ทธิ) การที่จนั ทร์\nทารั้วกั้นที่ดินเพื่อไม่ให้อาทิตย์เดินผ่าน จึงเป็ นการทาให้ประโยชน์แห่งภาระจายอมลดลง หรื อเสื่ อมความ\nสะดวกตามมาตรา 1390\nดังนั้น อาทิตย์จึงมีสิทธิ อา้ งหลักกฎหมายตามมาตรา 1390 ขึ้นต่อสู ้กบั จันทร์ เพื่อมิให้จนั ทร์ ทารั้ว\nกั้นระหว่างภารยทรัพย์กบั สามยทรัพย์ได้","conclusion":"สรุป อาทิตย์มีสิทธิอา้ งหลักกฎหมายตามมาตรา 1390 ขึ้นต่อสู ้กบั จันทร์เพื่อมิให้จนั ทร์ ทารั้วกั้นมิให้\nอาทิตย์เดินผ่านได้\nการสอบไล่ภาค 2 ปี การศึกษา 2553\nข้อสอบกระบวนวิชา LAW2001 (LA 201),(LW 204)\nกฎหมายแพ่งและพาณิชย์ว่าด้วยทรัพย์\nคาแนะนา ข้อสอบเป็ นอัตนัยล้วนมี 4 ข้อ","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2553-2-1-32","year":"2553","semester":"ภาค 2","number":1,"page":32,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาค 2 · ข้อ 1","sections":["1299"],"otherSections":[],"question":"ข้อ 1. นายสอนกับนายอิ่มทาสัญญากันเอง โดยนายสอนอนุญาตให้นายอิ่มทาถนนผ่านที่ดินมีโฉนดของตน\nเพื่อออกสู่ ถนนพหลโยธิน ทั้งที่ที่ดินของนายอิ่มมีทางออกสู่ ทางสาธารณะอยู่แล้ว หลังจากนายอิ่มทาถนน\nผ่านที่ดินของนายสอนได้ 4 ปี นายสอนถึงแก่ความตาย นายสิ นบุตรของนายสอนได้จดทะเบียนรับมรดก\nที่ดินดังกล่าว\nดังนี้ ให้วินิจฉัยว่า\n(ก) นายสิ นจะล้อมรั้วไม่ยอมให้นายอิ่มใช้ถนนผ่านที่ดินของตนอีกต่อไปได้หรื อไม่ เพราะเหตุใด\n(ข) ถ้า หลัง จากนายสิ น จดทะเบี ย นรั บ มรดกได้ 1 ปี นายสิ น ท าสั ญ ญาและจดทะเบี ย นโอน\nกรรมสิ ทธิ์ ที่ดินแปลงนั้นให้นางฟ้าภริ ยานอกสมรสของตนโดยเสน่หา นางฟ้าจะล้อมรั้วไม่ยอมให้นายอิ่ม\nใช้ถนนผ่านที่ดินของตนอีกต่อไปได้หรื อไม่ เพราะเหตุใด","rule":"มาตรา 1299 วรรคแรก ภายในบังคับแห่ งบทบัญญัติในประมวลกฎหมายนี้ หรื อกฎหมายอื่น ท่าน\nว่ า การได้ ม าโดยนิ ติ ก รรมซึ่ งอสั ง หาริ มทรั พ ย์ห รื อทรั พ ยสิ ท ธิ อัน เกี่ ย วกั บ อสั ง หาริ มทรั พ ย์ น้ ั นไม่\nบริ บูรณ์ เว้นแต่นิติกรรมจะได้ทาเป็ นหนังสื อและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่","application":"ตามกฎหมาย การได้มาซึ่งอสังหาริ มทรัพย์หรื อทรัพยสิ ทธิอนั เกี่ยวกับอสังหาริ มทรัพย์โดยทางนิติ\nกรรมนั้น จะบริ บู รณ์ เป็ นทรั พ ยสิ ท ธิ ไ ด้ จะต้องท าเป็ นหนัง สื อและจดทะเบี ย นการได้ม ากับ พนัก งาน\nเจ้าหน้าที่ ซึ่งถ้าฝ่ าฝื นจะมีผลเป็ นเพียงบุคคลสิ ทธิ ใช้กล่าวอ้างได้เฉพาะคู่สัญญาเท่านั้น ไม่สามารถยกขึ้น\nกล่าวอ้างต่อบุคคลภายนอกได้ (มาตรา 1299 วรรคแรก)\nกรณี ตามอุทาหรณ์ การที่นายสอนทาสัญญาอนุญาตให้นายอิ่มทาถนนผ่านที่ดินของตน ทั้งที่ที่ดินของนาย\nอิ่ ม มี ท างออกสู่ ท างสาธารณะอยู่ แ ล้ว นั้น ถื อ เป็ นกรณี ที่ น ายอิ่ ม ได้ท างภาระจ ายอมผ่ า นที่ ดิ น ของนาย\nสอน อันเป็ นการได้มาซึ่งทรัพยสิ ทธิอนั เกี่ยวกับอสังหาริ มทรัพย์โดยทางนิติกรรม\nเมื่อปรากฏข้อเท็จจริ งว่า นิติกรรมการได้ภาระจายอมดังกล่าวไม่ได้ทาเป็ นหนังสื อและจดทะเบียนการได้มา\nกับ พนัก งานเจ้า หน้า ที่ นิ ติก รรมนั้นจึ ง ไม่ บ ริ บู ร ณ์ ใ นฐานะทรั พ ยสิ ท ธิ ไม่ ส ามารถยกขึ้ นกล่ า วอ้า งต่ อ\nบุคคลภายนอกได้ แต่ยงั คงมีผลบังคับระหว่างนายสอนกับนายอิ่มซึ่ งเป็ นคู่สัญญาในฐานะบุคคลสิ ทธิ ตาม\nมาตรา 1299 วรรคแรก\nดังนั้น (ก) นายสิ นผูจ้ ดทะเบียนรับมรดกที่ดินภารยทรัพย์ดงั กล่าวจากนายสอนบิดาของตนจะล้อม\nรั้วไม่ยอมให้นายอิ่มใช้ถนนผ่านที่ดินของตนอีกต่อไปไม่ได้ เพราะแม้การได้ภาระจายอมดังกล่าวจะไม่ได้\nทาเป็ นหนังสื อและจดทะเบียนการได้มากับพนักงานเจ้าหน้าที่ แต่ภาระจายอมนั้นยังคงมีผลผูกพันนายสอน\nในฐานะบุคคลสิ ทธิ ดังนั้นเมื่อนายสอนตาย นายสิ นผูร้ ับมรดกจึงต้องรัยไปทั้งสิ ทธิและหน้าที่ของนายสอน\nเจ้ามรดกดังกล่าวด้วย\n(ข) การที่ต่อมานายสิ นจดทะเบียนโอนกรรมสิ ทธิ์ที่ดินแปลงนั้นให้แก่นางฟ้าภริ ยานอกสมรสของ\nตนโดยเสน่หา นางฟ้าจึงเป็ นเจ้าของกรรมสิ ทธิ์ในที่ดินแปลงนั้น และถือเป็ นบุคคลภายนอก ดังนั้น เมื่อ\nภาระจายอมดังกล่าวไม่บริ บูรณ์ในฐานะทรัพยสิ ทธิ จึงไม่สามารถบังคับใช้กบั นางฟ้าซึ่งเป็ นบุคคลภายนอก\nได้ นางฟ้าในฐานะเจ้าของกรรมสิ ทธิ์จึงมีสิทธิลอ้ มรั้วไม่ให้นายอิ่มใช้ถนนผ่านที่ดินของตนอีกต่อไปได้","conclusion":"สรุป\n(ก) นายสิ นจะล้อมรั้วไม่ยอมให้นายอิ่มใช้ถนนผ่านที่ดินของตนอีกต่อไปไม่ได้\n(ข) นางฟ้าสามารถล้อมรั้วไม่ยอมให้นายอิ่มใช้ถนนผ่านที่ดินของตนอีกต่อไปได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2553-2-3-34","year":"2553","semester":"ภาค 2","number":3,"page":34,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาค 2 · ข้อ 3","sections":["1382"],"otherSections":["1386"],"question":"ข้ อ 3. แพงมีกรรมสิ ทธิ์ บนที่ดินแปลงหนึ่ ง แต่เนื่ องจากแพงไปประกอบอาชีพอยู่ที่ต่างประเทศ จึงให้พนั\nดูแลที่ดินแปลงนั้นแทน พุธได้เข้าไปครอบครองปรปั กษ์ทาไร่ บนที่ดินแปลงนั้นบางส่ วน พันซึ่งเป็ นผูด้ ูแล\nที่ ดิ น แปลงนั้น ก็ ไ ม่ ท ราบ จึ ง ยัง ไม่ ไ ด้ข ับ ไล่ ส่ ว นแพงซึ่ ง อยู่ต่ า งประเทศก็ ไ ม่ ท ราบเช่ น เดี ย วกัน พุ ธ\nครอบครองทาไร่ บนที่ดินส่ วนนั้นของแพงมาได้แปดปี แพงกลับมาเมืองไทยกลับมาได้สามปี แพงได้ไป\nรังวัดที่ดินจึงเพิ่งทราบว่าพุธทาการครอบครองทาไร่ บุกรุ กเข้ามาบนที่ดินของตน แพงจึงฟ้องขับไล่พุธให้\nออกจากที่ดินแปลงนั้นโดยแพงอ้างว่า ตนเพิ่งทราบถึงการครอบครองของพุธเพียงสามปี ตนจึงยังไม่เสี ย\nสิ ทธิในที่ดินแปลงนั้นไป ถ้าท่านเป็ นศาล ท่านจะพิพากษาอย่างไร เพราะเหตุใด","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1386 บทบัญญัติว่าด้วยอายุความในประมวลกฎหมายนี้ ท่านให้ใช้บงั คับในเรื่ องอายุความ\nได้สิทธิ อันกล่าวไว้ในลักษณะนี้โดยอนุโลม","application":"โดยหลั ก แล้ ว การได้ ก รรมสิ ทธิ์ ในอสั ง หาริ มทรั พ ย์ โ ดยการครอบครองปรปั กษ์ ต าม\nมาตรา 1382 จะต้องประกอบด้วยหลักเกณฑ์ดงั นี้ คือ\n1 เป็ นทรัพย์สินของผูอ้ ื่นโดยผูอ้ ื่นมีกรรมสิ ทธิ์\n2 ได้ครอบครองโดยความสงบ\n3 ครอบครองโดยเปิ ดเผย\n4 ครอบครองโดยเจตนาเป็ นเจ้าของ\n5 ครอบครองติดต่อกันมาเป็ นเวลา 10 ปี\nกรณีตามอุทาหรณ์ การที่พุธได้เข้าไปครอบครองปรปักษ์ทาไร่ บนที่ดินบางส่วน ซึ่งเป็ นกรรมสิ ทธิ์ของแพง\nนั้น เมื่อพุธได้ครอบครองโดยความสงบ เปิ ดเผย และเจตนาเป็ นเจ้าของติดต่อกันถึง 11 ปี ซึ่ งเกิน 10 ปี\nแล้ว พุธย่อมได้กรรมสิ ทธิ์ในที่ดินส่ วนนั้นโดยการครอบครองปรปักษ์ตามมาตรา 1382\nดังนั้น แพงจะฟ้ องขับไล่พุธให้ออกจากที่ดินแปลงนั้น โดยอ้างว่าตนเพิ่งทราบถึงการครอบครองของพุธ\nเพี ย ง 3 ปี ตนจึ ง ยัง ไม่ เ สี ย สิ ท ธิ ใ นที่ ดิ น แปลงนั้น ไปไม่ ไ ด้ เพราะการครอบครองปรปั ก ษ์เ ป็ นการได้\nกรรมสิ ทธิ์ โดยอายุความได้สิทธิ ตามมาตรา 1386 และเป็ นอายุความโดยผลของกฎหมายซึ่ งศาลสามารถ\nยกขึ้นเองได้","conclusion":"สรุ ป ถ้า ข้า พเจ้า เป็ นศาลจะพิ พ ากษาให้ พุ ธ ได้ก รรมสิ ท ธิ์ ในที่ ดิ นส่ วนนั้น โดยการครอบครอง\nปรปักษ์ตามมาตรา 1382 ตามเหตุผลดังกล่าวข้างต้น","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2553-2-4-35","year":"2553","semester":"ภาค 2","number":4,"page":35,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาค 2 · ข้อ 4","sections":["1377","1382","1387","1401"],"otherSections":[],"question":"ข้ อ 4. ดวงเป็ นเจ้าของกิ จการร้ า นขายเครื่ องมื อทางการเกษตรทั้งขาย ให้เช่า และรับจ้างไถ หว่าน เกี่ยว\nข้าว พืชไร่ ฯลฯ ร้านของดวงตั้งอยู่ที่นอกเขตเทศบาล ที่ดินที่ต้ งั ร้านของดวงมีทางออกสู่ ทางสาธารณะอยู่\nแล้ว แต่เมื่ อมี เกษตรกรหรื อมี ใ ครเช่ า เครื่ องมื อทางการเกษตร ดวงจะใช้ที่ ดินของเด่ น เป็ นทางลัด ขน\nเครื่ องมือต่างๆผ่านที่ดินของเด่นเข้า – ออกสู่ถนนสาธารณะเสมอเป็ นประจา โดยดวงไม่ทราบว่าที่ดินแปลง\nนั้นใครเป็ นเจ้าของ จึงไม่ได้ขออนุญาตใช้ทาง และบางครั้งลูกค้าของดวงยังใช้เส้นทางบนที่ดินของเด่นเข้า\nมาติดต่อซื้อขาย เช่า ว่าจ้างดวงด้วย เมื่อดวงใช้ที่ดินของเด่นเป็ นทางเข้า - ออก มาได้สิบห้าปี เด่นทราบจึงมา\nตกลงกับ ดวงว่า ถ้า ดวงยัง ต้องการใช้ถ นนบนที่ ดินของตนต่อไป ดวงต้องเช่ า ที่ ดินแปลงนี้ มิ ฉ ะนั้นก็\nต้องห้ามบุกรุ กเข้ามาใช้ทางผ่านที่ดินแปลงนี้อีก ดวงจึงตกลงขอเช่าโดยจ่ายค่าผ่านทางให้กบั เด่นปี ละห้าพัน\nบาท\nในความเห็นของท่านให้ท่านอธิบายว่า ดวงได้สิทธิ อะไรก่อนที่จะตกลงเช่าที่ดินเด่น และหลังจาก\nตกลงเช่าที่ดินเด่นเพื่อผ่านทางบนที่ดินของเด่น วิธีใดและส่งผลอย่างไรบ้าง","rule":"มาตรา 1377 วรรคแรก ถ้า ผูค้ รอบครองสละเจตนาครอบครอง หรื อ ไม่ ยุด ถื อ ทรั พ ย์สิ น ต่ อไป\nไซร้ การครอบครองย่อมสุ ดสิ้ นลง\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1387 อสังหาริ มทรัพย์อาจต้องตกอยู่ในภาระจายอมอันเป็ นเหตุให้เจ้าของต้องยอมรับกรรม\nบางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรื อต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยูใ่ นกรรมสิ ทธิ์ทรัพย์สิน\nนั้นเพื่อประโยชน์แก่อสังหาริ มทรัพย์อื่น\nมาตรา 1401 ภาระจายอมอาจได้มาโดยอายุความ ท่านให้นาบทบัญญัติว่าด้วยอายุความได้สิทธิอนั\nกล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บงั คับโดยอนุโลม","application":"การได้ภาระจายอมตามมาตรา 1387 โดยอายุค วามครอบครองปรปั ก ษ์น้ ัน ถื อเป็ นการได้ท รั พ ยสิ ท ธิ\nเกี่ยวกับอสังหาริ มทรัพย์โดยทางอื่นนอกจากนิติกรรม ซึ่งตามมาตรา 1401 นั้น บัญญัติให้นาอายุความได้\nสิ ทธิตามมาตรา 1382 มาบังคับใช้โอยอนุโลม กล่าวคือ ต้องเป็ นกรณีที่เจ้าของสามยทรัพย์ได้ใช้ประโยชน์\nในภารยทรัพย์ โดยความสงบ เปิ ดเผย และมีเจตนาจะได้สิทธิ ภาระจายอมในภารยทรัพย์ โดยต้องใช้\nประโยชน์ติดต่อกันเป็ นเวลา 10 ปี\nกรณี ต ามอุ ท าหรณ์ การที่ ด วงเป็ นเจ้ า ของกิ จ การร้ า นขายเครื่ องมื อ ทางการเกษตร และรั บ จ้ า ง\nไถ หว่าน เกี่ยวข้าว พืชไร่ ฯลฯ และเมื่อมีเกษตรกรหรื อคนมาเช่าเครื่ องมือทางการเกษตร ดวงก็จะใช้ที่ดิน\nของเด่นเป็ นทางลัดขนเครื่ องมือต่างๆผ่านที่ดินของเด่นเข้าออกสู่ ถนนสาธารณะเสมอเป็ นประจานั้น ถือเป็ น\nกรณี ที่ดวงเจ้าของสามยทรัพย์ได้ใช้ประโยชน์ในภารยทรัพย์ คือที่ดินของเด่น โดยสงบ เปิ ดเผย และเจตนา\nจะได้มาซึ่ งภาระจายอมแล้ว เมื่อดวงใช้ที่ดินของเด่นเป็ นทางเข้าออกมาได้ 15 ปี ที่ต้ งั ร้านของดวงจึ ง ได้\nภาระจายอมโดยการครอบครองปรปักษ์แล้วตามมาตรา 1387 และมาตรา 1382 ประกอบมาตรา 1401\nแต่อย่างไรก็ตาม การที่ดวงทาสัญญาเช่าที่ ดินกับเด่นเพื่อใช้เป็ นทางผ่านเข้าออกนั้น ถือเป็ นกรณี ที่ดวงผู ้\nครอบครองได้สละเจตนาครอบครองในภารยทรัพย์ดังกล่าวแล้ว กล่าวคือ เป็ นการที่ดวงยอมรับว่าดวง\nไม่ได้มีสิทธิ ในภาระจายอมบนที่ดินของเด่นแต่อย่างใด ดังนั้น ภาระจายอมที่ได้มาโดยการครอบครอง\nปรปักษ์ดงั กล่าวจึงสิ้ นสุ ดลงตามมาตรา 1377 วรรคแรก","conclusion":"สรุ ป ดวงได้สิทธิ คือภาระจายอมในที่ดินของเด่นโดยการครอบครองปรปั กษ์ก่อนที่ จะตกลงเช่ า\nที่ดินเด่น และหลังจากดวงตกลงเช่าที่ดินเด่นแล้ว ส่ งผลให้ภาระจายอมดังกล่าวสิ้ นสุ ดลง\nการสอบไล่ภาค 1 ปี การศึกษา 2553\nข้อสอบกระบวนวิชา LAW2001 (LA 201),(LW 204)\nกฎหมายแพ่งและพาณิชย์ว่าด้วยทรัพย์\nคาแนะนา ข้อสอบเป็ นอัตนัยล้วนมี 4 ข้อ","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2553-1-1-37","year":"2553","semester":"ภาค 1","number":1,"page":37,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาค 1 · ข้อ 1","sections":["144","1299"],"otherSections":[],"question":"ข้ อ 1. ป่ านทาสัญญาและจดทะเบียนยกบ้านและที่ดินมีโฉนดแปลงหนึ่งให้ปอโดยเสน่หา โดยปออนุ ญาต\nด้วยวาจาให้ป่านอาศัยอยู่ในบ้านหลังนั้นได้ตลอดไป ลังจากนั้น 3 ปี ปอทาสัญญาและจดทะเบียนขายที่ดิน\nดังกล่าวให้แก้ว หลังจากที่แก้วรับโอนที่ดินดังกล่าวแล้ว แก้วแจ้งให้ป่านออกไปจากบ้านหลังนั้น\nแต่ป่านไม่ยอมย้ายออกไปโดยอ้างว่าบ้านหลังดังกล่าวยังเป็ นกรรมสิ ทธิ์ ขอปอเพราะสัญญาซื้ อขายที่ดิน\nไม่ได้ระบุเรื่ องบ้านไว้ ดังนั้น ป่ านจึงมีสิทธิอยูอ่ าศัยในบ้านหลังนี้ต่อไปตามที่ป่านได้รับอนุญาตจากปอ\nดังนี้ ให้วินิจฉัยว่า แก้วจะฟ้องขับไล่ป่านออกไปจากบ้านหลังนี้ ได้หรื อไม่ และข้ออ้างของป่ านรับ\nฟังได้หรื อไม่ เพราะเหตุใด จงอธิบาย","rule":"มาตรา 144 ส่วนควบของทรัพย์ หมายความว่า ส่วนซึ่งโดยสภาพแห่งทรัพย์หรื อโดยจารี ตประเพณี\nแห่ งท้องถิ่นเป็ นสาระสาคัญในความเป็ นอยูข่ องทรัพย์น้ นั และไม่อาจแยกจากกันได้นอกจากจะทาลาย ทา\nให้บุบสลาย หรื อทาให้ทรัพย์น้ นั เปลี่ยนแปลงรู ปทรงหรื อสภาพไป\nเจ้าของทรัพย์ยอ่ มมีกรรมสิ ทธิ์ในส่ วนควบของทรัพย์น้ นั\nมาตรา 1299 วรรคแรก ภายในบังคับแห่ งบทบัญญัติในประมวลกฎหมายนี้ หรื อกฎหมายอื่น ท่าน\nว่ า การได้ ม าโดยนิ ติ ก รรมซึ่ งอสั ง หาริ มทรั พ ย์ห รื อทรั พ ยสิ ท ธิ อัน เกี่ ย วกั บ อสั ง หาริ มทรั พ ย์ น้ ั นไม่\nบริ บูรณ์ เว้นแต่นิติกรรมจะได้ทาเป็ นหนังสื อและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่","application":"ตามกฎหมาย การได้มาซึ่งอสังหาริ มทรัพย์หรื อทรัพยสิ ทธิอนั เกี่ยวกับอสังหาริ มทรัพย์โดยทางนิติ\nกรรมนั้น จะบริ บู ร ณ์ เ ป็ นทรั พ ย์สิ ท ธิ ไ ด้ จะต้อ งท าเป็ นหนัง สื อ และจดทะเบี ย นการได้ม ากับ พนัก งาน\nเจ้าหน้าที่ ซึ่งถ้าฝ่ าฝื นจะมีผลเป็ นเพียงบุคคลสิ ทธิ ใช้กล่าวอ้างได้เฉพาะคู่สัญญาเท่านั้น ไม่สามารถยกขึ้น\nกล่าวอ้างต่อบุคคลภายนอกได้ มาตรา 1299 วรรคแรก\nกรณี ตามอุทาหรณ์ การที่ป่านทาสัญญายกบ้านและที่ดินมีโฉนดให้ปอโดยเสน่ หา ปอจึงเป็ นผูไ้ ด้มาซึ่ ง\nอสังหาริ มทรัพย์โดยทางนิ ติกรรม เมื่อได้มีการทาเป็ นหนังสื อและจดทะเบียนกับพนักงานเจ้าหน้าที่ การ\nได้มาดังกล่าวจึงมีผลบริ บูรณ์เป็ นทรัพย์สิทธิตามมาตรา 1299 วรรคแรก และจากข้อเท็จจริ งดังกล่าว เมื่อปอ\nได้อ นุ ญ าตให้ ป่ านอาศัย อยู่ ใ นบ้า นหลัง นั้น ได้ต ลอดไป ป่ านจึ ง เป็ นผูไ้ ด้ม าซึ่ ง ทรั พ ยสิ ท ธิ อัน เกี่ ย วกับ\nอสังหาริ มทรัพย์โดยทางนิติกรรม แต่เมื่อการได้มาซึ่งสิ ทธิอาศัยของป่ านเป็ นการอนุญาตด้วยวาจาไม่ได้ทา\nเป็ นหนังสื อและจดทะเบียนกับพนักงานเจ้าหน้าที่ สิ ทธิอาศัยดังกล่าวจึงไม่บริ บูรณ์เป็ นทรัพยสิ ทธิ ทาให้\nป่ านไม่สามารถยกขึ้นกล่าวอ้างต่อบุคคลภายนอกได้ แต่นิติกรรมนี้ คงมีผลเป็ นบุคคลสิ ทธิ ซึ่งใช้กล่าวอ้าง\nได้เฉพาะคู่สัญญาคือปอเท่านั้นตามมาตรา 1299 วรรคแรก\nและเมื่อข้อเท็จจริ งปรากฏว่า ต่อมาปอได้ทาสัญญาและจดทะเบียนขายที่ดินดังกล่าวให้แก้ว แก้วจึงเป็ นผูม้ ี\nกรรมสิ ทธิ์ ในที่ดินและบ้านซึ่งปลูกอยู่บนที่ดินนั้นด้วย ในฐานะที่บา้ นเป็ นส่วนควบของที่ดิน เพราะบ้านถือ\nว่าเป็ นสาระสาคัญในความเป็ นอยู่ของที่ ดินโดยจารี ตประเพณี แห่ งท้องถิ่นและไม่อาจแยกออกจากกันได้\nนอกจากจะทาลาย ทาให้บุบสลายหรื อทาให้ทรัพย์น้ นั เปลี่ยนแปลงรู ปทรงหรื อสภาพไปตามมาตรา 144\nดังนั้น แก้วในฐานะที่เป็ นเจ้าของที่ดินและบ้านจึงมีสิทธิ ฟ้องขับไล่ให้ป่านออกไปจากบ้านหลังนี้ ได้ และ\nข้ออ้างของป่ านที่วา่ บ้านหลังดังกล่าวยังเป็ นกรรมสิ ทธิ์ของปอ เพราะสัญญาซื้ อขายที่ดินไม่ได้ระบุเรื่ องบ้าน\nไว้และป่ านยังมีสิทธิอาศัยในบ้านหลังนี้ ต่อไปนั้นจึงรับฟังไม่ได้ เพราะเมื่อการได้สิทธิอาศัยในบ้านของปอ\nไม่บริ บูรณ์เป็ นทรัพย์สิทธิ ป่ านจึงไม่สามารถยกขึ้นกล่าวอ้างต่อแก้วซึ่งเป็ นบุคคลภายนอกได้","conclusion":"สรุป แก้วฟ้องขับไล่ให้ป่านออกไปจากบ้านดังกล่าวได้ และข้ออ้างของป่ านรับฟังไม่ได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2553-1-3-39","year":"2553","semester":"ภาค 1","number":3,"page":39,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาค 1 · ข้อ 3","sections":["1367","1377","1382"],"otherSections":[],"question":"ข้อ 3. อ่างเข้าไปครอบครองที่ดิน น.ส.3 ของโอ่งแปลงหนึ่ง ครอบครองทาประโยชน์มาได้ห้าปี เมื่อมีการ\nเดินสารวจเพื่ออกโฉนดที่ดิน โอ่งเพิ่งรู ้ว่าอ่างเข้าไปทาประโยชน์ครอบครองที่ดินแปลงนั้นอยู่ โอ่งจึงได้มา\nแจ้งความต่อพนักงานเจ้าหน้าที่ และมาบอกอ่างให้อ่างออกไปจากที่ ดินแปลงนั้น อ่างจึงเลิกทานาและรื้ อ\nบ้านของอ่างออกไปจากที่ดินแปลงนั้น เมื่อผ่านไปได้สองปี\nอ่างก็กลับเข้าไปปลูกบ้านทานาอยู่บนที่ดินแปลงนั้นใหม่ ปรากฏว่าที่ดินแปลงนั้นโอ่งได้เปลี่ยนจากหนังสื อ\nรับรองการทาประโยชน์มาเป็ นโฉนดที่ดินเรี ยบร้อยแล้ว อ่างครอบครองต่อมาได้หา้ ปี โอ่งจึงฟ้องศาลขับไล่\nอ่างให้ออกไปจากที่ดินแปลงนั้น\nให้ท่านวินิจฉัยว่าระหว่างโอ่งและอ่างใครมีสิทธิในที่ดินแปลงนั้นดีกว่ากัน เพราะเหตุใด","rule":"มาตรา 1367 บุ ค คลใดยึดถื อทรั พ ย์สิ น โดยเจตนาจะยึดถื อ เพื่ อตน ท่ า นว่า บุ ค คลนั้นได้ซ่ ึ ง สิ ท ธิ\nครอบครอง\nมาตรา 1377 วรรคแรก ถ้า ผูค้ รอบครองสละเจตนาครอบครอง หรื อ ไม่ ยุด ถื อ ทรั พ ย์สิ น ต่ อไป\nไซร้ การครอบครองย่อมสุ ดสิ้ นลง\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์","application":"โดยหลัก การได้กรรมสิ ทธิ์ในอสังหาริ มทรัพย์โดยการครอบครองปรปักษ์ตามมาตรา 1382 จะต้อง\nเป็ นการครอบครองทรัพย์สินของผูอ้ ื่นด้วยความสงบ เปิ ดเผย และมีเจตนาเป็ นเจ้าของ โดยต้องครอบครอง\nติ ด ต่ อ กัน เป็ นเวลา 10 ปี และในกรณี ที่ เ ป็ นที่ ดิ น นั้น จะต้อ งเป็ นที่ ดิ น ที่ มี ก รรมสิ ท ธิ์ ด้ว ยจึ ง จะสามารถ\nครอบครองปรปักษ์ได้\nตามอุทาหรณ์ การที่อ่างเข้าไปครอบครองทาประโยชน์ในที่ดิน น.ส.3 ของโอ่งได้ 5 ปี นั้น ถือเป็ นการเข้า\nยึดถือทรัพย์สินโดยเจตนายึดถือเพื่อตน อ่างจึงได้สิทธิครอบครองในที่ดินแปลงนั้นตามมาตรา 1367 โดยถือ\nเป็ นการแย่งสิ ทธิครอบครองในที่ดินของโอ่ง แต่ไม่ใช่กรณี การครอบครองปรปักษ์ เพราะที่ดินดังกล่าวมี\nเพียงสิ ทธิครอบครองเท่านั้น และเมื่อโอ่งได้มาบอกให้อ่างออกไปจากที่ดินแปลงนั้น อ่างก็ได้เลิกทานาและ\nรื้ อบ้า นของตนออกไปจากที่ ดิน แปลงนั้น แล้ว จึ ง เป็ นกรณี ที่ อ่า งสละเจตนาครอบครองในที่ ดิน แปลง\nดังกล่าวตามมาตรา 1377 วรรคแรก การครอบครองจึงสิ้ นสุ ดลง\nเมื่อผ่านไป 2 ปี อ่างก็กลับเข้าไปปลูกบ้านทานาอยู่บนที่ดินแปลงนั้นใหม่ เมื่ออ่างเจตนายึดถือเพื่อตนจึงได้\nสิ ทธิ ครอบครองในที่ดินแปลงดังกล่าวอีกครั้งตามมาตรา 1367 แต่เมื่อที่ดินแปลงนั้นเปลี่ยนเป็ นที่ ดินที่ มี\nโฉนด คือ มีกรรมสิ ทธิ์แล้ว การที่อ่างจะได้กรรมสิ ทธิ์โดยการครอบครองปรปักษ์ได้น้ นั จะต้องครอบครอง\nที่ดินของโอ่งด้วยความสงบ เปิ ดเผย และมีเจตนาเป็ นเจ้าของติดต่อกันเป็ นเวลา 10 ปี ตามมาตรา 1382\nแต่เมื่อข้อเท็จจริ งปรากฏว่า อ่างครอบครองที่ดินที่มีโฉนดของโอ่งในครั้งหลังนี้ได้เพียง 5 ปี อ่างจึงยังไม่ได้\nกรรมสิ ทธิ์ ดังนั้นโอ่งย่อมมี สิทธิ ในที่ดินแปลงนั้นดี กว่าอ่าง และเมื่อโอ่งฟ้ องศาลขับไล่อ่างให้ออกจาก\nที่ดินแปลงนั้น อ่างก็จะต้องออกจากที่ดินแปลงนั้น","conclusion":"สรุป โอ่งมีสิทธิในที่ดินแปลงนั้นดีกว่าอ่าง","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2553-1-4-40","year":"2553","semester":"ภาค 1","number":4,"page":40,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2553 ภาค 1 · ข้อ 4","sections":["1382","1401"],"otherSections":[],"question":"ข้ อ 4. นายหนึ่ง นายสอง และนายสาม มีที่ดินอยู่ขา้ งเคียงกัน นายหนึ่ งได้สูบน้ าผ่านลารางที่อยู่ในที่ดินของ\nนายดาเข้ามาใช้ทานาในที่ดินของนายหนึ่ง นายสอง และนายสาม ก็ยงั ได้อาศัยวิดน้ าจากลารางที่นายหนึ่ งสู บ\nน้ าผ่านที่ ดินของนายดาเข้ามาใช้ในที่ ดินของนายหนึ่ งไปใช้ทานาในที่ ดินของนายสองและนายสามด้วย\nเช่นเดียวกัน โดยทั้งนายสองและนายสามไม่เคยขออนุ ญาตนายดาเลย และนายดาก็ไม่เคยรู ้มาก่อนว่านาย\nหนึ่งชักน้ าผ่านที่ดินของตน และนายสองและนายสามยังวิดน้ าที่ผ่านจากที่ดินของนายดาไปยังที่ดินของนาย\nหนึ่ งเข้าไปใช้ในที่ดินของทั้งสองด้วย โดยทั้งนายหนึ่ งนายสอง และนายสาม ได้สูบน้ าวิดน้ าเข้าไปใช้ใน\nที่ดินของแต่ละคนมาได้เกินสิ บปี แล้ว นายดาคิดว่าการที่ นายสองและนายสามใช้น้ าที่ไหลผ่านลารางบน\nที่ดินของตนด้วยนั้นเป็ นการก่อให้เกิดภาระเพิ่มขึ้นกับที่ดินของตน นายดาจะห้ามไม่ให้นายสองและนาย\nสามวิดน้ าจากลารางที่ไหลผ่านที่ดินของนายดาเข้าไปในที่ดินของนายหนึ่ งไปใช้ในที่ดินของทั้งนายสอง\nและนายสามได้หรื อไม่ และข้ออ้างของนายดารับฟังได้เพียงใด เพราะเหตุใด","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1401 ภาระจายอมอาจได้มาโดยอายุความ ท่านให้นาบทบัญญัติว่าด้วยอายุความได้สิทธิ อนั\nกล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บงั คับโดยอนุโลม","application":"การได้ภาระจายอมโดยอายุความครอบครองปรปักษ์ตามมาตรา 1401 นั้น บัญญัติให้นาอายุความได้\nสิ ทธิตามมาตรา 1382 มาบังคับใช้โอยอนุโลม กล่าวคือ ต้องเป็ นกรณี ที่เจ้าของสามยทรัพย์ได้ใช้ประโยชน์\nในภารยทรัพย์ โดยความสงบ เปิ ดเผย และมีเจตนาจะได้สิทธิ ภาระจายอมในภารยทรัพย์ โดยต้องใช้\nประโยชน์ติดต่อกันเป็ นเวลา 10 ปี\nตามอุทาหรณ์ การที่นายหนึ่งได้สูบน้ าผ่านลารางที่อยูใ่ นที่ดินของนายดาเข้ามาใช้ทานาในที่ดินของตน โดย\nนายสองและนายสามก็ยงั ได้อาศัยวิดน้ าจาลารางที่นายหนึ่ งสู บน้ าผ่านที่ดินของนายดาเข้ามาใช้ในที่ดินของ\nนายหนึ่ งไปใช้ทานาในที่ดินของนายสองและนายสามด้วยนั้น เมื่อการกระทาดังกล่าวของนายหนึ่ ง นาย\nสองและนายสามนั้น นายดาไม่เคยรู ้มาก่อน และทั้งสามคนก็ไม่เคยขออนุ ญาตนายดา อีกทั้งก็ไปปรากฏ\nข้อเท็จจริ งว่า การกระทาของทั้งสามคนนั้นเป็ นการกระทาโดยถื อวิสาสะ ดังนั้นกรณี ดงั กล่าวถื อว่า นาย\nหนึ่ ง นายสอง และนายสาม ซึ่ งเป็ นเจ้าของสามยทรัพย์ได้ใช้ประโยชน์ในภารยทรัพย์ คือที่ดินของนาย\nดา โดยความสงบสุข เปิ ดเผย และเจตนาจะให้ได้มาซึ่งภาระจายอมแล้ว\nและเมื่อข้อเท็จจริ งปรากฏว่าทั้งสามคนได้สูบน้ าวิดน้ าเข้าไปใช้ในที่ดินของแต่ละคนมาได้เกินสิ บปี แล้ว ทั้ง\nสามคนย่อมได้ภาระจายอมในที่ดินของนายดาตามมาตรา 1401 ประกอบมาตรา 1382 กล่าวคือ นายดาต้อง\nยอมให้ท้ งั สามคนได้ใช้ประโยชน์ในที่ดินของนายดาในการสู บน้ าวิดน้ าเข้าไปใช้ในที่ดินของแต่ละคนได้\nต่อไป นายดาจะอ้างว่าการกระทาของนายสองและนายสามเป็ นการก่อให้เกิดภาระเพิ่มขึ้นกับที่ดินของตน\nไม่ได้ และจะห้ามไม่ให้นายสองและนายสามวิดน้ าจากลารางที่ไหลผ่านที่ดินของนายดา เข้าไปในที่ดิน\nของนายหนึ่งไปใช้ในที่ดินของทั้งนายสองและนายสามไม่ได้","conclusion":"สรุป ที่ดินของนายดาอยู่ในภาระจายอม นายดาจะห้ามไม่ให้นายสองและนายสามวิดน้ าจากลาราง\nที่ผา่ นที่ดินของนายดาดังกล่าวนั้นไม่ได้ และจะอ้างว่าเป็ นการก่อให้เกิดภาระเพิ่มขึ้นกับที่ดินของตนก็ไม่ได้\nเช่นเดียวกัน\nการสอบไล่ ภาคฤดูร้อน ปี การศึกษา 2552\nข้อสอบกระบวนวิชา LAW2001 (LA 201),(LW 204)\nกฎหมายแพ่งและพาณิชย์ว่าด้วยทรัพย์\nคาแนะนา ข้อสอบเป็ นอัตนัยล้วนมี 4 ข้อ","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2552-s-1-42","year":"2552","semester":"ภาคฤดูร้อน","number":1,"page":42,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาคฤดูร้อน · ข้อ 1","sections":["1304"],"otherSections":["1306"],"question":"ข้ อ 1. สมัครเป็ นเจ้าของที่ดินแปลงหนึ่ งซึ่งอยู่ติดกับทางสาธารณะที่เป็ นทางดินลูกรัง แต่สมัครได้ทาถนน\nผ่านที่ดินรกร้างว่างเปล่าซึ่งทางราชการยังไม่เคยออกเอกสารสิ ทธิให้แก่ราษฎรผูใ้ ด สมัครใช้รถยนต์ผา่ นเข้า\nออกที่ดินดังกล่าวติดต่อกันเป็ นเวลากว่า 12 ปี แล้ว เพราะเห็นว่าสะดวกกว่าการใช้ทางดินลูกรัง\nต่อมาทางราชการได้ลอ้ มรั้วเพื่อก่อสร้างสถานที่ราชการตรงที่ดินแปลงนั้น ทาให้สมัครไม่สามารถใช้ถนน\nดังกล่าวได้ สมัครจึงยื่นคาร้องต่อศาลเพื่อให้มีคาสั่งให้ทางราชการเปิ ดเส้นทางให้สมัครสามารถใช้ถนน\nผ่านเข้าออกได้เช่นเดิม เพราะตกเป็ นภาระจายอมแล้ว\nดังนี้ให้ท่านวินิจฉัยว่า ข้ออ้างของสมัครรับฟังได้หรื อไม่ เพราะเหตุใด","rule":"มาตรา 1304 สาธารณะสมบัติ ข องแผ่ น ดิ น นั้ น รวมทรั พ ย์สิ น ทุ ก ชนิ ด ของแผ่ น ดิ น ซึ่ ง ใช้เ พื่ อ\nสาธารณะประโยชน์ หรื อสงวนไว้เพื่อประโยชน์ร่วมกัน เช่น\n(1) ที่ดินรกร้างว่างเปล่า และที่ดินซึ่งมีผเู ้ วนคืนหรื อทอดทิ้ง หรื อกลับมาเป็ นของแผ่นดินโดยประการอื่นตาม\nกฎหมายที่ดิน\nมาตรา 1306 ท่านห้ามมิ ให้ยกอายุความขึ้นเป็ นข้อต่อสู ้กับแผ่นดิ นในเรื่ องทรั พย์สินอันเป็ นสา\nธารณสมบัติของแผ่นดิน","application":"โดยหลักแล้ว ทรัพย์สินที่เป็ นสาธารณสมบัติของแผ่นดินนั้น กฎหมายห้ามมิให้บุคคลใดยกอายุ\nความขึ้ น เป็ นข้อ ต่ อ สู ้ กับ แผ่ น ดิ น เพื่ อ ให้ ไ ด้ ม าซึ่ งกรรมสิ ท ธิ์ หรื อ ทรั พ ยสิ ท ธิ เ หนื อ ทรั พ ย์สิ น นั้ นตาม\nมาตรา 1306\nกรณีตามอุทาหรณ์ ถึงแม้สมัครจะทาถนนผ่านที่ดินรกร้างว่างเปล่าซึ่งทางราชการยังไม่เคยออกเอกสารสิ ทธิ\nให้แก่ราษฎรผูใ้ ด และใช้รถยนต์ผ่านเข้าออกที่ดินดังกล่าวติดต่อกันเป็ นเวลากว่า 12 ปี แล้วก็ตาม สมัครก็\nไม่ได้ภาระจายอมซึ่งถือเป็ นทรัพยสิ ทธิโดยอายุความปรปั กษ์ เพราะที่ดินดังกล่าวเป็ นสาธารณสมบัติของ\nแผ่นดินตามมาตรา 1304(1) ซึ่งห้ามมิให้บุคคลใดยกอายุความขึ้นเป็ นข้อต่อสู ้กบั แผ่นดิน ตามมาตรา 1306\nดังนั้น เมื่อทางราชการได้ลอ้ มรั้วเพื่อก่อสร้างสถานที่ ราชการตรงที่ดินแปลงนั้น สมัครจะยื่นคา\nร้องต่อศาลเพื่อให้มีคาสั่งให้ทางราชการเปิ ดเส้นทางให้สมัครสามารถใช้ถนนผ่านเข้าออกได้เช่นเดิมโดยอ้าง\nว่าที่ดินดังกล่าวตกเป็ นภาระจายอมแล้วไม่ได้","conclusion":"สรุป ข้ออ้างของสมัครรับฟังไม่ได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2552-s-3-44","year":"2552","semester":"ภาคฤดูร้อน","number":3,"page":44,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาคฤดูร้อน · ข้อ 3","sections":["1367","1375"],"otherSections":[],"question":"ข้ อ 3. เมื่อวันที่ 5 มกราคม 2540 คาปันได้นาพนักงานที่ดินรังวัดเพื่ออกโฉนดโดยผนวกที่ดิน น.ส.3 ของคา\nม่วนซึ่งอยูต่ ิดกับที่ดินของคาปัน เพราะเห็นว่าคาม่วนไม่ได้ดูแลหรื อทาประโยชน์ในที่ดินนั้นอย่างจริ งจัง\nโดยคาปั นเริ่ มเข้าครอบครองทาประโยชน์ในที่ดินของคาม่วนนับแต่วนั ที่นาเจ้าพนักงานที่ดินไปรังวัด ทาง\nราชการออกโฉนดให้คาปั นวันที่ 1 ตุลาคม 2540 ต่อมาวันที่ 10 มกราคม 2541 คาม่วนได้ไปขอรังวัดเพื่อ\nออกโฉนดบ้าง คาม่วนจึงรู ้วา่ คาปันออกโฉนดทับที่ดินของตน คาม่วนจึงเจรจาขอที่ดินคืนจากคาปัน แต่คา\nปั นปฏิเสธไม่ยอมคืนโดยอ้างว่าที่ดินพิพาทเป็ นของตนแล้ว หลังจากนั้นวันที่ 1 มิถุนายน 2542 คาม่วนจึง\nฟ้องศาลเพื่อเรี ยกคืนที่ดินพิพาทจากคาปัน\nดังนี้ให้วินิจฉัยว่า คาม่วนจะฟ้องเรี ยกคืนที่ดินพิพาทได้หรื อไม่ เพราะเหตุใด","rule":"มาตรา 1367 บุ ค คลใดยึดถื อทรั พ ย์สิ น โดยเจตนาจะยึดถื อ เพื่ อตน ท่ า นว่า บุ ค คลนั้นได้ซ่ ึ ง สิ ท ธิ\nครอบครอง\nมาตรา 1375 ถ้า ผู ้ค รอบครองถู ก แย่ ง การครอบครองโดยมิ ช อบด้ว ยกฎหมายไซร้ ท่ า นว่ า ผู ้\nครอบครองมีสิทธิจะได้คืนซึ่งการครอบครอง เว้นแต่อีกฝ่ ายหนึ่งมีสิทธิเหนือทรัพย์สินดีกว่า ซึ่งจะเป็ นเหตุ\nให้เรี ยกคืนจากผูค้ รอบครองได้\nการฟ้องคดีเพื่อเอาคืนซึ่งการครอบครองนั้น ท่านว่าต้องฟ้องภายในปี หนึ่งนับแต่เวลาถูกแย่งการครอบครอง","application":"โดยหลัก ถ้าผูถ้ ูกครอบครองถูกแย่งการครอบครองโดยมิช อบด้วยกฎหมาย กฎหมายให้สิทธิ ผู ้\nครอบครองฟ้องเรี ยกคืนซึ่งการครอบครองได้ภายใน 1 ปี นับแต่เวลาถูกแย่งการครอบครอง โดยไม่คานึงว่า\nผู ้ค รอบครองจะทราบว่า ถู ก แย่ง การครอบครองหรื อ ไม่ และไม่ ค านึ ง ว่ า ผูค้ รอบครองได้โ ต้แ ย้ง การ\nครอบครองหรื อไม่ตามมาตรา 1375\nกรณี ตามอุทาหรณ์ การที่คาปันนาเจ้าพนักงานที่ดินรังวัดที่ดินเพื่อออกโฉนดโดยผนวกที่ดิน น.ส.3 ของคา\nม่วนซึ่งมีเพียงสิ ทธิครอบครองไปด้วย ซึ่ งคาปั นได้เริ่ มเข้าครอบครองทาประโยชน์ในที่ดินของคาม่วน นับ\nแต่วนั ที่ นาเจ้า พนัก งานที่ ดินไปรั ง วัดคื อวันที่ 5 มกราคม 2540 นั้น กรณี เช่ นนี้ ถื อว่า ค าปั นได้เข้า ยึดถื อ\nทรั พ ย์สิ นโดยเจตนาจะยึดถื อเพื่ อตนแล้ว ค าปั นจึ ง ได้สิ ท ธิ ค รอบครองในที่ ดิน น.ส.3 ของค าม่ วนตาม\nมาตรา 1367 และกรณี น้ ี ยัง ถื อ ว่ า ค าปั น ได้ แ ย่ ง การครอบครองที่ ดิ น น.ส.3 ของค าม่ ว นด้ ว ยตาม\nมาตรา 1375 วรรคแรก โดยทางราชการได้ออกโฉนดให้คาปันในวันที่ 1 ตุลาคม 2540\nต่อมาวันที่ 10 มกราคม 2541 ค าม่ วนได้ไ ปขอรั ง วัดที่ ดินเพื่ อออกโฉนด จึ ง รู ้ ว่า ค าปั นแย่ง สิ ท ธิ\nครอบครองที่ดินของตน คาม่วนจึงเจรจาขอที่ ดินคื นจากคาปั น ซึ่ งกรณี น้ ี เป็ นเพียงการโต้แย้งผูแ้ ย่ง การ\nครอบครองเท่านั้น ดังนั้น เมื่อปรากฏข้อเท็จจริ งว่า คาม่วนได้ฟ้องศาลเพื่อเรี ยกที่ดินพิพาทคืนจากคาปันใน\nวันที่ 1 มิ ถุนายน 2542 ซึ่ ง เกิ น 1 ปี นับ แต่ถูก แย่งการครอบครอง ค าม่ วนจึ ง ไม่ มี อานาจฟ้ องเรี ยกคืนการ\nครอบครองที่พิพาทจากคาปันตามมาตรา 1375 วรรคสอง","conclusion":"สรุป คาม่วนจะฟ้องเรี ยกคืนที่ดินพิพาทจากคาปันไม่ได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2552-s-4-45","year":"2552","semester":"ภาคฤดูร้อน","number":4,"page":45,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาคฤดูร้อน · ข้อ 4","sections":["1382","1387","1401"],"otherSections":[],"question":"ข้ อ 4. ป้ อมตั้งแผงขายผลไม้อยู่ในที่ดินของแก่นโดยไม่ได้รับอนุ ญาตจากแก่น และต้องการเพียงใช้เป็ นที่\nขายผลไม้โดยไม่มีเจตนาจะยึดเป็ นเจ้าของแต่อย่างใด ป้ อมใช้พ้ืนที่ดงั กล่าวขายผลไม้ติดต่อกันได้ 10 กว่าปี\nแล้ว แก่นจึงแจ้งให้ป้อมย้ายออกไปจากที่ดินของตน แต่ป้อมอ้างว่าตนใช้ที่ดินดังกล่าวเป็ นเวลากว่า 10 ปี\nแล้ว จึงได้ภาระจายอมเหนื อที่ดินของแก่ น และเรี ยกให้แก่นไปจดทะเบียนภาระจายอมให้ป้อม ให้ท่าน\nวินิจฉัยว่า ข้ออ้างของป้ อมที่ว่าได้ภาระจายอมแล้วรับฟั งได้หรื อไม่ และป้ อมจะเรี ยกให้แก่นจดทะเบียน\nภาระจายอมให้กบั ตนได้หรื อไม่ เพราะเหตุใด","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1387 อสังหาริ มทรัพย์อาจต้องตกอยู่ในภาระจายอมอันเป็ นเหตุให้เจ้าของต้องยอมรับกรรม\nบางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรื อต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยูใ่ นกรรมสิ ทธิ์ทรัพย์สิน\nนั้นเพื่อประโยชน์แก่อสังหาริ มทรัพย์อื่น\nมาตรา 1401 ภาระจายอมอาจได้มาโดยอายุความ ท่านให้นาบทบัญญัติว่าด้วยอายุความได้สิทธิอนั\nกล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บงั คับโดยอนุโลม","application":"โดยหลัก การได้ภาระจายอมโดยอายุความ เป็ นการได้ทรัพยสิ ทธิเกี่ยวกับอสังหาริ มทรัพย์โดยทาง\nอื่ น นอกจากนิ ติ ก รรม ซึ่ งตามมาตรา 1401 บัญ ญัติ ใ ห้ น าบทบัญ ญัติ ว่ า ด้ ว ยอายุ ค วามได้ สิ ท ธิ ต าม\nมาตรา 1382 มาใช้บ ัง คับ โดยอนุ โลม กล่า วคื อ ต้องเป็ นการครอบครองทรั พ ย์สิ น ของผูอ้ ื่ น โดยความ\nสงบ เปิ ดเผย และเจตนาเป็ นเจ้าของและครอบครองติดต่อกันเป็ นเวลา 10 ปี\nแต่อย่างไรก็ตาม ภาระจายอมจะเกิดมีข้ ึนได้ก็เพื่อประโยชน์แก่อสังหาริ มทรัพย์อื่นซึ่ งเรี ยกว่าสามยทรั พย์\nเท่านั้น ตามมาตรา 1387 ดังนั้น ถ้าเป็ นการใช้อสังหาริ มทรัพย์เพื่อประโยชน์ส่วนตัวแม้จะใช้ติดต่อกันนาน\nเกินกว่า 10 ปี ก็ไม่ทาให้เกิดภาระจายอมโดยอายุความขึ้นได้\nกรณี ตามอุท าหรณ์ การที่ ป้ อมตั้ง แผงขายผลไม้อยู่ใ นที่ ดินของแก่ นโดยไม่ ไ ด้รับ อนุ ญาตจากแก่ นและ\nต้องการเพียงใช้เป็ นที่ขายผลไม้โดยไม่มีเจตนาจะยึดถือเป็ นเจ้าของแต่อย่างใด จึงไม่ใช่เป็ นการครอบครอง\nปรปักษ์ตามมาตรา 1382 เพราะป้อมไม่มีเจตนาเป็ นเจ้าของ\nและการที่ ป้ อ มใช้ ที่ ดิ น ของแก่ น เพื่ อ ตั้ ง แผงขายผลไม้ ก็ ไ ม่ ใ ช่ เ ป็ นการใช้ ที่ ดิ น เพื่ อ ประโยชน์ แ ก่\nอสังหาริ มทรัพย์อื่น แม้จะมีการใช้ที่ดินเพื่อขายผลไม้ติดต่อกันนานเกินกว่า 10 ปี แล้ว ที่ดินของป้ อมก็\nไม่ได้ภาระจายอมเหนื อที่ดินของแก่นโดยอายุความปรปั กษ์ตามมาตรา 1401 ประกอบมาตรา 1382 และ\nมาตรา 1387","conclusion":"สรุ ป ข้ออ้างของป้ องที่ว่าได้ภาระจายอมเหนื อที่ดินของแก่นแล้วรับฟั งไม่ได้ และป้ อมจะเรี ยกให้\nแก่นจดทะเบียนภาระจายอมให้กบั ตนไม่ได้เช่นกัน\nการสอบไล่ภาค 2 ปี การศึกษา 2552\nข้อสอบกระบวนวิชา LAW2001 (LA 201),(LW 204)\nกฎหมายแพ่งและพาณิชย์ว่าด้วยทรัพย์\nคาแนะนา ข้อสอบเป็ นอัตนัยล้วนมี 4 ข้อ","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2552-2-1-47","year":"2552","semester":"ภาค 2","number":1,"page":47,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาค 2 · ข้อ 1","sections":["1299","1382"],"otherSections":["1300","456"],"question":"ข้ อ 1. เชิดทาสัญญาขายที่ดินมีโฉนดแปลงหนึ่ งให้กบั ชัย โดยชาระราคากันครบถ้วนและส่ งมอบที่ดินกัน\nแล้ว แต่สัญญาดังกล่าวมิได้จดทะเบียนกับพนักงานเจ้าหน้าที่ หลังจากชัยเข้าครอบครองทาประโยชน์ใน\nที่ดินแปลงนี้ ได้ 9 ปี เชิดได้ทาสัญญาและจดทะเบียนกับพนักงานเจ้าหน้าที่ขายฝากที่ดินแปลงนี้ ให้แก่ โตมี\nกาหนด 2 ปี โดยโตไม่รู้ขอ้ เท็จจริ งเรื่ องการซื้อขายที่ดินระหว่างเชิดกับชัย\nหลังจากครบกาหนด 2 ปี ตามสัญญาขายฝากแล้ว เชิดไม่ใช้สิทธิ ไถ่คืนที่ดิน โตจะเข้าไปครอบครองที่ดิน\nแปลงนี้แต่พบชัยครอบครองทาประโยชน์ในที่ดินอยู่ โตจึงแจ้งให้ชยั ย้ายออกไปจากที่ดินแปลงนี้ แต่ชยั อ้าง\nว่าที่ดินเป็ นกรรมสิ ทธิ์ของตน\nเชิ ดไม่ มี สิ ท ธิ นาที่ ดินแปลงนี้ ไ ปขายให้กับ ผูใ้ ด และชัย ก็ ค รอบครองโดยสงบ เปิ ดเผยและมี เจตนาเป็ น\nเจ้าของติดต่อกันมาเกินกว่า 10 ปี แล้ว\nดังนี้ ให้วินิจฉัยว่า ระหว่างชัยกับโต ผูใ้ ดมีกรรมสิ ทธิ์ในที่ดินแปลงนี้ ดีกว่ากัน และชัยจะขอให้ศาล\nเพิกถอนการจดทะเบียนขายฝากระหว่างเชิดกับโตได้หรื อไม่ เพราะเหตุใด","rule":"มาตรา 1299 วรรคสอง ถ้ามีผไู ้ ด้มาซึ่งอสังหาริ มทรัพย์ หรื อทรัพยสิ ทธิอนั เกี่ยวกับอสังหาริ มทรัพย์\nโดยทางอื่นนอกจากนิ ติกรรม สิ ทธิ ของผูไ้ ด้มานั้น ถ้ายังมิได้จดทะเบียนไซร้ ท่านว่าจะมีการเปลี่ยนแปลง\nทางทะเบียนไม่ได้ และสิ ทธิ อนั ยังมิได้จดทะเบียนนั้น มิให้ยกเป็ นข้อต่อสู้บุคคลภายนอกผูไ้ ด้สิทธิมาโดย\nเสี ยค่าตอบแทนและโดยสุจริ ตและได้จดทะเบียนสิ ทธิโดยสุจริ ตแล้ว\nมาตรา 1300 ถ้ า ได้ จ ดทะเบี ย นการโอนอสั ง หาริ มทรั พ ย์ หรื อทรั พ ยสิ ทธิ อั น เกี่ ย วกั บ\nอสังหาริ มทรัพย์ เป็ นทางเสี ยเปรี ยบแก่ บุค คลผูอ้ ยู่ใ นฐานะอันจะให้จดทะเบี ยนสิ ทธิ ข องตนได้อยู่ ก่ อน\nไซร้ ท่านว่าบุคคลนั้นอาจเรี ยกให้เพิกถอนการจดทะเบียนนั้นได้\nแต่การโอนอันมีค่าตอบแทน ซึ่ งผูร้ ับโอนกระทาการโดยสุ จริ ตนั้น ไม่ว่ากรณี จะเป็ นประการใด ท่านว่าจะ\nเรี ยกให้เพิกถอนทะเบียนไม่ได้","application":"กรณี ตามอุทาหรณ์ เมื่อได้ความว่าสัญญาซื้ อขายที่ดินมีโฉนดซึ่ งเป็ นอสังหาริ มทรัพย์ระหว่างเชิด\nกับ ชัย แม้จะได้ช าระราคากันครอบถ้วนและส่ งมอบที่ ดินกันแล้ว แต่เมื่ อไม่ ไ ด้จดทะเบียนกับ พนักงาน\nเจ้าหน้าที่สัญญาซื้อขายดังกล่าวจึงตกเป็ นโมฆะตามมาตรา 456 วรรคแรก\nและตามข้อเท็จจริ ง เมื่อชัยผูซ้ ้ื อเข้าไปครอบครองทาประโยชน์ในที่ดินแปลงนี้ ติดต่อกันได้ 9 ปี เชิดได้ทา\nสัญญาและได้จดทะเบียนกับพนักงานเจ้าหน้าที่ขายฝากที่ดินแปลงนี้ให้แก่โตมีกาหนด 2 ปี โดยโตไม่รู้เรื่ อง\nการซื้อขายที่ดินระหว่างเชิดกับชัย และหลังจากครบกาหนด 2\nปี ตามสัญญาขายฝากแล้ว เชิดไม่ใช้สิทธิไถ่คืนที่ดิน และในขณะเดียวกันชัยก็ยงั คงครอบครองที่ดินแปลง\nนี้โดยสงบ เปิ ดเผย และเจตนาเป็ นเจ้าของติดต่อกันเป็ นเวลา 11 ปี กรณี เช่นนี้ จึงถือว่าชัยได้กรรมสิ ทธิ์ใน\nที่ดินแปลงนี้ โดยการครอบครองปรปั กษ์ตามมาตรา 1382 อันเป็ นการได้มาวึ่งอสังหาริ มทรัพย์โดยทางอื่น\nนอกจากนิติกรรม แต่เมื่อชัยยังไม่ได้จดทะเบียนเปลี่ยนชื่อในโฉนดเป็ นชื่อของตน ชัยจึงไม่สามารถยกการ\nได้ม านั้นขึ้ นเป็ นข้อต่ อสู ้ บุ ค คลภายนอกผูไ้ ด้สิ ท ธิ ใ นอสั ง หาริ ม ทรั พ ย์น้ ันมาโดยมี ค่ า ตอบแทนและโดย\nสุจริ ต และจดทะเบียนสิ ทธิโดยสุจริ ตแล้วตามมาตรา 1299 วรรคสอง (ฎ. 884/2523)\nดังนั้น เมื่อโตซึ่ งเป็ นบุคคลภายนอกเป็ นผูไ้ ด้สิทธิ ในที่ดินแปลงนี้ ไปโดยมีค่าตอบแทนและโดยสุ จริ ต และ\nได้จดทะเบียนโดยสุ จริ ตแล้ว จึงมีกรรมสิ ทธิ์ ในที่ดินแปลงนี้ ดีกว่าชัย และถึงแม้ชยั จะเป็ นผูอ้ ยู่ในฐานะอัน\nจะจดทะเบียนสิ ทธิ ได้ก่อน และการจดทะเบียนขายฝากระหว่างเชิดกับโตจะทาให้ชยั เสี ยเปรี ยบก็ตาม แต่\nชัยก็ไม่สามารถขอให้เพิกถอนการจดทะเบียนการขายฝากระหว่างเชิดกับโตได้ ทั้งนี้ เพราะโตจดทะเบียน\nโดยมีค่าตอบแทนและโดยสุจริ ตตามมาตรา 1300","conclusion":"สรุ ป ระหว่างชัยกับโต โตมีกรรมสิ ทธิ์ ในที่ดินแปลงนี้ ดีกว่าชัย และชัยจะขอให้ศาลเพิกถอนการ\nจดทะเบียนการขายฝากระหว่างเชิดกับโตไม่ได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2552-2-3-49","year":"2552","semester":"ภาค 2","number":3,"page":49,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาค 2 · ข้อ 3","sections":["1367","1375"],"otherSections":["1381"],"question":"ข้ อ 3. สมดีขายฝากที่ดินมือเปล่าของสมดีแปลงหนึ่ งให้แสงสี กาหนดเวลาไถ่คืน 5 ปี โดยทาสัญญาเป็ น\nหนังสื อลงลายมือชื่อคู่สัญญาทั้งสองและส่ งมอบที่ดินให้แสงสี เมื่อขายฝากไปได้ 4 ปี กับ 8 เดือ สมดีจะมา\nขอไถ่ที่ดินแปลงนี้ คืน แต่แสงสี ไม่ยอมให้ไถ่อา้ งว่า ภริ ยาของสมดีได้มาตกลงขายขาดที่ดินแปลงนี้ กับตน\nแล้ว\nและตนได้จ่ายเงินให้ภริ ยาสมดีไป 200,000 บาท สมดีหมดสิ ทธิ ไถ่คืนแล้ว ที่ดินแปลงนี้ เป็ นของตนอย่าง\nเด็ดขาด หลังจากแสงสี บอกกับสมดีว่าที่ดินแปลงนั้นเป็ นของตนมาได้ 1 ปี กับ 3 เดือน สมดีจึงได้อพยพ\nครอบครั วเข้า ไปครอบครองปลู ก บ้า นอยู่อาศัย ท าประโยชน์ บ นที่ ดิน แปลงนั้น สมดี เข้า ครอบครองท า\nประโยชน์บนที่ดินแปลงนั้นมาได้ 4 เดือน แสงดีได้มาฟ้องขับไล่ให้สมดีออกไปจากที่ดินแปลงนั้น\nให้ท่านวินิจฉัยว่า แสงสี จะฟ้องขับไล่สมดีให้ออกไปจากที่ดินแปลงนั้นได้หรื อไม่ เพราะเหตุใด","rule":"มาตรา 1367 บุ ค คลใดยึดถื อทรั พ ย์สิ นโดยเจตนาจะยึดถื อเพื่ อตน ท่ า นว่า บุ ค คลนั้นได้ซ่ ึ ง สิ ท ธิ\nครอบครอง\nมาตรา 1375 ถ้า ผู ้ค รอบครองถู ก แย่ ง การครอบครองโดยมิ ช อบด้ว ยกฎหมายไซร้ ท่ า นว่ า ผู ้\nครอบครองมีสิทธิจะได้คืนซึ่งการครอบครอง เว้นแต่อีกฝ่ ายหนึ่งมีสิทธิเหนือทรัพย์สินดีกว่า ซึ่งจะเป็ นเหตุ\nให้เรี ยกคืนจากผูค้ รอบครองได้\nการฟ้ อ งคดี เ พื่ อ เอาคื น ซึ่ งการครอบครองนั้ น ท่ า นว่ า ต้อ งฟ้ อ งภายในปี หนึ่ งนั บ แต่ เ วลาถู ก แย่ ง การ\nครอบครอง\nมาตรา 1381 บุ ค คลใดยึดถือทรั พย์สิ นอยู่ในฐานะเป็ นผูแ้ ทนผูค้ รอบครอง บุ ค คลนั้นจะเปลี่ ยน\nลักษณะแห่ งการยึดถือได้ ก็แต่โดยบอกกล่าวไปยัง ผูค้ รอบครองว่า ไม่เจตนาจะยึดถื อทรัพ ย์สิน แทนผู ้\nครอบครองต่อไป หรื อตนเองเป็ นผูค้ รอบครองโดยสุจริ ต อาศัยอานาจใหม่อนั ได้จากบุคคลภายนอก","application":"โดยหลักแล้ว ถ้าผูค้ รอบครองถูกแย่งการครอบครองโดยมิชอบด้วยกฎหมาย ผูค้ รอบครองมีสิทธิ\nฟ้องเรี ยกคืนซึ่ งการครอบครองภายใน 1 ปี นับแต่เวลาถูกแย่งการครอบครอง เว้นแต่อีกฝ่ ายหนึ่ ง มีสิทธิ\nเหนือทรัพย์สินดีกว่าซึ่งจะเป็ นเหตุให้เรี ยกคืนจากผูค้ รอบครองได้ (มาตรา 1375)\nกรณี ตามอุทาหรณ์ สมดีขายฝากที่ดินมือเปล่าของสมดีแปลงหนึ่งให้แสงสี กาหนดเวลาไถ่คืน 5 ปี โดยทา\nสั ญ ญาเป็ นหนั ง สื อลงลายมื อ ชื่ อคู่ สั ญ ญาทั้ งสองและส่ งมอบที่ ดิ น ให้ แ สงสี เมื่ อ ขายฝากไป\nได้ 4 ปี 8 เดือน สมดีจะมาขอไถ่ที่ดินคืน แต่แสงสี ไม่ยอมให้ไถ่โดยอ้างว่าภริ ยาของสมดีได้มาตกลงขาย\nที่ดินแปลงนี้ ให้กบั ตนแล้ว และตนได้จ่ายเงินให้ภริ ยาสมดีไป 2 แสนบาท สมดีหมดสิ ทธิ ไถ่คืนแล้ว ที่ดิน\nเป็ นของตนอย่างเด็ดขาดแล้ว กรณี จึงถือว่าแสงสี ได้เปลี่ยนเจตนาการยึดถือตามมาตรา 1381 แสงสี จึงได้ไป\nซึ่งสิ ทธิครอบครองตามมาตรา 1367\nเมื่อได้ความว่า ภายหลังจากแสงสี แย่งการครอบครองมาได้ 1 ปี 3 เดือน ซึ่งเลยระยะเวลาการฟ้องเรี ยกคืน\nการครอบครองตามมาตรา 1375 แล้ว สมดีได้อพยพเข้าไปครอบครองปลูกบ้านอยู่อาศัยทาประโยชน์ใน\nที่ ดินแปลงนั้น จึ ง เป็ นกรณี ที่ ส มดี เอาคื นซึ่ ง การครอบครองด้วยตนเอง แต่เมื่ อสมดี เข้า ครอบครองท า\nประโยชน์ ใ นที่ ดินแปลงนั้นมาได้เพี ย ง 4 เดื อน (ยัง ไม่ เกิ น 1 ปี ) ยัง ไม่ หมดระยะการฟ้ องเรี ย กคื นตาม\nมาตรา 1375 แสงสี จึงฟ้องขับไล่ให้สมดีออกไปจากที่ดินแปลงนั้นได้","conclusion":"สรุป แสงสี ฟ้องขับไล่ให้สมดีออกไปจากที่ดินแปลงนั้นได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2552-1-1-52","year":"2552","semester":"ภาค 1","number":1,"page":52,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาค 1 · ข้อ 1","sections":["1299","1382"],"otherSections":["1300"],"question":"ข้ อ 1. เพลิงครอบครองปรปั กษ์ที่ดินมี โฉนดของน้ าฝนเกิ นกว่า 10 ปี แล้ว แต่เพลิงยังไม่ได้ดาเนิ นการจด\nทะเบียนเปลี่ยนชื่อในโฉนดที่ดินเป็ นของตน หลังจากนั้นน้ าฝนถึงแก่ความตาย น้ าผึ้งบุตรของน้ าฝนได้จด\nทะเบี ย นรั บ มรดกที่ ดิ น แปลงนั้น ต่ อ มาอี ก 1 ปี น้ า ผึ้ ง ท าสั ญ ญาและจดทะเบี ย นขายที่ ดิ น แปลงนั้นให้\nเปลว โดยก่อนจดทะเบียนโอนกรรมสิ ทธิ์ เปลวได้ไปดูที่ดินแต่ไม่เห็นผูใ้ ดครอบครองที่ดินดังกล่าว แต่\nหลังจากน้ าผึ้งจดทะเบียนโอนกรรมสิ ทธิ์ ที่ดินให้เปลวแล้ว เปลวจึงรู ้ว่าเพลิงครอบครองปรปักษ์ที่ดินแปลง\nนั้น จึงห้ามไม่ให้เพลิงเข้าไปยุง่ เกี่ยวกับที่ดินแปลงนั้นอีก\nดังนี้ ให้วินิจฉัยว่า ระหว่างเปลวกับเพลิงผูใ้ ดมีกรรมสิ ทธิ์ ในที่ดินแปลงนั้นดีกว่ากัน และเพลิงจะ\nยื่ น ค าร้ อ งขอให้ ศ าลมี ค าสั่ ง เพิ ก ถอนการจดทะเบี ย นโอนกรรมสิ ท ธิ์ ที่ ดิ น ระหว่ า งน้ า ผึ้ ง กับ เปลวได้\nหรื อไม่ เพราะเหตุใด","rule":"มาตรา 1299 วรรคสอ ถ้ามีผไู ้ ด้มาซึ่งอสังหาริ มทรัพย์ หรื อทรัพยสิ ทธิอนั เกี่ยวกับอสังหาริ มทรัพย์\nโดยทางอื่นนอกจากนิติกรรม สิ ทธิ ของผูไ้ ด้มานั้น ถ้ายังมิได้จดทะเบียนไซร้ ท่านว่าจะมีการเปลี่ยนแปลง\nทางทะเบียนไม่ได้ และสิ ทธิ อนั ยังมิได้จดทะเบียนนั้น มิให้ยกเป็ นข้อต่อสู้บุคคลภายนอกผูไ้ ด้สิทธิมาโดย\nเสี ยค่าตอบแทนและโดยสุจริ ตและได้จดทะเบียนสิ ทธิโดยสุจริ ตแล้ว\nมาตรา 1300 ถ้ า ได้ จ ดทะเบี ย นการโอนอสั ง หาริ มทรั พ ย์ หรื อทรั พ ยสิ ทธิ อั น เกี่ ย วกั บ\nอสังหาริ มทรัพย์ เป็ นทางเสี ยเปรี ยบแก่ บุค คลผูอ้ ยู่ใ นฐานะอันจะให้จดทะเบี ยนสิ ทธิ ข องตนได้อยู่ ก่ อน\nไซร้ ท่านว่าบุคคลนั้นอาจเรี ยกให้เพิกถอนการจดทะเบียนนั้นได้\nแต่การโอนอันมีค่าตอบแทน ซึ่ งผูร้ ับโอนกระทาการโดยสุ จริ ตนั้น ไม่ว่ากรณี จะเป็ นประการใด ท่านว่าจะ\nเรี ยกให้เพิกถอนทะเบียนไม่ได้","application":"กรณี ตามอุทาหรณ์ เพลิงครอบครองปรปั กษ์ที่ดินมีโฉนดของน้ าฝนเกินกว่า 10 ปี จึงได้กรรมสิ ทธิ์\nในที่ดินดังกล่าวโดยการครอบครองปรปั กษ์ตามมาตรา 1382 และถือเป็ นการได้มาซึ่งอสังหาริ มทรัพย์โดย\nทางอื่นนอกจากนิ ติกรรมตามมาตรา 1299 วรรคสอง ดังนั้นเมื่ อไม่ได้จดทะเบี ยนการได้มาต่อพนักงาน\nเจ้าหน้าที่ เพลิงก็จะเปลี่ยนแปลงทางทะเบียนไม่ได้ และสิ ทธิ อนั ยังไม่ได้จดทะเบียนนั้น มิให้ยกขึ้นต่อสู ้\nบุคคลภายนอกผูไ้ ด้สิทธิมาโดยเสี ยค่าตอบแทนและโดยสุจริ ต และได้จดทะเบียนสิ ทธิโดยสุจริ ตแล้ว\nสาหรับกรณี ที่น้ าฝนเจ้าของที่ดินถึงแก่ความตาย และน้ าผึ้งบุตรของน้ าฝนจดทะเบียนรับมรดกที่ดินแปลง\nดังกล่าวมานั้น กรณี เช่นนี้ ถือว่าน้ าผึ้งรับโอนที่ดินดังกล่าวในฐานะทายาทโดยธรรมของน้ าฝน อันเป็ นการ\nรับทรัพย์มรดกตามกฎหมายว่าด้วยมรดก ซึ่ งทายาทต้องรับไปทั้งสิ ทธิ และตลอดจนความรับผิดต่างๆของ\nเจ้ามรดก ทั้งถือไม่ได้ว่าน้ าผึ้งเป็ นบุคคลภายนอกที่ได้กรรมสิ ทธิ์ ที่ ดินโดยมีค่าตอบแทน ดังนั้น ระหว่าง\nเพลิงกับน้ าผึ้ง เพลิงจึงมีกรรมสิ ทธิ์ในที่ดินดังกล่าวดีกว่าน้ าผึ้ง (ฎ. 1886/2536 ฎ. 1069 – 1070/2522)\nประเด็นที่ ต้องวินิจฉัย ประการแรกมี ว่า ระหว่า งเปลวและเพลิ ง ใครมี ก รรมสิ ท ธิ์ ในที่ ดินแปลงนี้ ดีกว่า\nกัน เห็นว่า ขณะที่เพลิงยังไม่ได้ดาเนินการเปลี่ยนชื่อในโฉนดเป็ นชื่อของตน น้ าผึ้งซึ่ งไม่มีสิทธิดีกว่าเพลิง\nได้ จ ดทะเบี ย นขายที่ ดิ น แปลงที่ ต กเป็ นกรรมสิ ท ธิ์ แก่ เ พลิ ง แล้ว ให้ เ ปลว โดยก่ อ นจดทะเบี ย นโอน\nกรรมสิ ทธิ์ เปลวได้ไปดูที่ดินแต่ไม่เห็นผูใ้ ดครอบครองที่ดินดังกล่าว แต่หลังจากน้ าผึ้งจดทะเบี ยนโอน\nกรรมสิ ทธิ์ที่ดินให้เปลวแล้ว เปลวจึงรู ้ว่าเพลิงครอบครองปรปั กษ์ที่ดินแปลงนั้น กรณี เช่นนี้ ถือว่าเปลวเป็ น\nบุคคลภายนอกซื้อที่ดินมาโดยสุจริ ต เสี ยค่าตอบแทนและจดทะเบียนสิ ทธิโดยสุจริ ต จึงได้รับความคุม้ ครอง\nตามมาตรา 1299 วรรคสอง ซึ่ งเป็ นบทยกเว้นหลักทัว่ ไปที่ว่า ผูร้ ับโอนไม่มีสิทธิ ดีกว่าผูโ้ อน ดังนั้นแม้\nเปลวจะรับโอนมาจากน้ าผึ้งผูท้ ี่ไม่มีสิทธิ ในที่ดินดีกว่าเพลิง เปลวก็ยงั มีสิทธิ ดีกว่าเพลิง เพลิงจะอ้างหลัก\nผูร้ ับโอนไม่มีสิทธิดีกว่าผูโ้ อนมาใช้ยนั เปลวไม่ได้\nประเด็นที่ตอ้ งวินิจฉัยประการต่อมามีว่า เพลิงจะยื่นคาร้องขอให้ศาลมีคาสั่งเพิกถอนการจดทะเบียนโอน\nกรรมสิ ทธิ์ ที่ดินระหว่างน้ าผึ้งกับเปลวได้หรื อไม่ เห็นว่า แม้เพลิงจะเป็ นผูอ้ ยู่ในฐานะอันจะให้จดทะเบียน\nสิ ทธิ ของตนได้อยู่ก่อนตามมาตรา 1300 และการจดทะเบียนโอนกรรมสิ ทธิ์ ระหว่างน้ าผึ้งกับเปลวจะทาให้\nเพลิงเสี ยเปรี ยบก็ตาม เพลิงก็ไม่สามารถยืน่ คาร้องขอให้ศาลมีคาสั่งเพิกถอนการจดทะเบียนดังกล่าว เพราะ\nการจดทะเบียนรับโอนกรรมสิ ทธิ์ของเปลวนั้นมีค่าตอบแทนและเป็ นการจดทะเบียนโดยสุ จริ ต (ฎ. 32/2490)","conclusion":"สรุ ป เปลวเป็ นผูม้ ีกรรมสิ ทธิ์ในที่ดินดีกว่าเพลิง และเพลิงจะยื่นคาร้องขอให้ศาลมีคาสั่งเพิกถอน\nการจดทะเบียนโอนกรรมสิ ทธิ์ระหว่างน้ าผึ้งกับเปลวไม่ได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2552-1-3-54","year":"2552","semester":"ภาค 1","number":3,"page":54,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาค 1 · ข้อ 3","sections":["1367","1375"],"otherSections":[],"question":"ข้ อ 3. ใสได้ตกลงขอทาถนนผ่านที่ดินของแสงซึ่งเป็ นที่ดินมือเปล่า แต่ก็ยงั ไม่ถึงทางสาธารณะ ใสจะต้อง\nทาถนนผ่านที่ดินของเสี ยงอีกแปลงหนึ่งซึ่งเป็ นที่ดินเปล่าจึงจะถึงทางสาธารณะได้ แต่ใสไม่สามารถติดต่อ\nเสี ยงได้จึงได้ทาถนนผ่านที่ดินของเสี ยงไปโดยพลการ และนอกจากนั้นเมื่อเห็นที่ดินของเสี ยงทิ้งร้างไว้ ใส\nจึงยังใช้ที่ดินของเสี ยงทั้งแปลงทาไร่ ขา้ วโพด ใสใช้ทางผ่านที่ดินของทั้งแสงและเสี ยงและทาไร่ ขา้ วโพดบน\nที่ดินของเสี ยงผ่านมาได้หา้ ปี\nถ้าเสี ยงฟ้องเรี ยกคืนและห้ามไม่ให้ใสเข้ามายุง่ เกี่ยวในที่ดินของตน ใสจะมีขอ้ ต่อสู้เสี ยงได้อย่างไร\nบ้าง เพราะเหตุใด","rule":"มาตรา 1367 บุ ค คลใดยึดถื อทรั พ ย์สิ น โดยเจตนาจะยึดถื อ เพื่ อตน ท่ า นว่า บุ ค คลนั้นได้ซ่ ึ ง สิ ท ธิ\nครอบครอง\nมาตรา 1375 ถ้า ผู ้ค รอบครองถู ก แย่ ง การครอบครองโดยมิ ช อบด้ว ยกฎหมายไซร้ ท่ า นว่ า ผู ้\nครอบครองมีสิทธิจะได้คืนซึ่งการครอบครอง เว้นแต่อีกฝ่ ายหนึ่งมีสิทธิเหนือทรัพย์สินดีกว่า ซึ่งจะเป็ นเหตุ\nให้เรี ยกคืนจากผูค้ รอบครองได้\nการฟ้ อ งคดี เ พื่ อ เอาคื น ซึ่ งการครอบครองนั้ น ท่ า นว่ า ต้อ งฟ้ อ งภายในปี หนึ่ งนั บ แต่ เ วลาถู ก แย่ ง การ\nครอบครอง","application":"กรณี ตามอุทาหรณ์ ประเด็นที่ตอ้ งวินิจฉัยมีว่า ถ้าเสี ยงฟ้องเรี ยกคืนและห้ามไม่ให้ใสเข้ามายุง่ เกี่ยว\nในที่ดินของตน ใสจะมีขอ้ ต่อสู้เสี ยงได้อย่างไรบ้าง เห็นว่า การที่ใสได้ตกลงขอทาถนนผ่านที่ดิ นของ\nแสง ซึ่งเป็ นที่ดินมือเปล่า แต่ก็ยงั ไม่ถึงทางสาธารณะ ใสจะต้องทาถนนผ่านที่ดินของเสี ยงอีกแปลงหนึ่งซึ่ง\nเป็ นที่ดินมือเปล่าจึงจะถึงทางสาธารณะได้ แต่ใสไม่สามารถติดต่อเสี ยงได้จึงได้ทาถนนผ่านที่ดินของเสี ยง\nไปโดยพลการ นอกจากนั้นเมื่ อ เห็ นที่ ดิน ของเสี ย งทิ้ ง ร้ า งไว้ ใสจึ ง ยัง ใช้ที่ ดินของเสี ย งทั้ง แปลงท าไร่\nข้าวโพด อันเป็ นการยึดถือทาประโยชน์ในทรัพย์สิน กรณี เช่นนี้ถือว่าใสได้เข้ายึดถือทรัพย์สินโดยเจตนาจะ\nยึดถือเพื่อตนแล้ว ใสจึงได้สิทธิ ครอบครองในที่ดินมือเปล่าของเสี ยงทั้งแปลงตามมาตรา 1367 และกรณี น้ ี\nยังถือว่าใสได้แย่งการครอบครองมือเปล่าของเสี ยงด้วยตามมาตรา 1375 วรรคแรก\nเมื่อเสี ยงผูค้ รอบครองถูกใสแย่งการครอบครองโดยมิชอบด้วยกฎหมาย กฎหมายให้สิทธิเสี ยงฟ้องเรี ยกคืน\nซึ่งการครอบครองได้ภายใน 1 ปี นับแต่เวลาถูกแย่งการครอบครอง โดยไม่คานึงว่าผูค้ รอบครองจะทราบว่า\nถูก แย่ง การครอบครองหรื อไม่ และไม่ ค านึ งถึ งว่า ผูค้ รอบครองได้โต้แย้ง ผูแ้ ย่งหารครอบครองหรื อได้\nร้ องเรี ย นต่อพนัก งานฝ่ ายปกครองว่า ถูก แย่ง การครอบครองหรื อไม่ (ฎ. 6412/2550 ฎ.108/2517) เมื่ อ\nข้อเท็จจริ งคดีน้ ี ปรากฏว่าใสได้ใช้ทางผ่านที่ดินมือเปล่าทั้งของแสงและเสี ยงและทาไร่ ขา้ วโพดบนที่ดินของ\nเสี ยงผ่านมาได้ 5 ปี เสี ยงจึงหมดสิ ทธิ ฟ้องเรี ยกคืนการครอบครองแล้วตามมาตรา 1375 วรรคสอง ถ้าเสี ยง\nฟ้องเรี ยกคืนซึ่งการครอบครองและห้ามมิให้ใสเข้ามายุง่ เกี่ยวในที่ดินของตน ใสย่อมสามารถยกข้อต่อสู้ได้\nว่าเสี ยงหมดสิ ทธิเรี ยกคืนซึ่งการครอบครองแล้ว และตนได้สิทธิครอบครองในที่ดินของเสี ยงแล้ว","conclusion":"สรุ ป ใสสามารถยกข้อต่อสู้ได้วา่ เสี ยงหมดสิ ทธิเรี ยกคืนซึ่งการครอบครองตามมาตรา 1375 และตน\nได้สิทธิครอบครองในที่ดินของเสี ยงแล้ว","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2552-1-4-56","year":"2552","semester":"ภาค 1","number":4,"page":56,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาค 1 · ข้อ 4","sections":["1368","1382"],"otherSections":["1384","1385"],"question":"ข้ อ 4. นายฟ้าครอบครองปรปักษ์ทานาบนที่ดินมีโฉนดแปลงหนึ่งของเหลืองมาเข้าปี ที่แปด นายฟ้าประสบ\nอุบตั ิเหตุ ต้องรักษาตัวอยู่ที่โรงพยาบาล นายฟ้าทราบว่าแม้ออกจากโรงพยาบาลแล้วร่ างกายตนคงทานา\nไม่ได้อีกแล้ว ขณะรักษาตัวอยู่ใ นโรงพยาบาลได้ 6 เดือน ได้ยกที่ ดินแปลงนั้นให้บุ ตรชายทานาต่ อ จาก\nตน บุตรชายนายฟ้าจึงเข้าไปครอบครองที่ดินแปลงนั้น และเอาที่ดินแปลงนั้นไปให้นายแดงเช่าแทน นาย\nแดงนาที่ดินแปลงนั้นไปปลูกยางพารา แดงเช่าที่ดินแปลงนั้นมาได้สามปี เหลืองได้ฟ้องคดีต่อศาลขับไล่ให้\nแดงและบุตรชายนายฟ้าออกจากที่ดินแปลงนั้น\nตามหลักกฎหมายแพ่งและพาณิ ชย์ บุตรชายนายฟ้าได้กรรมสิ ทธิ์ โดยการครอบครองปรปั กษ์ใน\nที่ดินแปลงนั้นแล้วหรื อยัง เพราะเหตุใด","rule":"มาตรา 1368 บุคคลอาจได้มาซึ่งสิ ทธิครอบครองโดยผูอ้ ื่นยึดถือไว้ให้\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1384 “ถ้า ผูค้ รอบครองขาดยึดถื อทรั พ ย์สิ นโดยไม่ ส มัค ร และได้คื นภายในเวลาปี หนึ่ ง\nนับตั้งแต่วนั ขาดยึดถือ หรื อได้คืนโดยฟ้องคดีภายในกาหนดนั้นไซร้ ท่านมิให้ถือว่าการครอบครองสะดุด\nหยุดลง”\nมาตรา 1385 ถ้าโอนการครอบครองแก่กัน ผูร้ ั บโอนจะนับเวลาซึ่ งผูโ้ อนครอบครองอยู่ก่อนนั้น\nรวมเข้า กับ เวลาครอบครองของตนก็ ไ ด้ ถ้า ผูร้ ั บ โอนนับ รวมเช่ น นั้น และถ้า มี ข ้อบกพร่ องในระหว่า ง\nครอบครองของผูโ้ อนไซร้ ท่านว่าข้อบกพร่ องนั้นอาจยกขึ้นเป็ นข้อต่อสู ้ผรู ้ ับโอนได้","application":"โดยหลั ก แล้ ว การได้ ก รรมสิ ทธิ์ ในอสั ง หาริ มทรั พ ย์ โ ดยการครอบครองปรปั กษ์ ต าม\nมาตรา 1382 จะต้องประกอบด้วยหลักเกณฑ์ดงั นี้ คือ\n1 เป็ นทรัพย์สินของผูอ้ ื่นโดยผูอ้ ื่นมีกรรมสิ ทธิ์\n2 ได้ครอบครองโดยความสงบ\n3 ครอบครองโดยเปิ ดเผย\n4 ครอบครองโดยเจตนาเป็ นเจ้าของ\n5 ครอบครองติดต่อกันมาเป็ นเวลา 10 ปี\nสาหรับการครอบครองติดต่อกันนั้น จะต้องเป็ นกรณี ที่ผคู ้ รอบครอง ไม่มีเจตนาสละการครอบครอง หรื อ\nขาดการยึดถือโดยสมัครใจ และนับระยะเวลาครอบครองติดต่อกันได้ หากเป็ นเพียงการขาดการยึดถือโดย\nไม่สมัคร เพราะมีเหตุมาขัดขวางโดยไม่สมัครใจ กฎหมายถื อว่าการขาดการยึดถือนั้นไม่ทาให้ขาดอายุ\nความ การครอบครองสะดุดหยุดลง หากได้ทรัพย์สินคืนภายใน 1 ปี นับแต่วนั ที่ขาดการยึดถือ ทั้งนี้ ตาม\nมาตรา 1384\nกรณี ตามอุทาหรณ์ ประเด็นที่ตอ้ งวินิจฉัยมีว่า บุตรชายนายฟ้าได้กรรมสิ ทธิ์โดยการครอบครองปรปักษ์ใน\nที่ดินแปลงนั้นหรื อยัง เห็นว่า นายฟ้าได้ครอบครองปรปักษ์ทานาบนที่ดินมีโฉนดแปลงหนึ่งของเหลืองมา\nเข้าปี ที่ 8 นายฟ้าประสบอุบตั ิเหตุตอ้ งรักษาตัวอยู่โรงพยาบาล กรณี น้ ีถือว่านายฟ้าขาดการยึดถือโดยไม่สมัคร\nใจเนื่องจากมีเหตุมาขัดขวางหรื อไม่มีเจตนาสละการครอบครอง เมื่อนายฟ้าเห็นว่าทานาต่อไปอีกไม่ได้ จึง\nยกที่ดินแปลงนั้นให้บุตรชายทานาต่อจากตนในขณะที่รักษาตัวอยู่ในโรงพยาบาลได้ 6 เดือน ดังนี้ ถือว่าการ\nขาดการยึดถือนั้นไม่ทาให้อายุความสะดุดหยุดลง เนื่องจากได้ทรัพย์สินคืนมาภายใน 1 ปี นับแต่วนั ที่ขาด\nการยึดถือ โดยมีบุตรชายนายฟ้าเข้ายึดถือแทนตามมาตรา 1384 และในกรณี เช่นนี้ บุตรชายนายฟ้าผูร้ ับโอน\nการครอบครองโดยนิ ติก รรมสามารถนับ เวลาซึ่ ง นายฟ้ า ผู โ้ อนครอบครองอยู่ ก่ อนนั้น รวมเข้า กับ เวลา\nครอบครองของตนก็ได้ ตามมาตรา 1385\nอนึ่ง การที่บุตรชายของนายฟ้ากลับเอาที่ดินแปลงนั้นไปให้นายแดงเช่าแทน นายแดงย่อมอยูใ่ นฐานะเป็ นผู ้\nยึดถือที่ดินแปลงนั้นแทนบุตรชายนายฟ้าตลอดมาตามมาตรา 1368 (ฎ. 1054/2519 ฎ.1623/2522) เมื่อแดง\nเช่าที่ดินแปลงนั้นมาได้ 3 ปี รวมกับเวลาที่นายฟ้าครอบครองมาแต่ก่อนและที่กฎหมายถือว่าไม่สะดุดหยุด\nลงอี ก 8 ปี 6 เดื อน รวมเป็ น 11 ปี 6 เดื อน ตามหลัก กฎหมายแพ่ ง และพาณิ ช ย์ บุ ตรชายนายฟ้ า ย่อ มได้\nกรรมสิ ทธิ์ในที่ดินแปลงนั้นโดยการครอบครองปรปักษ์ตามมาตรา 1382 แล้ว","conclusion":"สรุป บุตรชายนายฟ้าได้กรรมสิ ทธิ์โดยการครอบครองปรปักษ์แล้ว\nการสอบไล่ภาค 1 ปี การศึกษา 2552\nข้อสอบกระบวนวิชา LAW2001 (LA 201),(LW 204)\nกฎหมายแพ่งและพาณิชย์ว่าด้วยทรัพย์\nคาแนะนา ข้อสอบเป็ นอัตนัยล้วนมี 4 ข้อ","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2552-1-1-58","year":"2552","semester":"ภาค 1","number":1,"page":58,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาค 1 · ข้อ 1","sections":["1299","1382"],"otherSections":["1300"],"question":"ข้ อ 1 เพลิ งครอบครองปรปั กษ์ที่ดินมี โฉนดของน้ าฝนเกินกว่า 10 ปี แล้ว แต่เพลิงยังไม่ได้ดาเนิ นการจด\nทะเบียนเปลี่ยนชื่อในโฉนดที่ดินเป็ นของตน หลังจากนั้นน้ าฝนถึงแก่ความตาย น้ าผึ้งบุตรของน้ าฝนได้จด\nทะเบี ย นรั บ มรดกที่ ดิ น แปลงนั้น ต่ อ มาอี ก 1 ปี น้ า ผึ้ ง ท าสั ญ ญาและจดทะเบี ย นขายที่ ดิ น แปลงนั้นให้\nเปลว โดยก่อนจดทะเบียนโอนกรรมสิ ทธิ์ เปลวได้ไปดูที่ดินแต่ไม่เห็นผูใ้ ดครอบครองที่ดินดังกล่าว แต่\nหลังจากน้ าผึ้งจดทะเบียนโอนกรรมสิ ทธิ์ที่ดินให้เปลวแล้ว เปลวจึงรู ้ว่าเพลิงครอบครองปรปักษ์ที่ดินแปลง\nนั้น จึงห้ามไม่ให้เพลิงเข้าไปยุง่ เกี่ยวกับที่ดินแปลงนั้นอีก\nดังนี้ ให้วินิจฉัยว่า ระหว่างเปลวกับเพลิงผูใ้ ดมีกรรมสิ ทธิ์ ในที่ดินแปลงนั้นดีกว่ากัน และเพลิงจะ\nยื่ น ค าร้ อ งขอให้ ศ าลมี ค าสั่ ง เพิ ก ถอนการจดทะเบี ย นโอนกรรมสิ ท ธิ์ ที่ ดิ น ระหว่ า งน้ า ผึ้ ง กับ เปลวได้\nหรื อไม่ เพราะเหตุใด","rule":"มาตรา 1299 วรรคสอง ถ้ า มี ผู ้ไ ด้ ม าซึ่ งอสั ง หาริ มทรั พ ย์ หรื อทรั พ ยสิ ทธิ อั น เกี่ ย วกั บ\nอสังหาริ มทรัพย์โดยทางอื่นนอกจากนิ ติกรรม สิ ทธิ ของผูไ้ ด้มานั้น ถ้ายังมิได้จดทะเบียนไซร้ ท่านว่าจะมี\nการเปลี่ยนแปลงทางทะเบียนไม่ได้ และสิ ทธิอนั ยังมิได้จดทะเบียนนั้น มิให้ยกเป็ นข้อต่อสู้บุคคลภายนอกผู ้\nได้สิทธิมาโดยเสี ยค่าตอบแทนและโดยสุจริ ตและได้จดทะเบียนสิ ทธิโดยสุจริ ตแล้ว\nมาตรา 1300 ถ้ า ได้ จ ดทะเบี ย นการโอนอสั ง หาริ มทรั พ ย์ หรื อทรั พ ยสิ ทธิ อั น เกี่ ย วกั บ\nอสังหาริ มทรัพย์ เป็ นทางเสี ยเปรี ยบแก่ บุค คลผูอ้ ยู่ใ นฐานะอันจะให้จดทะเบี ยนสิ ทธิ ข องตนได้อยู่ ก่ อน\nไซร้ ท่านว่าบุคคลนั้นอาจเรี ยกให้เพิกถอนการจดทะเบียนนั้นได้\nแต่การโอนอันมีค่าตอบแทน ซึ่ งผูร้ ับโอนกระทาการโดยสุ จริ ตนั้น ไม่ว่ากรณี จะเป็ นประการใด ท่านว่าจะ\nเรี ยกให้เพิกถอนทะเบียนไม่ได้","application":"กรณีตามอุทาหรณ์ เพลิงครอบครองปรปักษ์ที่ดินมีโฉนดของน้ าฝนเกินกว่า 10 ปี จึงได้กรรมสิ ทธิ์ในที่ดิน\nดังกล่าวโดยการครอบครองปรปักษ์ตามมาตรา 1382 และถือเป็ นการได้มาซึ่งอสังหาริ มทรัพย์โดยทางอื่น\nนอกจากนิ ติ ก รรมตามมาตรา 1299 วรรคสอง ดัง นั้ น เมื่ อ ไม่ ไ ด้ จ ดทะเบี ย นการได้ม าต่ อ พนั ก งาน\nเจ้าหน้าที่ เพลิงก็จะเปลี่ยนแปลงทางทะเบียนไม่ได้ และสิ ทธิ อนั ยังไม่ได้จดทะเบียนนั้น มิให้ยกขึ้นต่อสู ้\nบุคคลภายนอกผูไ้ ด้สิทธิมาโดยเสี ยค่าตอบแทนและโดยสุจริ ต และได้จดทะเบียนสิ ทธิโดยสุจริ ตแล้ว\nสาหรับกรณี ที่น้ าฝนเจ้าของที่ดินถึงแก่ความตาย และน้ าผึ้งบุตรของน้ าฝนจดทะเบียนรับมรดกที่ดินแปลง\nดังกล่าวมานั้น กรณี เช่นนี้ ถือว่าน้ าผึ้งรับโอนที่ดินดังกล่าวในฐานะทายาทโดยธรรมของน้ าฝน อันเป็ นการ\nรับทรัพย์มรดกตามกฎหมายว่าด้วยมรดก ซึ่ งทายาทต้องรับไปทั้งสิ ทธิ และตลอดจนความรับผิดต่างๆของ\nเจ้ามรดก ทั้งถือไม่ได้ว่าน้ าผึ้งเป็ นบุคคลภายนอกที่ได้กรรมสิ ทธิ์ ที่ ดินโดยมีค่าตอบแทน ดังนั้น ระหว่าง\nเพลิงกับน้ าผึ้ง เพลิงจึงมีกรรมสิ ทธิ์ในที่ดินดังกล่าวดีกว่าน้ าผึ้ง (ฎ. 1886/2536 ฎ. 1069 – 1070/2522)\nประเด็นที่ ต้องวินิจฉัย ประการแรกมี ว่า ระหว่า งเปลวและเพลิ ง ใครมี ก รรมสิ ท ธิ์ ในที่ ดินแปลงนี้ ดีกว่า\nกัน เห็นว่า ขณะที่เพลิงยังไม่ได้ดาเนินการเปลี่ยนชื่อในโฉนดเป็ นชื่อของตน น้ าผึ้งซึ่ งไม่มีสิทธิดีกว่าเพลิง\nได้ จ ดทะเบี ย นขายที่ ดิ น แปลงที่ ต กเป็ นกรรมสิ ท ธิ์ แก่ เ พลิ ง แล้ว ให้ เ ปลว โดยก่ อ นจดทะเบี ย นโอน\nกรรมสิ ทธิ์ เปลวได้ไปดูที่ดินแต่ไม่เห็นผูใ้ ดครอบครองที่ดินดังกล่าว แต่หลังจากน้ าผึ้งจดทะเบี ยนโอน\nกรรมสิ ทธิ์ที่ดินให้เปลวแล้ว เปลวจึงรู ้ว่าเพลิงครอบครองปรปั กษ์ที่ดินแปลงนั้น กรณี เช่นนี้ ถือว่าเปลวเป็ น\nบุคคลภายนอกซื้อที่ดินมาโดยสุ จริ ต เสี ยค่าตอบแทนและจดทะเบียนสิ ทธิโดยสุจริ ต จึงได้รับความคุม้ ครอง\nตามมาตรา 1299 วรรคสอง ซึ่ งเป็ นบทยกเว้นหลักทัว่ ไปที่ว่า ผูร้ ับโอนไม่มีสิทธิ ดีกว่าผูโ้ อน ดังนั้นแม้\nเปลวจะรับโอนมาจากน้ าผึ้งผูท้ ี่ไม่มีสิทธิ ในที่ดินดีกว่าเพลิง เปลวก็ยงั มีสิทธิ ดีกว่าเพลิง เพลิงจะอ้างหลัก\nผูร้ ับโอนไม่มีสิทธิดีกว่าผูโ้ อนมาใช้ยนั เปลวไม่ได้\nประเด็นที่ตอ้ งวินิจฉัยประการต่อมามีว่า เพลิงจะยื่นคาร้องขอให้ศาลมีคาสั่งเพิกถอนการจดทะเบียนโอน\nกรรมสิ ทธิ์ ที่ดินระหว่างน้ าผึ้งกับเปลวได้หรื อไม่ เห็นว่า แม้เพลิงจะเป็ นผูอ้ ยู่ในฐานะอันจะให้จดทะเบียน\nสิ ทธิ ของตนได้อยูก่ ่อนตามมาตรา 1300 และการจดทะเบียนโอนกรรมสิ ทธิ์ระหว่างน้ าผึ้งกับเปลวจะทาให้\nเพลิงเสี ยเปรี ยบก็ตาม เพลิงก็ไม่สามารถยืน่ คาร้องขอให้ศาลมีคาสั่งเพิกถอนการจดทะเบียนดังกล่าว เพราะ\nการจดทะเบี ย นรั บ โอนกรรมสิ ทธิ์ ของเปลวนั้ นมี ค่ า ตอบแทนและเป็ นการจดทะเบี ย นโดย\nสุจริ ต (ฎ. 32/2490)","conclusion":"สรุ ป เปลวเป็ นผูม้ ีกรรมสิ ทธิ์ในที่ดินดีกว่าเพลิง และเพลิงจะยื่นคาร้องขอให้ศาลมีคาสั่งเพิกถอน\nการจดทะเบียนโอนกรรมสิ ทธิ์ระหว่างน้ าผึ้งกับเปลวไม่ได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2552-1-3-61","year":"2552","semester":"ภาค 1","number":3,"page":61,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาค 1 · ข้อ 3","sections":["1367","1375"],"otherSections":[],"question":"ข้ อ 3 ใสได้ตกลงขอทาถนนผ่านที่ดินของแสงซึ่งเป็ นที่ดินมือเปล่า แต่ก็ยงั ไม่ถึงทางสาธารณะ ใสจะต้อง\nทาถนนผ่านที่ดินของเสี ยงอีกแปลงหนึ่งซึ่งเป็ นที่ดินเปล่าจึงจะถึงทางสาธารณะได้ แต่ใสไม่สามารถติดต่อ\nเสี ยงได้จึงได้ทาถนนผ่านที่ดินของเสี ยงไปโดยพลการ และนอกจากนั้นเมื่อเห็นที่ดินของเสี ยงทิ้งร้างไว้ ใส\nจึงยังใช้ที่ดินของเสี ยงทั้งแปลงทาไร่ ขา้ วโพด ใสใช้ทางผ่านที่ดินของทั้งแสงและเสี ยงและทาไร่ ขา้ วโพดบน\nที่ดินของเสี ยงผ่านมาได้หา้ ปี\nถ้าเสี ยงฟ้องเรี ยกคืนและห้ามไม่ให้ใสเข้ามายุง่ เกี่ยวในที่ดินของตน ใสจะมีขอ้ ต่อสู้เสี ยงได้อย่างไร\nบ้าง เพราะเหตุใด","rule":"มาตรา 1367 บุคคลใดยึดถือทรัพย์สินโดยเจตนาจะยึดถื อเพื่ อตน ท่านว่าบุคคลนั้นได้ซ่ ึ ง สิ ท ธิ\nครอบครอง\nมาตรา 1375 ถ้า ผูค้ รอบครองถู ก แย่ ง การครอบครองโดยมิ ช อบด้ว ยกฎหมายไซร้ ท่ า นว่า ผู ้\nครอบครองมีสิทธิจะได้คืนซึ่งการครอบครอง เว้นแต่อีกฝ่ ายหนึ่งมีสิทธิเหนือทรัพย์สินดีกว่า ซึ่งจะเป็ นเหตุ\nให้เรี ยกคืนจากผูค้ รอบครองได้\nการฟ้ อ งคดี เ พื่ อ เอาคื น ซึ่ งการครอบครองนั้ น ท่ า นว่ า ต้อ งฟ้ อ งภายในปี หนึ่ งนั บ แต่ เ วลาถู ก แย่ ง การ\nครอบครอง","application":"กรณี ตามอุทาหรณ์ ประเด็นที่ตอ้ งวินิจฉัยมีว่า ถ้าเสี ยงฟ้องเรี ยกคืนและห้ามไม่ให้ใสเข้ามายุ่งเกี่ยวในที่ดิน\nของตน ใสจะมีขอ้ ต่อสู้เสี ยงได้อย่างไรบ้าง เห็นว่า การที่ใสได้ตกลงขอทาถนนผ่านที่ดินของแสง ซึ่งเป็ น\nที่ดินมือเปล่า แต่ก็ยงั ไม่ถึงทางสาธารณะ ใสจะต้องทาถนนผ่านที่ดินของเสี ยงอีกแปลงหนึ่งซึ่งเป็ นที่ดินมือ\nเปล่า จึ ง จะถึงทางสาธารณะได้ แต่ใ สไม่ ส ามารถติ ดต่อเสี ยงได้จึง ได้ท าถนนผ่านที่ ดินของเสี ย งไปโดย\nพลการ นอกจากนั้นเมื่อเห็นที่ดินของเสี ยงทิ้งร้างไว้ ใสจึงยังใช้ที่ดินของเสี ยงทั้งแปลงทาไร่ ขา้ วโพด อัน\nเป็ นการยึดถือทาประโยชน์ในทรัพย์สิน กรณี เช่นนี้ถือว่าใสได้เข้ายึดถือทรัพย์สินโดยเจตนาจะยึดถือเพื่อตน\nแล้ว ใสจึงได้สิทธิครอบครองในที่ดินมือเปล่าของเสี ยงทั้งแปลงตามมาตรา 1367 และกรณี น้ ียงั ถือว่าใสได้\nแย่งการครอบครองมือเปล่าของเสี ยงด้วยตามมาตรา 1375 วรรคแรก\nเมื่อเสี ยงผูค้ รอบครองถูกใสแย่งการครอบครองโดยมิชอบด้วยกฎหมาย กฎหมายให้สิทธิเสี ยงฟ้องเรี ยกคืน\nซึ่งการครอบครองได้ภายใน 1 ปี นับแต่เวลาถูกแย่งการครอบครอง โดยไม่คานึงว่าผูค้ รอบครองจะทราบ\nว่าถูกแย่งการครอบครองหรื อไม่ และไม่คานึ งถึงว่าผูค้ รอบครองได้โต้แย้งผูแ้ ย่งหารครอบครองหรื อได้\nร้องเรี ย นต่อพนัก งานฝ่ ายปกครองว่า ถูก แย่ง การครอบครองหรื อไม่ (ฎ. 6412/2550 ฎ. 108/2517) เมื่ อ\nข้อเท็จจริ งคดีน้ ี ปรากฏว่าใสได้ใช้ทางผ่านที่ดินมือเปล่าทั้งของแสงและเสี ยงและทาไร่ ขา้ วโพดบนที่ดินของ\nเสี ยงผ่านมาได้ 5 ปี เสี ยงจึงหมดสิ ทธิ ฟ้องเรี ยกคืนการครอบครองแล้วตามมาตรา 1375 วรรคสอง ถ้า\nเสี ยงฟ้องเรี ยกคืนซึ่ งการครอบครองและห้ามมิให้ใสเข้ามายุ่งเกี่ยวในที่ดินของตน ใสย่อมสามารถยกข้อ\nต่อสู้ได้วา่ เสี ยงหมดสิ ทธิเรี ยกคืนซึ่งการครอบครองแล้ว และตนได้สิทธิครอบครองในที่ดินของเสี ยงแล้ว","conclusion":"สรุ ป ใสสามารถยกข้อต่อสู้ได้ว่าเสี ยงหมดสิ ทธิ เรี ยกคืนซึ่งการครอบครองตามมาตรา 1375 และ\nตนได้สิทธิครอบครองในที่ดินของเสี ยงแล้ว","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2552-1-4-62","year":"2552","semester":"ภาค 1","number":4,"page":62,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2552 ภาค 1 · ข้อ 4","sections":["1368","1382"],"otherSections":["1384","1385"],"question":"ข้อ 4 นายฟ้าครอบครองปรปักษ์ทานาบนที่ดินมีโฉนดแปลงหนึ่งของเหลืองมาเข้าปี ที่แปด นายฟ้าประสบ\nอุบตั ิเหตุ ต้องรักษาตัวอยู่ที่โรงพยาบาล นายฟ้าทราบว่าแม้ออกจากโรงพยาบาลแล้วร่ างกายตนคงทานา\nไม่ได้อีกแล้ว ขณะรักษาตัวอยู่ในโรงพยาบาลได้ 6 เดือน ได้ยกที่ดินแปลงนั้นให้บุตรชายทานาต่ อจาก\nตน บุตรชายนายฟ้าจึงเข้าไปครอบครองที่ดินแปลงนั้น และเอาที่ดินแปลงนั้นไปให้นายแดงเช่าแทน นาย\nแดงนาที่ดินแปลงนั้นไปปลูกยางพารา แดงเช่าที่ดินแปลงนั้นมาได้สามปี เหลืองได้ฟ้องคดีต่อศาลขับไล่ให้\nแดงและบุตรชายนายฟ้าออกจากที่ดินแปลงนั้น\nตามหลักกฎหมายแพ่งและพาณิ ชย์ บุตรชายนายฟ้าได้กรรมสิ ทธิ์ โดยการครอบครองปรปั กษ์ใน\nที่ดินแปลงนั้นแล้วหรื อยัง เพราะเหตุใด","rule":"มาตรา 1368 บุคคลอาจได้มาซึ่งสิ ทธิครอบครองโดยผูอ้ ื่นยึดถือไว้ให้\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1384 “ถ้าผูค้ รอบครองขาดยึดถื อทรัพย์สิ นโดยไม่สมัค ร และได้คืนภายในเวลาปี หนึ่ ง\nนับตั้งแต่วนั ขาดยึดถือ หรื อได้คืนโดยฟ้องคดีภายในกาหนดนั้นไซร้ ท่านมิให้ถือว่าการครอบครองสะดุด\nหยุดลง”\nมาตรา 1385 ถ้าโอนการครอบครองแก่กนั ผูร้ ับโอนจะนับเวลาซึ่ งผูโ้ อนครอบครองอยู่ก่อนนั้น\nรวมเข้า กับ เวลาครอบครองของตนก็ ไ ด้ ถ้า ผูร้ ั บ โอนนับ รวมเช่ น นั้น และถ้า มี ข ้อบกพร่ องในระหว่า ง\nครอบครองของผูโ้ อนไซร้ ท่านว่าข้อบกพร่ องนั้นอาจยกขึ้นเป็ นข้อต่อสู ้ผรู ้ ับโอนได้","application":"โดยหลักแล้ว การได้กรรมสิ ทธิ์ ในอสังหาริ มทรัพย์โดยการครอบครองปรปั กษ์ตามมาตรา 1382 จะต้อง\nประกอบด้วยหลักเกณฑ์ดงั นี้ คือ\n1 เป็ นทรัพย์สินของผูอ้ ื่นโดยผูอ้ ื่นมีกรรมสิ ทธิ์\n2 ได้ครอบครองโดยความสงบ\n3 ครอบครองโดยเปิ ดเผย\n4 ครอบครองโดยเจตนาเป็ นเจ้าของ\n5 ครอบครองติดต่อกันมาเป็ นเวลา 10 ปี\nสาหรับการครอบครองติดต่อกันนั้น จะต้องเป็ นกรณี ที่ผคู ้ รอบครอง ไม่มีเจตนาสละการครอบครอง หรื อ\nขาดการยึดถือโดยสมัครใจ และนับระยะเวลาครอบครองติดต่อกันได้ หากเป็ นเพียงการขาดการยึดถือโดย\nไม่สมัคร เพราะมีเหตุมาขัดขวางโดยไม่สมัครใจ กฎหมายถื อว่าการขาดการยึดถือนั้นไม่ทาให้ขาดอายุ\nความ การครอบครองสะดุดหยุดลง หากได้ทรัพย์สินคืนภายใน 1 ปี นับแต่วนั ที่ขาดการยึดถือ ทั้งนี้ ตาม\nมาตรา 1384\nกรณี ตามอุทาหรณ์ ประเด็นที่ตอ้ งวินิจฉัยมีว่า บุตรชายนายฟ้าได้กรรมสิ ทธิ์โดยการครอบครองปรปักษ์ใน\nที่ดินแปลงนั้นหรื อยัง เห็นว่า นายฟ้าได้ครอบครองปรปักษ์ทานาบนที่ดินมีโฉนดแปลงหนึ่งของเหลืองมา\nเข้าปี ที่ 8 นายฟ้ าประสบอุบตั ิเหตุตอ้ งรักษาตัวอยู่โรงพยาบาล กรณี น้ ี ถือว่านายฟ้ าขาดการยึดถื อโดยไม่\nสมัครใจเนื่ องจากมีเหตุมาขัดขวางหรื อไม่มีเจตนาสละการครอบครอง เมื่อนายฟ้าเห็นว่าทานาต่อไปอีก\nไม่ ไ ด้ จึ ง ยกที่ ดิ น แปลงนั้ นให้ บุ ต รชายท านาต่ อ จากตนในขณะที่ รั ก ษาตั ว อยู่ ใ นโรงพยาบาล\nได้ 6 เดือน ดังนี้ ถือว่าการขาดการยึดถือนั้นไม่ทาให้อายุความสะดุดหยุดลง เนื่องจากได้ทรัพย์สินคืนมา\nภายใน 1 ปี นับแต่วนั ที่ขาดการยึดถือ โดยมีบุตรชายนายฟ้าเข้ายึดถือแทนตามมาตรา 1384 และในกรณี\nเช่นนี้ บุตรชายนายฟ้าผูร้ ับโอนการครอบครองโดยนิ ติกรรมสามารถนับเวลาซึ่ งนายฟ้าผูโ้ อนครอบครองอยู่\nก่อนนั้นรวมเข้ากับเวลาครอบครองของตนก็ได้ ตามมาตรา 1385\nอนึ่ง การที่บุตรชายของนายฟ้ากลับเอาที่ดินแปลงนั้นไปให้นายแดงเช่าแทน นายแดงย่อมอยูใ่ นฐานะเป็ นผู ้\nยึดถือที่ดินแปลงนั้นแทนบุตรชายนายฟ้าตลอดมาตามมาตรา 1368 (ฎ. 1054/2519 ฎ. 1623/2522) เมื่อแดง\nเช่าที่ดินแปลงนั้นมาได้ 3 ปี รวมกับเวลาที่นายฟ้าครอบครองมาแต่ก่อนและที่กฎหมายถือว่าไม่สะดุดหยุด\nลงอีก 8 ปี 6 เดือน รวมเป็ น 11 ปี 6 เดือน ตามหลักกฎหมายแพ่งและพาณิ ชย์ บุตรชายนายฟ้าย่อมได้\nกรรมสิ ทธิ์ในที่ดินแปลงนั้นโดยการครอบครองปรปักษ์ตามมาตรา 1382 แล้ว","conclusion":"สรุป บุตรชายนายฟ้าได้กรรมสิ ทธิ์โดยการครอบครองปรปักษ์แล้ว\nการสอบไล่ ภาคฤดูร้อน ปี การศึกษา 2551\nข้อสอบกระบวนวิชา LAW2001 (LA 201),(LW 204)\nกฎหมายแพ่งและพาณิชย์ว่าด้วยทรัพย์\nคาแนะนา ข้อสอบเป็ นอัตนัยล้วนมี 4 ข้อ","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2551-s-1-64","year":"2551","semester":"ภาคฤดูร้อน","number":1,"page":64,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาคฤดูร้อน · ข้อ 1","sections":["144"],"otherSections":[],"question":"ข้ อ 1 แห้วอนุญาตด้วยวาจาให้หอมอาศัยอยู่ในบ้านของตนไม่ได้กาหนดระยะเวลาไว้ หลังจากที่หอมเข้า\nไปอยู่ในบ้านหลังนั้นได้ 1 ปี เกิดพายุพดั หลังคาบ้านเสี ยหาย หอมจึงซ่ อมแซมหลังคาบ้านใหม่และติดตั้ง\nจานรับสัญญาณดาวเทียมบนระเบียงบ้านด้วย ต่อมาแห้วได้ทาสัญญาและจดทะเบียนขายบ้านและที่ดินให้\nแป้ง แป้งจึงแจ้งให้หอมย้ายออกไปจากบ้านหลังดังกล่าว\nดังนี้ หอมจะรื้ อจานรับสัญญาณดาวเทียมออกไปและเรี ยกให้แป้ งจ่ายเงินค่าซ่ อมแซมหลังคาบ้าน\nให้กบั ตนได้หรื อไม่ เพราะเหตุใด","rule":"มาตรา 144 ส่ ว นควบของทรั พ ย์ หมายความว่า ส่ ว นซึ่ ง โดยสภาพแห่ ง ทรั พ ย์ห รื อ โดยจารี ต\nประเพณี แห่ งท้องถิ่นเป็ นสาระสาคัญในความเป็ นอยู่ของทรัพย์น้ นั และไม่อาจแยกจากกันได้นอกจากจะ\nทาลาย ทาให้บุบสลาย หรื อทาให้ทรัพย์น้ นั เปลี่ยนแปลงรู ปทรงหรื อสภาพไป\nเจ้าของทรัพย์ยอ่ มมีกรรมสิ ทธิ์ในส่ วนควบของทรัพย์น้ นั","application":"ส่ วนควบ คือ ส่ วนซึ่ งโดยสภาพของทรัพย์สินหรื อจารี ตประเพณี แห่ งท้องถิ่นย่อมเป็ นสาระสาคัญในความ\nเป็ นอยูข่ องทรัพย์น้ นั และไม่อาจแบ่งแยกจากกันได้ นอกจากจะทาลาย ทาให้บุบสลายหรื อทาให้ทรัพย์น้ นั\nเปลี่ยนแปลงรู ปทรง ซึ่ งผูเ้ ป็ นเจ้าของตัวทรัพย์ย่อมเป็ นเจ้าของส่ วนควบนั้นด้วย ในทางกลับกันถ้าทรัพย์\nดังกล่าวไม่เป็ นสาระสาคัญในความเป็ นอยู่ของตัวทรัพย์ และสามารถแยกออกจากกันได้โดยไม่ทาให้ทรัพย์\nนั้นถูกทาลายหรื อบุบสลายหรื อเปลี่ ยนแปลงรู ปทรง กรณี เช่ นนี้ ย่อมไม่เป็ นส่ วนควบและผูเ้ ป็ นเจ้าของ\nทรัพย์ก็ไม่เป็ นเจ้าของทรัพย์น้ นั\nกรณี ตามอุทาหรณ์ การที่หอมซ่อมแซมหลังคาบ้านซึ่งเกิดพายุพดั หลังคาเสี ยหาย ซึ่งโดยหลักแล้วหลังคา\nบ้านย่อมถือว่าเป็ นสาระสาคัญในความเป็ นอยู่ของตัวบ้าน และไม่สามารถแยกออกจากตัวบ้านได้นอกจาก\nจะทาลาย ทาให้บุบสลายหรื อทาให้ทรัพย์น้ นั เปลี่ยนแปลงรู ปทรงไป เมื่อได้ความว่า หอมซ่อมแซมหลังคา\nบ้านไปโดยมิได้รับความยินยอมจากแห้วเจ้าของบ้าน กรณี เช่นนี้ หลังคาบ้านจึงตกเป็ นส่ วนควบของบ้าน\nตามมาตรา 144 วรรคแรก ดั ง นั้ น หลั ง คาบ้ า นจึ ง ตกเป็ นกรรมสิ ท ธิ์ ของแห้ ว เจ้ า ของบ้า นตาม\nมาตรา 144 วรรคสอง และเมื่อแห้วได้ทาสัญญาและจดทะเบียนขายบ้านและที่ดินให้แป้ง กรรมสิ ทธิ์ใน\nบ้านพร้อมทั้งส่ วนควบของบ้านจึงตกเป็ นของแป้งผูร้ ับโอน\nสาหรับค่าใช้จ่ายในการซ่ อมแซมบ้านนั้น เมื่อหอมซ่อมแซมบ้านดังกล่าวโดยมิได้รับความยินยอมจากแห้ว\nเจ้าของบ้านทั้งหลังคาบ้านที่ซ่อมก็ได้ตกเป็ นส่ วนควบของตัวบ้าน อันเป็ นกรรมสิ ทธิ์ของแป้งเจ้าของบ้าน\nผูร้ ับโอน นายหอมจึงไม่สามารถเรี ยกให้แป้ งจ่ายค่าซ่ อมแซมหลังคาบ้านได้แต่ประการใด ส่ วนจานรับ\nสั ญ ญาณดาวเที ย มที่ หอมน ามาติ ด ตั้ง ที่ ร ะเบี ย งบ้า น หอมจะรื้ อออกไปได้ห รื อ ไม่ น้ ัน เห็ น ว่า จานรั บ\nสัญญาณดาวเทียมโดยหลักแล้วย่อมไม่เป็ นสาระสาคัญในความเป็ นอยู่ของตัวบ้าน และหากหอมจะรื้ อไปก็\nไม่ ท าให้บ ้า นถูก ท าลายหรื อบุ บ สลายหรื อ เปลี่ ย นแปลงรู ป ทรงแต่ป ระการใด ดัง นั้น จานรั บ สัญ ญาณ\nดาวเทียมจึงไม่ถือเป็ นส่วนควบของบ้านยังคงเป็ นกรรมสิ ทธิ์ของนายหอมอยู่ หอมจึงสามารถรื้ อออกไปได้","conclusion":"สรุ ป หอมสามารถรื้ อจานรับสัญญาณดาวเทียมออกไปได้ แต่หอมไม่สามารถเรี ยกให้แป้งจ่ายเงิน\nค่าซ่อมแซมหลังคาบ้านให้กบั ตนได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2551-s-2-65","year":"2551","semester":"ภาคฤดูร้อน","number":2,"page":65,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาคฤดูร้อน · ข้อ 2","sections":["1299"],"otherSections":["1300"],"question":"ข้ อ 2 สาราญกับสารวยทาสัญญาประนีประนอมยอมความกัน โดยสาราญตกลงยกบ้านและที่ดินมีโฉนด\nให้สารวยแทนการชาระหนี้ และศาลได้มีคาสั่งพิพากษาตามยอมแล้ว แต่ท้ งั สองยังไม่ได้จดทะเบียนโอน\nกรรมสิ ทธิ์ ให้แก่กนั หลังจากนั้น 1 ปี สาราญถึงแก่ความตาย สาเริ งบุตรชายของสาราญได้จดทะเบียนรับ\nมรดกบ้านและที่ดินดังกล่าว ทั้งที่รู้ขอ้ เท็จจริ งเรื่ องทาสัญญาประนีประนอมระหว่างสาราญกับสารวย\nดังนี้ ให้วินิจฉัยว่า สารวยจะขอให้เพิกถอนการจดทะเบียนรับมรดกของสาเริ งได้หรื อไม่ เพราะ\nเหตุใด","rule":"มาตรา 1299 วรรคแรก ภายในบังคับแห่ งบทบัญญัติในประมวลกฎหมายนี้ หรื อกฎหมายอื่น ท่าน\nว่ า การได้ ม าโดยนิ ติ ก รรมซึ่ งอสั ง หาริ มทรั พ ย์ห รื อทรั พ ยสิ ท ธิ อัน เกี่ ย วกั บ อสั ง หาริ มทรั พ ย์ น้ ั นไม่\nบริ บูรณ์ เว้นแต่นิติกรรมจะได้ทาเป็ นหนังสื อและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่\nมาตรา 1300 ถ้ า ได้ จ ดทะเบี ย นการโอนอสั ง หาริ มทรั พ ย์ หรื อทรั พ ยสิ ทธิ อั น เกี่ ย วกั บ\nอสังหาริ มทรัพย์ เป็ นทางเสี ยเปรี ยบแก่ บุค คลผูอ้ ยู่ใ นฐานะอันจะให้จดทะเบี ยนสิ ทธิ ข องตนได้อยู่ ก่ อน\nไซร้ ท่านว่าบุคคลนั้นอาจเรี ยกให้เพิกถอนการจดทะเบียนนั้นได้\nแต่การโอนอันมีค่าตอบแทน ซึ่ งผูร้ ับโอนกระทาการโดยสุ จริ ตนั้น ไม่ว่ากรณี จะเป็ นประการใด ท่านว่าจะ\nเรี ยกให้เพิกถอนทะเบียนไม่ได้","application":"การได้อสังหาริ มทรัพย์หรื อทรัพยสิ ทธิเกี่ยวกับอสังหาริ มทรัพย์โดยนิติกรรมไม่บริ บูรณ์ เว้นแต่นิติกรรมนั้น\nจะได้ท าเป็ นหนัง สื อ และจดทะเบี ย นการได้ม ากับ พนัก งานเจ้า หน้า ที่ ซึ่ งค าว่ า “ไม่ บ ริ บู ร ณ์ ” ตาม\nมาตรา 1299 วรรคแรกนี้ หมายถึงไม่บริ บูรณ์ในฐานะทรัพยสิ ทธิ กล่าวคือ ไม่อาจใช้ยนั ต่อบุคคลทัว่ ไป\nได้ แต่ยงั คงมีผลบังคับกันได้ในระหว่างคู่กรณีในฐานะบุคคลสิ ทธิ\nกรณี ตามอุทาหรณ์ การที่สาราญทาสัญญาประนี ประนอมยอมความยกบ้านและที่ดินที่มีโฉนดให้สารวย\nแทนการชาระหนี้และศาลมีคาพิพากษาตามยอม กรณี เช่นนี้ ถือว่าสารวยเป็ นผูไ้ ด้มาซึ่งอสังหาริ มทรัพย์โดย\nทางนิ ติกรรม (คือการทาสัญญาประนี ประนอมยอมความ) แต่เนื่ องจากบุคคลทั้งสองยังไม่ได้จดทะเบียน\nโอนกรรมสิ ทธิ์ ให้แก่กนั นิ ติกรรมดังกล่าวจึงไม่บริ บูรณ์ในฐานะทรัพยสิ ทธิ แต่ยงั คงมีผลใช้ได้ระหว่าง\nคู่สัญญาคือ สาราญกับสารวยในฐานะบุคคลสิ ทธิตามมาตรา 1299 วรรคแรก (ฎ.9936/2539)\nหลังจากนั้น 1 ปี สาราญได้ถึงแก่ความตาย สาเริ งบุตรของสาราญได้จดทะเบียนรับมรดกบ้านและที่ดิน\nดังกล่าว ทั้งที่ รู้ขอ้ เท็จจริ งเรื่ องสัญญาประนี ประนอมยอมความระหว่างสารวยกับสาราญ ปั ญหาที่ตอ้ ง\nวินิจฉัย จึ ง มี ว่า ส ารวจจะขอให้เ พิ ก ถอนการจดทะเบี ย นรั บ มรดกของส าเริ ง ได้ห รื อ ไม่ เห็ นว่า ส าเริ ง\nนอกจากมิใช่บุคคลภายนอกที่ได้กรรมสิ ทธิ์ ในอสังหาริ มทรัพย์โดยมีค่าตอบแทนแล้ว สาเริ งยังเป็ นผูไ้ ด้\nกรรมสิ ทธิ์โดยไม่สุจริ ตอีกด้วย ดังนั้นสารวยจึงมีกรรมสิ ทธิ์ ในบ้านและที่ดินดีกว่าสาเริ ง เมื่อสารวยเป็ นผู ้\nอยู่ในฐานะอันจะให้จดทะเบียนสิ ทธิ ของตนได้ก่อน และการจดทะเบียนรับมรดกของสาเริ งทาให้สารวย\nเสี ยเปรี ยบ สารวยจึงขอให้เพิกถอนการจดทะเบียนรับมรดกของสาเริ งได้ตามมาตรา 1300 (ฎ. 6655/2542)","conclusion":"สรุป สารวยขอให้เพิกถอนการจดทะเบียนรับมรดกของสาเริ งได้\nหมายเหตุ ผลของการทาสัญญาประนี ป ระนอมยอมความในศาลนั้นเป็ นเรื่ องเจตนาของคู่ก รณี ซึ่ งศาล\nพิพากษาไปตามนั้น ยังไม่ถือว่าเป็ นการได้ทรัพยสิ ทธิมาโดยคาพิพากษา ศาลเพียงแต่ถือว่าผูน้ ้ นั อยูใ่ นฐานะ\nที่จะจดทะเบียนสิ ทธิของตนดีกว่าผูอ้ ื่นตามมาตรา 1300 จึงไม่เป็ นการได้มาโดยทางอื่นนอกจากนิ ติกรรม\nตามมาตรา 1299 วรรคสอง","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2551-s-3-66","year":"2551","semester":"ภาคฤดูร้อน","number":3,"page":66,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาคฤดูร้อน · ข้อ 3","sections":["1375"],"otherSections":["1381"],"question":"ข้ อ 3 ต้น ท าสั ญ ญาขายฝากบ้า นและที่ ดิ น มี น.ส.3 ของตนให้ กับ ตั้ม มี ก าหนดเวลา 1 ปี เมื่ อ ครบ\nกาหนดเวลาตามสัญญาขายฝากแล้ว ต้นไม่นาเงินไปไถ่ถอน แต่ตน้ ไม่มีที่อยู่อาศัย ตั้มจึงอนุญาตให้ตน้ อยู่\nอาศัยต่อไปโดยไม่คิดค่าเช่า หลังจากนั้นอีก 1 ปี ต้นถึงแก่ความตาย ตาลบุตรของต้นได้อาศัยอยู่ในบ้าน\nและที่ดินนั้นต่อจากต้น ต่อมาอีก 6 เดือน ตั้มได้บอกให้ตาลย้ายออกไปจากบ้านและที่ดินของตน มิฉะนั้น\nให้ตาลทาสัญญาเช่ากับตน แต่ตาลไม่ยอมทาสัญญาเช่าโดยอ้างว่าตนเป็ นผูร้ ับมรดกบ้านและที่ดินมาจากต้น\nบิ ดาของตน และตาลยัง คงอาศัย อยู่ใ นบ้า นและที่ ดิ นพิ พ าท ต่อมาอี ก 7 เดื อนตั้ง จึ ง มาปรึ ก ษาท่ า นว่ า\nต้องการจะฟ้องขับไล่และเรี ยกที่ดินคืนจากตาล\nดังนี้ ให้ท่านวินิจฉัยว่าตั้งจะฟ้องขับไล่ตาลและเรี ยกที่ดินคืนได้หรื อไม่ เพราะเหตุใด","rule":"มาตรา 1375 ถ้า ผูค้ รอบครองถู ก แย่ ง การครอบครองโดยมิ ช อบด้ว ยกฎหมายไซร้ ท่ า นว่า ผู ้\nครอบครองมีสิทธิจะได้คืนซึ่งการครอบครอง เว้นแต่อีกฝ่ ายหนึ่งมีสิทธิเหนือทรัพย์สินดีกว่า ซึ่งจะเป็ นเหตุ\nให้เรี ยกคืนจากผูค้ รอบครองได้\nการฟ้ อ งคดี เ พื่ อ เอาคื น ซึ่ งการครอบครองนั้ น ท่ า นว่ า ต้อ งฟ้ อ งภายในหนึ่ งปี นั บ แต่ เ วลาถู ก แย่ ง การ\nครอบครอง\nมาตรา 1381 บุคคลใดยึดถือทรัพย์สินอยู่ในฐานะเป็ นผูแ้ ทนผูค้ รอบครอง บุคคลนั้นจะเปลี่ ยน\nลักษณะแห่ งการยึดถือได้ ก็แต่โดยบอกกล่าวไปยัง ผูค้ รอบครองว่า ไม่เจตนาจะยึดถื อทรัพ ย์สิน แทนผู ้\nครอบครองต่อไป หรื อตนเองเป็ นผูค้ รอบครองโดยสุจริ ต อาศัยอานาจใหม่อนั ได้จากบุคคลภายนอก","application":"โดยหลักแล้ว ถ้าผูค้ รอบครองถูกแย่งการครอบครองโดยมิชอบด้วยกฎหมาย ย่อมมีสิทธิฟ้องเรี ยกคืนซึ่งการ\nครอบครองได้ภายในเวลา 1 ปี นับแต่เวลาถูกแย่งการครอบครอง\nกรณีตามอุทาหรณ์ ประเด็นที่ตอ้ งวินิจฉัยมีวา่ ตั้มจะฟ้องขับไล่ตาลและเรี ยกที่ดินคืนได้หรื อไม่ เห็นว่า ต้น\nทาสัญญาขายฝากบ้านและที่ดินมี น.ส.3 ของตนให้กบั ตั้มมีกาหนดเวลา 1 ปี เมื่อครบกาหนดเวลาตาม\nสั ญ ญาขายฝากแล้ว ต้น ไม่ น าเงิ น ไปไถ่ ถ อน กรณี เ ช่ น นี้ ตั้ม จึ ง เป็ นผู ม้ ี สิ ท ธิ ค รอบครองเหนื อ บ้า นและ\nที่ดิน น.ส.3 ดังกล่าว ส่ วนการที่ต้ มั อนุญาตให้ตน้ อยูอ่ าศัยต่อไปโดยไม่คิดค่าเช่า ก็ไม่ทาให้ตน้ เป็ นผูม้ ีสิทธิ\nครอบครองเหนื อบ้านและที่ดินแต่อย่างใด ต้นจึงเป็ นเพียงผูค้ รอบครองแทนตั้มเท่านั้น และหลังจากที่ตน้\nถึงแก่ความตาย ตาลบุตรของต้นอาศัยอยู่ในบ้านและที่ดินต่อจากบิดา ซึ่ งเป็ นเพียงการครอบครองแทนตั้ม\nเช่นกัน ต่อมาอีก 6 เดือน ตั้มให้ตาลย้ายออกไปจากบ้านและที่ดินของตน มิฉะนั้นให้ตาลทาสัญญากับตน\nแต่ตาลไม่ยอมทาสัญญาเช่าโอยอ้างว่าตาลรับมรดกมาจากต้นบิดาของตน กรณี เช่นนี้ จึงถือว่าตาลได้เปลี่ยน\nเจตนาการครอบครองแทนตั้ม มาเป็ นการครอบครองเพื่ อ ตน ในฐานะเป็ นเจ้า ของบ้า นและที่ ดิ น ตาม\nมาตรา 1381 และถือว่าเป็ นการแย่งการครอบครองโดยมิชอบด้วยกฎหมายตามมาตรา 1375 วรรคแรก (ฎ.\n2065/2533)\nหลัง จากการแย่ง การครอบครองโดยการเปลี่ ย นเจตนาตามมาตรา 1375 ประกอบมาตรา 1381 ได้\nเพียง 7 เดือน ตั้งจึงสามารถฟ้ องขับไล่และเรี ยกที่ดินคืนจากตาลได้ เพราะเมื่อผูค้ รอบครองถูกแย่งการ\nครอบครองโดยมิ ช อบด้ ว ยกฎหมายแล้ว ก็ ย่ อ มมี สิ ท ธิ ฟ้ อ งเรี ยกคื น ซึ่ งการครอบครองได้ ภ ายใน\nเวลา 1 ปี นับแต่เวลาถูกแย่งการครอบครองตามมาตรา 1375 วรรคสอง","conclusion":"สรุ ป ตั้มสามารถฟ้องขับไล่และเรี ยกที่ดินคืนจากตาลได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2551-s-4-67","year":"2551","semester":"ภาคฤดูร้อน","number":4,"page":67,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาคฤดูร้อน · ข้อ 4","sections":["1382","1387","1401"],"otherSections":[],"question":"ข้อ 4 นายวันเป็ นเจ้าของบ้านและที่ดินมีโฉนดแปลงหนึ่ง ต่อมานายวันถึงแก่ความตาย นายเช้ากับนายเย็น\nเป็ นผูร้ ับมรดกบ้านและที่ดินร่ วมกันในฐานะทายาทโดยธรรม แต่นายเช้าเป็ นผูค้ รอบครองบ้านและที่ดินนั้น\nต่อจากนายวันเพียงผูเ้ ดียว หลังจากนั้นอีก 3 ปี นายเช้ากับนายเย็นแบ่งมรดกกันโดยจดทะเบียนแบ่งแยก\nโฉนดที่ดินเป็ นสองแปลง นายเช้าเป็ นเจ้าของกรรมสิ ทธิ์ แปลงที่มีบา้ นสร้างอยู่ ส่ วนนายเย็นเป็ นเจ้าของ\nที่ ดินแปลงที่ สองซึ่ งมี ถนนที่ นายเช้าใช้สัญจรไปมาตั้งแต่สมัยที่นายวันยังมี ชีวิตอยู่ หลังจากจดทะเบียน\nแบ่งแยกกรรมสิ ทธิ์ที่ดินกันได้ 8 ปี นายเย็นถึงแก่ความตาย นางราตรี บุตรของเย็นได้จดทะเบียนรับมรดก\nที่ดินของนายเย็น และล้อมรั้วห้ามไม่ให้ นายเช้าใช้ถนนผ่านที่ดินของตนอีกต่อไป เพราะที่ดินของนายเช้ามี\nทางออกสู่ ทางสาธารณะอยู่แล้ว แต่นายเช้าเห็นว่าเส้นทางนั้นไม่สะดวก และต้องการใช้ถนนผ่านที่ดินของ\nนางราตรี ต่อไป\nดัง นี้ ให้วินิจฉัย ว่า นายเช้า จะเรี ย กให้นางราตรี ร้ื อถอนรั้ วออกไปเพื่ อให้ ตนสามารถใช้ถ นน\nดังกล่าวต่อไปได้หรื อไม่ เพราะเหตุใด","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1387 อสังหาริ มทรัพย์อาจต้องตกอยูใ่ นภาระจายอมอันเป็ นเหตุให้เจ้าของต้องยอมรับกรรม\nบางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรื อต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยูใ่ นกรรมสิ ทธิ์ทรัพย์สิน\nนั้นเพื่อประโยชน์แก่อสังหาริ มทรัพย์อื่น\nมาตรา 1401 ภาระจายอมอาจได้มาโดยอายุความ ท่านให้นาบทบัญญัติวา่ ด้วยอายุความได้สิทธิ อนั\nกล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บงั คับโดยอนุโลม","application":"โดยหลักแล้ว การได้ภาระจายอมเหนือที่ดินแปลงหนึ่ง ตามมาตรา 1387 จะเกิดขึ้นได้ก็เพื่อประโยชน์แก่\nที่ดินแปลงอื่นหรื ออสังหาริ มทรัพย์อื่นเท่านั้น กล่าวคือ จะต้องมีที่ดิน 2 แปลง โดยที่ดินแปลงหนึ่งตกอยู่\nในภาระจายอมของที่ดินอีกแปลงหนึ่ง\nกรณี ตามอุทาหรณ์ ประเด็นที่ตอ้ งวินิจฉัยมีว่า นายเช้าจะเรี ยกให้นางราตรี ร้ื อถอนรั้ วออกไปเพื่อให้ ตน\nสามารถใช้ถนนดังกล่าวต่อไปได้หรื อไม่ เห็นว่า นายเช้ากับนายเย็นรับมรดกบ้านและที่ดินมีโฉนดร่ วมกัน\nในฐานะทายาทโดยธรรมของนายวัน เมื่อยังไม่มีการจดทะเบียนแบ่งแยกกรรมสิ ทธิ์กัน ทั้งนายเช้ากับนาย\nเย็นจึงเป็ นเจ้าของรวมในบ้านและที่ดินดังกล่าว แม้นายเช้าจะครอบครองบ้านและที่ดินเพียงผูเ้ ดียวเป็ นเวลา\nถึง 3 ปี ก็ถือเป็ นการครอบครองแทนนายเย็นเจ้าของรวมอีกคนหนึ่งเท่านั้น\nต่อมาเมื่อทั้งสองจดทะเบียนแบ่งแยกโฉนดที่ ดินเป็ นสัดส่ วนกัน โดยนายเช้าเป็ นเจ้าของกรรมสิ ทธิ์ ที่ ดิน\nแปลงที่บา้ นนั้นปลูกสร้างอยู่ ส่ วนนายเย็นเป็ นเจ้าของที่ดินอีกแปลงหนึ่งซึ่งมีถนนที่นายเช้าใช้สัญจรไปมา\nตั้งแต่สมัยที่นายวันยังมีชีวิตอยู่ ในกรณี น้ ีการได้ภาระจายอมโดยอายุความในถนนภายในที่ดินที่แบ่งแยกไว้\nนี้ ตอ้ งเริ่ มนับแต่เมื่ อได้แบ่งแยกที่ ดินและโอนกรรมสิ ทธิ์ กันแล้ว เพราะก่อนการแบ่งแยกคงมี ที่ดินแปลง\nเดียว จึงไม่อาจจะนับรยะเวลาก่อนการแบ่งแยกโฉนดเป็ นการเริ่ มต้นอายุความการได้มาซึ่ งภาระจายอมเพื่อ\nประโยชน์แก่ที่ดินได้ (ฎ. 1049/2513)\nสาหรับการได้ภาระจายอมโดยอายุความนั้น มาตรา 1401 ให้นาบทบัญญัติวา่ ด้วยอายุความได้สิทธิดงั กล่าว\nในลักษณะ 3 แห่ งบรรพนี้ มาใช้บงั คับโดยอนุ โลม กล่าวคือ จะต้องเป็ นกรณี ที่เจ้าของสามยทรัพย์ได้ใช้\nประโยชน์ในที่ดินภารยทรัพย์น้ นั โดยความสงบ และโดยเปิ ดเผย และด้วยเจตนาจะได้สิทธิภาระจายอมใน\nที่ดินดังกล่าว ติดต่อกันเป็ นเวลา 10 ปี ตามมาตรา 1382 ประกอบมาตรา 1401 เมื่อข้อเท็จจริ งปรากฏว่า\nหลังจากจดทะเบียนแบ่งแยกกรรมสิ ทธิ์ กันแล้ว นายเช้ายังคงใช้ถนนนั้นอยู่ต่อมาได้เพียง 8 ปี ซึ่ งยังไม่\nถึง 10 ปี ตามมาตรา 1401 ประกอบมาตรา 1382 ถนนนั้นจึงยังไม่เป็ นภาระจายอมโดยอายุความ (ฎ.\n1754/2505)\nเมื่อถนนไม่เป็ นภาระจายอม การที่นางราตรี บุตรของเย็นซึ่งรับมรดกที่ดินแปลงนั้นได้ลอ้ มรั้วห้ามไม่ให้นาย\nเช้าใช้ถนนผ่านที่ดินของตนต่อไป เพราะเห็นว่าที่ดินของนายเช้า มีทางออกสู่ ทางสาธารณะอยู่แล้ว จึง\nสามารถกระทาได้ในฐานะเจ้าของอสังหาริ มทรัพย์ ดังนั้นนายเช้าจะเรี ยกให้นางราตรี ร้ื อถอนรั้วออกไปโดย\nอ้างว่าทางสาธารณะนั้นไม่สะดวกเพื่อให้ตนสามารถใช้ถนนดังกล่าวต่อไปไม่ได้","conclusion":"สรุ ป นายเช้าเรี ยกให้นางราตรี ร้ื อถอนรั้ วออกไปไม่ได้ เพราะถนนไม่เป็ นภาระจายอมโดยอายุ\nความ\nการสอบไล่ภาค 2 ปี การศึกษา 2551\nข้อสอบกระบวนวิชา LAW2001 (LA 201),(LW 204)\nกฎหมายแพ่งและพาณิชย์ว่าด้วยทรัพย์\nคาแนะนา ข้อสอบเป็ นอัตนัยล้วนมี 4 ข้อ","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2551-2-1-70","year":"2551","semester":"ภาค 2","number":1,"page":70,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาค 2 · ข้อ 1","sections":["144","146","1299"],"otherSections":[],"question":"ข้ อ 1 เพชรทาสัญญาอนุญาตให้พลอยอาศัยอยู่ในบ้านของตนได้ตลอดชีวิตของพลอย แต่สัญญาดังกล่าว\nไม่ได้จดทะเบียนกับพนักงานเจ้าหน้าที่ หลังจากที่พลอยอาศัยอยู่ในบ้านหลังนั้นได้ 15 ปี พลอยเห็นว่า\nบ้านชารุ ดทรุ ดโทรมมาก จึงรื้ อถอนบ้านเก่าและสร้างบ้านหลังใหม่ข้ ึนแทนหลังเก่า โดยไม่ได้บอกกล่าว\nเพชรแต่อย่างใด ต่อมาอีก 5 ปี เพชรทาสัญญาและจดทะเบียนขายที่ดินแปลงนั้นพร้อมสิ่ งปลูกสร้างบน\nที่ดินให้กบั มรกต และมรกตแจ้งให้พลอยย้ายออกไปจากที่ดินและบ้านหลังนั้น แต่พลอยอ้างว่าตนมีสิทธิ\nอาศัยในบ้านหลังนั้นตลอดชี วิตตามสัญญาที่เพชรทาไว้กบั ตน ส่ วนบ้านตนเป็ นผูอ้ อกเงินก่อสร้างจึงเป็ น\nกรรมสิ ทธิ์ของตน เพชรไม่มีสิทธินาบ้านไปขายแต่อย่างใด\nดังนี้ ให้วินิจฉัยว่าพลอยจะอ้างสัญญาระหว่างเพชรกับพลอยขึ้นต่อสู ้มรกตเพื่อไม่ตอ้ งย้ายออกไป\nได้หรื อไม่ และระหว่างพลอยกับมรกตผูใ้ ดมีกรรมสิ ทธิ์ในบ้านพิพาทดีกว่ากัน เพราะเหตุใด","rule":"มาตรา 144 วรรคสอง เจ้าของทรัพย์ยอ่ มมีกรรมสิ ทธิ์ในส่ วนควบของทรัพย์น้ นั\nมาตรา 146 ทรัพย์ซ่ ึ งติดกับที่ดินหรื อติดกับโรงเรื อนเพียงชัว่ คราวไม่ถือว่าเป็ นส่ วนควบกับที่ดิน\nหรื อโรงเรื อนนั้น ความข้อนี้ให้ใช้บงั คับแก่โรงเรื อนหรื อสิ่ งปลูกสร้างอย่างอื่น ซึ่งผูม้ ีสิทธิในที่ดินของผูอ้ ื่น\nใช้สิทธิน้ นั ปลูกสร้างไว้ในที่ดินนั้นด้วย\nมาตรา 1299 วรรคแรก ภายในบังคับแห่ งบทบัญญัติในประมวลกฎหมายนี้ หรื อกฎหมายอื่น ท่าน\nว่ า การได้ ม าโดยนิ ติ ก รรมซึ่ งอสั ง หาริ มทรั พ ย์ห รื อทรั พ ยสิ ท ธิ อัน เกี่ ย วกั บ อสั ง หาริ มทรั พ ย์ น้ ั นไม่\nบริ บูรณ์ เว้นแต่นิติกรรมจะได้ทาเป็ นหนังสื อและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่","application":"กรณี ตามอุทาหรณ์ ประเด็นที่ตอ้ งวินิจฉัยประการแรกมีว่า พลอยจะอ้างสัญญาระหว่างเพชรกับพลอยขึ้น\nต่อสู้มรกตเพื่อไม่ตอ้ งย้ายออกได้หรื อไม่ เห็นว่า โดยหลักแล้ว การได้อสังหาริ มทรัพย์หรื อทรัพยสิ ทธิ อนั\nเกี่ยวกับอสังหาริ มทรัพย์มาโดยนิติกรรม หากไม่มีกฎหมายบัญญัติถึงความสมบูรณ์ของการได้มาไว้ ก็ตอ้ ง\nเป็ นไปตามมาตรา 1299 วรรคแรก กล่าวคือ หากมิได้ทานิติกรรมเป็ นหนังสื อและจดทะเบียนการได้มากับ\nพนัก งานเจ้า หน้า ที่ การได้ม าซึ่ ง อสัง หาริ ม ทรั พ ย์หรื อทรั พ ยสิ ท ธิ อันเกี่ ย วกับ อสัง หาริ ม ทรั พ ย์ ย่อมไม่\nบริ บูรณ์เป็ นทรัพยสิ ทธิ ไม่อาจใช้ยนั ต่อบุคคลภายนอกได้\nคงบังคับกันได้ในระหว่างคู่กรณี ในฐานะบุคคลสิ ทธิ เท่านั้น กรณี น้ ี เมื่อพลอยเป็ นผูม้ ีสิทธิ อาศัยในบ้านของ\nเพชรตามสัญญาที่เพชรทากับพลอย พลอยจึงเป็ นผูท้ ี่ได้มาซึ่งทรัพย์อนั เกี่ยวกับอสังหาริ มทรัพย์โดยทางนิติ\nกรรม แต่เนื่องจากนิติกรรมดังกล่าว ไม่ได้จดทะเบียนกับพนักงานเจ้าหน้าที่ การได้มาซึ่งสิ ทธิอาศัยจึงไม่\nบริ บู ร ณ์ ใ นฐานะทรั พ ยสิ ท ธิ ท าให้ ไ ม่ ส ามารถยกขึ้ น ต่ อ สู ้ บุ ค คลภายนอกได้ต ามมาตรา 1299 วรรค\nแรก กรณี เช่นนี้ พลอยจะอ้างสัญญาระหว่างเพชรกับพลอยซึ่ งเป็ นบุคคลสิ ทธิข้ ึนต่อสู ้มรกตบุคคลภายนอก\nไม่ได้ (ฎ. 1752/2523)\nประเด็นที่ ต้องวินิจฉัย ประการต่อมามี ว่า ระหว่า งพลอยกับ มรกตผูใ้ ดมี ก รรมสิ ท ธิ์ ในบ้า นพิ พ าทดี ก ว่า\nกัน เห็นว่า การที่พลอยเห็นบ้านชารุ ดทรุ ดโทรมมากจึงรื้ อถอนบ้านเก่าและสร้างบ้านหลังใหม่ข้ ึนแทนหลัง\nเก่าโดยไม่ได้บอกกล่าวเพชรแต่อย่างใด ซึ่ งข้อเท็จจริ งปรากฏบ้านที่สร้างขึ้นใหม่น้ ี มีลกั ษณะติดที่ดินเป็ น\nการถาวร เพราะไม่ปรากฏว่าเป็ นการปลูกสร้างเพียงชัว่ คราวและจะรื้ อถอนไป ทั้งพลอยก็ไม่มีสิทธิ หรื อ\nได้ รั บ อ านาจจากเพชรที่ จ ะปลู ก บ้า นลงในที่ ดิ น ของเพชรแต่ อ ย่ า งใด กรณี ไ ม่ เ ข้า ข้อ ยกเว้น ตาม\nมาตรา 146 ดังนั้น บ้านจึงเป็ นส่ วนควบของที่ ดิน โดยที่ดินเป็ นทรัพย์ประธาน เพชรเจ้าของที่ดินทรัพย์\nประธานจึงเป็ นเจ้าของส่วนควบคือบ้านด้วยตามมาตรา 144 วรรคสอง (ฎ. 1516 – 1517/2529)\nหลัง จากที่ พลอยสร้ างบ้า นได้ 5 ปี เพชรได้ท าสัญญาและจดทะเบี ยนขายที่ ดินแปลงนั้นพร้ อมสิ่ งปลูก\nสร้าง คือบ้านพิพาทให้กบั มรกต เมื่อได้ความว่า เพชรเป็ นเจ้าของส่ วนควบคือบ้านด้วยย่อมมีสิทธิที่จะจด\nทะเบียนขายบ้านพิพาทได้ ส่งผลทาให้มรกตผูส้ ื บสิ ทธิของเพชรเป็ นผูท้ ี่มีกรรมสิ ทธิ์ในที่ดินและบ้านพิพาท\nดีกว่าพลอย","conclusion":"สรุ ป พลอยจะอ้า งสั ญญาระหว่า งเพชรกับ พลอยขึ้ นต่ อสู ้ ม รกตเพื่ อไม่ ต้องย้า ยออกไม่ ไ ด้ และ\nระหว่างพลอยกับมรกต มรกตเป็ นผูม้ ีสิทธิในบ้านดีกว่า","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2551-2-3-72","year":"2551","semester":"ภาค 2","number":3,"page":72,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาค 2 · ข้อ 3","sections":["1377","1382","1387","1401","1368"],"otherSections":["1391"],"question":"ข้อ 3 นายจิ ตเช่ า ที่ ดิ นของนายแจ่ ม ปลูก บ้า นอยู่และได้เ ดิ นผ่า นที่ ดิ นของใจมาได้หกปี เพื่ อ เข้า ออกใน\nหมู่บา้ น ตอลดมาโดยไม่เคยขออนุ ญาตใจเลย สัญญาเช่าที่ดินแจ่มหมดอายุ นายจิตจึงได้ร้ื อบ้านออกไป\nและไปเช่าที่ดินในตัวเมืองเพื่อปลูกบ้านอยู่ แต่ก็ยงั คงประกอบอาชีพค้าขาย จึงยังต้องใช้ทางเดินผ่านที่ดิน\nของใจเข้า ออกในหมู่ บ ้า นเพื่ อ เข้า ไปค้า ขายเหมื อ นเดิ ม จิ ตใช้ท างผ่า นที่ ดิน ของใจมาช่ ว งหลัง นี้ ได้ห้ า\nปี ทางผ่านที่เป็ นดินเริ่ มเป็ นหลุมเป็ นบ่อเข้าออกไม่สะดวก จิตจึงได้จา้ งผูร้ ับเหมาทาถนนและตั้งใจจะเท\nคอนกรี ต แต่เมื่อใจทราบจึงได้ห้ามไม่ให้จิตเข้ามาในที่ดินของตนและให้ผูร้ ับเหมารื้ อย้ายข้าวของที่จะทา\nถนนผ่านออกไปและทาที่ดินให้ดีเหมือนเดิม\nระหว่า งจิ ต และใจ จิ ตจะรั ก ษาทางท าถนนและเทคอนกรี ตบนทางเข้า ออกบนที่ ดิน ของใจได้\nหรื อไม่ เพราะเหตุใด","rule":"มาตรา 1377 วรรคแรก ถ้าผูค้ รอบครองสละเจตนาครอบครอง หรื อไม่ยุดถือทรัพย์สินต่ อไป\nไซร้ การครอบครองย่อมสุ ดสิ้ นลง\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1387 อสังหาริ มทรัพย์อาจต้องตกอยูใ่ นภาระจายอมอันเป็ นเหตุให้เจ้าของต้องยอมรับกรรม\nบางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรื อต้องงดเว้นการใช้สิทธิบางอย่างอันมีอยูใ่ นกรรมสิ ทธิ์ทรัพย์สิน\nนั้นเพื่อประโยชน์แก่อสังหาริ มทรัพย์อื่น\nมาตรา 1391 เจ้าของสามยทรัพย์มีสิทธิทาการทุกอย่างอันจาเป็ นเพื่อรักษาและใช้ภาระจายอมแต่\nต้องเสี ยค่าใช้จ่ายของตนเอง ในการนี้ เจ้าของสามยทรัพย์จะก่อให้เกิดความเสี ยหายแก่ภารยทรัพย์ได้ก็แต่\nน้อยที่สุดตามพฤติการณ์\nมาตรา 1401 ภาระจายอมอาจได้มาโดยอายุความ ท่านให้นาบทบัญญัติวา่ ด้วยอายุความได้สิทธิ อนั\nกล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บงั คับโดยอนุโลม","application":"กรณี ต ามอุ ท าหรณ์ โดยหลัก แล้ว การใช้ภ ารยทรั พ ย์เ พื่ อ ให้ ไ ด้ภ าระจ ายอมนั้ น ไม่ จ าเป็ นที่ เ จ้า ของ\nสามยทรัพย์จะต้องเป็ นผูใ้ ช้เองเท่านั้น การที่นายจิตผูเ้ ช่าที่ดินของนายแจ่มได้เดินผ่านที่ดินของนายใจโดย\nเจตนาใช้เป็ นทางเข้าออกในหมู่บา้ น โดยไม่เคยขออนุญาตนายใจเลยเป็ นระยะเวลา 6 ปี ถือว่านายแจ่ม\nเจ้าของที่ดินใช้ทางโดยปรปักษ์โดยมีนายจิตเป็ นผูใ้ ช้ทางแทน (ตามมาตรา 1368 ประกอบมาตรา 1401)\nการที่ต่อมา สัญญาเช่าที่ดินระหว่างนายจิตและนายแจ่มสิ้ นสุ ดลง นายจิตผูเ้ ช่าได้ร้ื อถอนบ้านออกไปและ\nไปเช่าที่ดินในเมืองปลูกบ้านอยู่ โดยไม่ปรากฏว่านายแจ่มได้ใช้ทางผ่านที่ดินของนายใจต่อจากนายจิตแต่\nอย่างใด กรณี เช่นนี้ ถือว่านายจิตสละเจตนาครอบครองเพื่อให้ได้ซ่ ึ งสิ ทธิ ภาระจายอมในทางผ่านที่ดินของ\nนายใจตามมาตรา 1377 วรรคแรกแล้ว การครอบครองโดยปรปั ก ษ์เ พื่ อ ให้ ไ ด้ภ าระจ ายอมที่ มี ก่ อ น\nตลอด 6 ปี ที่ผ่านมาจึงสิ้ นสุ ดลง ดังนั้น อายุความครอบครองปรปักษ์เพื่อให้ได้ภาระจายอมของนายจิตจึง\nสิ้ นสุ ดลงด้วย\nและแม้ต่อมาจะได้ความว่าในขณะที่สัญญาเช่าที่ดินระงับไปแล้ว นายจิตจะยังใช้ทางเดินผ่านที่ดินของนาย\nใจเข้าออกในหมู่บา้ นอยู่ก็ตาม แต่การเข้าออกดังกล่าวเป็ นการเข้าไปเพื่อค้าขายอันเป็ นไปเพื่อประโยชน์\nส่ ว นตัว ของนายจิ ต โดยเฉพาะ มิ ใ ช่ เ พื่ อ ประโยชน์ ข องอสั ง หาริ ม ทรั พ ย์ การใช้ท างผ่า นในช่ ว งหลัง\nตลอดเวลา 5 ปี จึงนับอายุความครอบครองปรปั กษ์ตามมาตรา 1401 ประกอบมาตรา 1382 เพื่อให้ได้\nภาระจายอมไม่ได้ เพราะไม่เข้าลักษณะและสาระสาคัญของภาระจายอมตามมาตรา 1387 ดังนั้น ภาระจา\nยอมจึงไม่อาจเกิดมีข้ นึ ได้ (ฎ. 11 – 13/2503)\nประเด็ น ที่ ต้อ งวิ นิ จ ฉัย มี ว่า นายจิ ต จะท าถนนและเทคอนกรี ต บนทางเข้า ออกบนที่ ดิ น ของนายใจได้\nหรื อไม่ เห็นว่า การที่นายจิตจ้างผูร้ ับเหมาทาถนนและตั้งใจจะเทคอนกรี ต แม้จะเป็ นการกระทาเพื่อรักษา\nและใช้ทางผ่านที่ดินของนายใจ และไม่เป็ นการกระทาที่เป็ นการเพิ่มภารยทรัพย์ก็ตาม (ฎ.1730/2503) นาย\nจิตก็ไม่สามารถทาได้ กรณี ไม่ตอ้ งด้วยมาตรา 1391 วรรคแรก เพราะกรณี น้ ี ภาระจายอมไม่เกิดขึ้น นายใจ\nจึงมีอานาจห้ามไม่ให้นายจิตเข้ามาในที่ดินของตน และให้ผรู ้ ับเหมารื้ อย้ายข้าวของที่จะทาถนนออกไปและ\nทาที่ดินให้ดีเหมือนเดิมได้","conclusion":"สรุป นายจิตทาถนนและเทคอนกรี ตบนทางเข้าออกบนที่ดินของนายใจไม่ได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2551-2-4-74","year":"2551","semester":"ภาค 2","number":4,"page":74,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาค 2 · ข้อ 4","sections":["1368","1382"],"otherSections":["1384"],"question":"ข้ อ 4 ทองครอบครองปรปั ก ษ์ที่ ดินมี โฉนดแปลงหนึ่ ง ของนายนาค ท าสวนลิ้ นจี่ ม าได้แปดปี ถูก ศาล\nพิพากษาจาคุกเป็ นเวลาเก้าเดือน เงินซึ่ งเป็ นเพื่อบ้านทราบจึงได้ขอเช่าสวนลื้นจี่เพื่อให้นกั ท่องเที่ยวมาเที่ยว\nชมสวนเกษตรและเก็บลิ้นจี่ขายนักท่องเที่ยวด้วย เมื่อถูกจาคุกไปได้แปดเดือนขณะอยู่ในเรื อนจา ทองป่ วย\nต้องเข้าโรงพยาบาล เมื่อพ้นโทษทองจึงได้มารักษาพยาบาลต่ออยูใ่ นโรงพยาบาลที่กรุ งเทพ อีกห้าเดือนเป็ น\nเวลารวมหนึ่ งปี กับสองเดือน เมื่อรักษาตัวหายดีแล้วทองจึงได้หางานทาที่กรุ งเทพ แต่ที่ดินแปลงนี้ ทอง\nยังคงให้เงินเช่าต่อ ทองทางานอยู่ที่กรุ งเทพมาได้สองปี เงินและทองถูกนาคฟ้ องขับไล่เรี ยกที่ดินแปลงนี้\nคืน\nให้ท่านอธิบายว่าทองได้กรรมสิ ทธิ์ในที่ดินแปลงนี้ แล้วหรื อยัง นาคฟ้องคดีต่อศาลเรี ยกที่ดินแปลง\nนี้คืนจากทองได้หรื อไม่ เพราะเหตุใด","rule":"มาตรา 1368 บุคคลอาจได้มาซึ่งสิ ทธิครอบครองโดยผูอ้ ื่นยึดถือไว้ให้\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1384 “ถ้าผูค้ รอบครองขาดยึดถือทรัพย์สินโดยไม่สมัคร และได้คืนภายในเวลาปี หนึ่ งนับตั้งแต่วนั\nขาดยึดถือ หรื อได้คืนโดยฟ้องคดีภายในกาหนดนั้นไซร้ ท่านมิให้ถือว่าการครอบครองสะดุดหยุดลง”","application":"โดยหลักแล้ว การได้กรรมสิ ทธิ์ ในอสังหาริ มทรัพย์โดยการครอบครองปรปั กษ์ตามมาตรา 1382 จะต้อง\nประกอบด้วยหลักเกณฑ์ดงั นี้ คือ\n1 เป็ นทรัพย์สินของผูอ้ ื่นโดยผูอ้ ื่นมีกรรมสิ ทธิ์\n2 ได้ครอบครองโดยความสงบ\n3 ครอบครองโดยเปิ ดเผย\n4 ครอบครองโดยเจตนาเป็ นเจ้าของ\n5 ครอบครองติดต่อกันมาเป็ นเวลา 10 ปี\nสาหรับการครอบครองติดต่อกันนั้น จะต้องเป็ นกรณี ที่ผคู ้ รอบครอง ไม่มีเจตนาสละการครอบครอง หรื อ\nขาดการยึดถือโดยสมัครใจ และนับระยะเวลาครอบครองติดต่อกันได้ หากเป็ นเพียงการขาดการยึดถือโดย\nไม่สมัคร เพราะมีเหตุมาขัดขวางโดยไม่สมัครใจ กฎหมายถื อว่าการขาดการยึดถือนั้นไม่ทาให้ขาดอายุ\nความ การครอบครองสะดุดหยุดลง หากได้ทรัพย์สินคืนภายใน 1 ปี นับแต่วนั ที่ขาดการยึดถือ ทั้งนี้ ตาม\nมาตรา 1384\nกรณีตามอุทาหรณ์ การที่ทองครอบครองปรปักษ์ที่ดินมีโฉนดแปลงหนึ่งของนายนาค มา 8 ปี โดยทาเป็ น\nสวนลิ้นจี่ ต่อมานายทอง ได้ถูกศาลพิพากษาจาคุกเป็ นเวลา 9 เดือน เงินซึ่งเป็ นเพื่อบ้านจึงได้ขอเช่าสวน\nลิ้นจี่จากทองเพื่อให้นกั ท่องเที่ยวมาเที่ยวชมสวนเกษตร และเก็บลิ้นจี่ขายนักท่องเที่ยวด้วย กรณี เช่นนี้ ถือ\nว่า ทองได้ขาดการยึดถือโดยไม่สมัครใจตามมาตรา 1384 โดยมีเงินผูเ้ ช่าเป็ นผูย้ ึดถือการครอบครองแทน\nตามมาตรา 1368 และเป็ นผูเ้ อาคืนซึ่งการครอบครองให้ภายใน 1 ปี นับตั้งแต่ขาดการยึดถือโดยไม่สมัคร\nใจ อายุความการครอบครองจึงไม่สะดุดหยุดลง\nเมื่อได้ความว่า ทองถูกจาคุกไปได้ 8 เดือน ขณะอยู่ในเรื อนจาทองป่ วยต้องเข้าโรงพยาบาล เมื่อพ้นโทษ\nท อ ง จึ ง ไ ด้ ม า รั ก ษ า พย า บา ล ต่ อ อ ยู่ ใ น โ ร ง พ ย าบ า ล ที่ กรุ ง เ ท พฯ อี ก 5 เ ดื อ น ซึ่ ง เ ป็ น เ ว ล า\nรวม 1 ปี 2 เดือน เมื่อรักษาตัวหายดีแล้ว ทองจึงได้หางานทาที่กรุ งเทพฯ และทองได้ทางานอยู่\nที่ ก รุ ง เทพฯอี ก 2 ปี ในกรณี ดั ง กล่ า วนี้ ระหว่ า งที่ ท องถู ก จ าคุ ก และในระหว่ า งป่ วยและท างานที่\nกรุ ง เทพฯ จะถื อ ว่า ทองขาดการยึด ถื อ ไม่ ไ ด้ เพราะที่ ดิ น แปลงนี้ ก็ มี เ งิ น ครอบครองปรปั ก ษ์แ ทนทอง\nตลอดเวลาตามมาตรา 1368 ประกอบมาตรา 1384 ดังที่กล่าวไปข้างต้น เมื่อรวมระยะเวลาทั้งหมดติดต่อกัน\nแล้วเป็ นเวลาเกิน 10 ปี ดังนั้น ทองจึงได้กรรมสิ ทธิ์ ในที่ดินแปลงนี้ แล้ว โดยการครอบครองปรปักษ์ตาม\nมาตรา 1382","conclusion":"สรุป ทองได้กรรมสิ ทธิ์ในที่ดินแปลงนี้แล้ว นาคจึงฟ้องศาลเรี ยกที่ดินแปลงนี้จากทองไม่ได้\nการสอบไล่ภาค 1 ปี การศึกษา 2551\nข้อสอบกระบวนวิชา LAW2001 (LA 201),(LW 204)\nกฎหมายแพ่งและพาณิชย์ว่าด้วยทรัพย์\nคาแนะนา ข้อสอบเป็ นอัตนัยล้วนมี 4 ข้อ","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2551-1-1-76","year":"2551","semester":"ภาค 1","number":1,"page":76,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาค 1 · ข้อ 1","sections":["1299"],"otherSections":[],"question":"ข้ อ 1 เด่นเป็ นเจ้าของที่ดินมีโฉนดจานวน 2 ไร่ โดยเด่นยกที่ดินด้านทิศเหนื อจานวน 1 ไร่ ให้แก่ดวง\nโดยไม่ได้จดทะเบียนแบ่งโฉนดให้ ภายหลังจากดวงเข้าครอบครองเป็ นเจ้าของที่ดินด้านทิศเหนือติดต่อกัน\nเป็ นเวลากว่า 10 ปี แล้ว เด่นก็ยกที่ดินส่วนที่เหลือจานวน 1 ไร่ ซึ่งอยูด่ า้ นทิศใต้ให้แก่เปลว\nแต่ทาสัญญาจดทะเบียนให้เปลวมีชื่อเป็ นเจ้าของโฉนดทั้งแปลง เพราะเปลวรับรองว่าจะจดทะเบียนแบ่ง\nโอนให้ดวงในภายหลัง แต่เปลวไม่ดาเนิ นการจดทะเบียนแบ่งโอนให้ดวงตามที่รับรองไว้กบั เด่น แต่กลับ\nนาที่ดินดังกล่าวไปทาสัญญาและจดทะเบียนขายให้กบั เพลิง ซึ่ งเพลิงรู ้ขอ้ เท็จจริ งต่างๆ และรู ้ดว้ ยว่าดวง\nกาลังจะยืน่ ฟ้องคดีให้เปลวแบ่งโฉนดให้ดวง แต่เพลิงก็ยงั รับซื้อที่ดินนั้นทั้งหมด\nดังนี้ให้ท่านวินิจฉัยว่า ระหว่าง ดวง เปลว และเพลิง ผูใ้ ดมีกรรมสิ ทธิ์ในที่ดินจานวน 1 ไร่ ด้าน\nทิศเหนือซึ่งเป็ นที่พิพาทดีกว่ากัน เพราะเหตุใด","rule":"มาตรา 1299 ภายในบังคับแห่ งบทบัญญัติในประมวลกฎหมายนี้ หรื อกฎหมายอื่ น ท่านว่า การ\nได้มาโดยนิ ติกรรมซึ่งอสังหาริ มทรัพย์หรื อทรัพยสิ ทธิ อนั เกี่ยวกับอสังหาริ มทรัพย์น้ นั ไม่บริ บูรณ์ เว้นแต่นิติ\nกรรมจะได้ทาเป็ นหนังสื อและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่\nถ้า มี ผูไ้ ด้ม าซึ่ ง อสั ง หาริ ม ทรั พ ย์ หรื อ ทรั พ ยสิ ท ธิ อัน เกี่ ย วกับ อสั ง หาริ ม ทรั พ ย์โ ดยทางอื่ น นอกจากนิ ติ\nกรรม สิ ทธิ ของผูไ้ ด้มานั้น ถ้ายังมิได้จดทะเบียนไซร้ ท่านว่าจะมีการเปลี่ยนแปลงทางทะเบียนไม่ได้ และ\nสิ ทธิ อนั ยังมิได้จดทะเบียนนั้น มิให้ยกเป็ นข้อต่อสู้บุคคลภายนอกผูไ้ ด้สิทธิมาโดยเสี ยค่าตอบแทนและโดย\nสุจริ ตและได้จดทะเบียนสิ ทธิโดยสุจริ ตแล้ว","application":"เด่นยกที่ดินด้านทิศเหนือจานวน 1 ไร่ ให้ดวง แต่ยงั ไม่ได้จดทะเบียนแบ่งแยกโฉนดที่ดินให้ ดวงจึงเป็ นผู ้\nได้ม าซึ่ ง อสัง หาริ ม ทรั พ ย์โดยทางนิ ติก รรมตามมาตรา 1299 วรรคแรก แต่นิติก รรมดัง กล่า วไม่ ไ ด้จ ด\nทะเบียนกับพนักงานเจ้าหน้าที่จึงเป็ นโมฆะ แต่การที่ดวงเข้าครอบครองเป็ นเจ้าของที่ดินนั้นติดต่อกันเป็ น\nเวลากว่า 10 ปี แล้ว ดวงจึ ง เป็ นผูไ้ ด้ก รรมสิ ท ธิ์ โดยการครอบครองปรปั ก ษ์ อันเป็ นการได้ม าโดยทาง\nอื่น นอกจากนิติกรรมตามมาตรา 1299 วรรคสอง แต่ดวงยังไม่ได้จดทะเบียนเปลี่ยนชื่อในโฉนดเป็ นของ\nตน ดวงจึงไม่สามารถเปลี่ยนแปลงใดๆในทางทะเบียน และไม่สามารถยกเป็ นข้อต่อสู้บุคคลภายนอกผูไ้ ด้\nสิ ทธิ ในอสั ง หาริ มทรั พ ย์ น้ ั นโดยมี ค่ า ตอบแทน โดยสุ จริ ต และจดทะเบี ย นสิ ทธิ โดยสุ จริ ต\nแล้ว (ฎ. 884/2523)\nต่อมาเด่นยกที่ดินส่ วนที่เหลือด้านทิศใต้จานวน 1 ไร่ ให้เปลว โดยทาสัญญาและจดทะเบียนให้เปลวมีชื่อ\nในโฉนดทั้งแปลง เพราะเปลวรับรองว่าจะจดทะเบียนแบ่งโอนให้ดวงภายหลัง แต่เปลวไม่ดาเนิ นการจด\nทะเบียนแบ่งโอนให้ดวงตามที่รับรองไว้กบั เด่น แต่เปลวกลับทาสัญญาและจดทะเบียนขายที่ดินแปลงทิศ\nเหนื อให้เพลิง โดยเพลิงรู ้ขอ้ เท็จจริ งต่างๆ แม้เพลิงจะเป็ นบุคคลภายนอกที่ได้กรรมสิ ทธ์ในที่ดินดังกล่าว\nโดยมีค่าตอบแทนก็จริ ง แต่การได้มานั้นไม่สุจริ ต และจดทะเบียนสิ ทธิโดยไม่สุจริ ต\nดัง นั้น ดวงจึ ง เป็ นผูม้ ี ก รรมสิ ท ธิ์ ในที่ ดิ น พิ พ าทดี ก ว่า เปลว เพราะเปลวได้ม าโดยไม่ มี ค่ า ตอบแทนไม่\nสุจริ ต และจดทะเบียนสิ ทธิโดยไม่สุจริ ต เพราะดวงมีกรรมสิ ทธิ์ดีกว่าเพลิงตามเหตุผลดังกล่าวข้างต้น","conclusion":"สรุป ดวงมีกรรมสิ ทธิ์ในที่ดินพิพาทดีกว่าเปลวและเพลิง","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2551-1-3-77","year":"2551","semester":"ภาค 1","number":3,"page":77,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาค 1 · ข้อ 3","sections":["1382","1387","1401"],"otherSections":["1400"],"question":"ข้อ 3 หนึ่งเป็ นเจ้าของที่ดินแปลงหนึ่งซึ่งให้สองเช่าที่ดินปลูกบ้าน สองได้ใช้ทางเดินผ่านที่ดินของสามเพื่อ\nออกไปสู่ ถนนสาธารณะ เพราะที่ดินของหนึ่งไม่มีทางเข้าออก โดยสองไม่ได้ขออนุญาตจากสามเลย สอง\nเช่าที่ดินหนึ่งและใช้ทางผ่านเข้าออกบนที่ดินของสามมาได้สิบห้าปี ทางราชการได้ตดั ถนนระหว่างจังหวัด\nผ่านที่ดินแปลงนั้น พอดีกบั ที่สองได้เลิกสัญญาเช่าที่ดินแปลงนั้นจึงถูกปล่อยทิ้งร้างมาได้สองปี หนึ่งได้เข้า\nมาปลูกบ้านอยูบ่ นที่ดินแปลงนั้น หนึ่งจึงต้องการที่จะใช้ทางผ่านบนที่ดินของสามเข้าออก\nโดยหนึ่ งอ้างว่าที่ดินของสามตกเป็ นภาระจายอมให้ที่ดินของตนผ่านเข้าออกแล้ว แต่สามอ้างว่าหนึ่งหมด\nสิ ทธิที่จะใช้ทางผ่านเข้าออกบนที่ดินของตนแล้ว\nให้ท่านอธิบายว่าข้ออ้างระหว่างหนึ่งและสามใครจะรับฟังได้ดีกว่ากัน เพราะเหตุใด","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1387 อสังหาริ มทรัพย์อาจต้องตกอยูใ่ นภาระจายอมอันเป็ นเหตุให้เจ้าของต้องยอมรับกรรม\nบางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรื อต้องงดเว้นการใช้สิทธิ บางอย่างอันมีอยู่ในกรรมสิ ทธิ์ นั้นเพื่อ\nประโยชน์แก่อสังหาริ มทรัพย์อื่น\nมาตรา 1400 วรรคแรก ถ้าภาระจายอมหมดประโยชน์แก่สามยทรัพย์ไซร้ ท่านว่าภาระจายอมนั้น\nสิ้ นไป แต่ถา้ ความเป็ นไปมีทางให้กลับใช้ภาระจายอมได้ไซร้ ท่านว่าภาระจายอมนั้นกลับมีข้ ึนอีก แต่ตอ้ ง\nยังไม่พน้ อายุความที่ระบุไว้ในมาตราก่อน\nมาตรา 1401 ภาระจายอมอาจได้มาโดยอายุความ ท่านให้นาบทบัญญัติว่าด้วยอายุความได้สิทธิกล่าวไว้ใน\nลักษณะ 3 แห่งบรรพนี้มาใช้บงั คับโดยอนุโลม","application":"หนึ่งเป็ นเจ้าของที่ดินแปลงหนึ่งซึ่งให้สองเช่าที่ดินปลูกบ้าน สองได้ใช้ทางเดินผ่านที่ดินของสามเพื่อออก\nไปสู่ ถนนสาธารณะเพราะที่ดินของหนึ่ งไม่มีทางเข้าออก โดยสองไม่ได้ของอนุ ญาตจากสามเลยสองเช่า\nที่ดินหนึ่ งและใช้ทางผ่านเข้าออกบนที่ดินของสามมาได้สิบห้าปี ที่ดินของหนึ่ งได้ภาระจายอมในการใช้\nทางเดินผ่านที่ดินของสามเพราะภาระจายอมมีข้ ึนเพื่อประโยชน์อสังหาริ มทรัพย์ตามมาตรา 1387 ดังนั้นใคร\nก็ตามที่ อยู่บนที่ ดินก็จะก่อให้เกิดภาระจายอมโดยการครอบครองปรปั กษ์ได้ตามมาตรา 1401 ประกอบ\nมาตรา 1382 ทางราชการได้ตดั ถนนระหว่างจังหวัดผ่านที่ดินแปลงนั้น ภาระจายอมในการใช้ทางก็หมด\nประโยชน์แก่สามยทรัพย์ภาระจายอมนั้นสิ้ นไป เป็ นการสิ้ นไปโดยผลของกฎหมายมาตรา 1400 วรรค\nแรก และเมื่อเป็ นถนนของทางราชการจึ งใช้ไ ด้ตลอดไป เมื่อหนึ่ งได้เข้ามาปลูกบ้านอยู่บ นที่ ดินแปลง\nนั้น หนึ่งจะใช้ทางผ่านบนที่ดินของสามไม่ได้ เพราะภาระจายอมสิ้ นไปโดยผลของกฎหมายแล้ว ข้อที่สาม\nอ้างว่าหนึ่งหมดสิ ทธิที่จะใช้ทางผ่านเข้าออกบนที่ดินของตนจึงรับฟังได้ดีกว่าของหนึ่ง","conclusion":"สรุป ข้ออ้างของสามรับฟังได้ดีกว่า","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2551-1-4-79","year":"2551","semester":"ภาค 1","number":4,"page":79,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2551 ภาค 1 · ข้อ 4","sections":["1367","1382","1387","1401"],"otherSections":[],"question":"ข้ อ 4 ที่ดินมือเปล่าแปลงหนึ่ งของโอ่งมีที่ดินมือเปล่าของอ่างอยู่ติดทางขวามือ และมีที่ดินมือเปล่า ของ\nเอียดติดอยู่ทางด้านหลัง อ่างได้เข้าไปขุดหน่อไม้ในที่ดินของโอ่งมาขายเป็ นประจาเป็ นเวลาเกินกว่าสิ บปี\nแล้ว ส่ วนเอียดก็ใช้ที่ดินของโอ่งเป็ นทางผ่านเข้าออกที่ดินของตนตลอดมาอยู่เกินกว่าสิ บปี เช่นกัน ทั้งเอียด\nและอ่างได้ใช้ที่ดินของโอ่งโดยโอ่งไม่รู้ ต่อมาโอ่งได้ห้ามไม่ให้เอียดและอ่างเข้าไปในที่ดินแปลงนั้นของ\nตน\nตามประมวลกฎหมายแพ่งและพาณิชย์ลกั ษณะทรัพย์ อ่างและเอียดมีสิทธิในที่ดินของโอ่งแปลงนั้น\nอย่างไรบ้าง เพราะเหตุใด","rule":"มาตรา 1367 บุคคลใดยึดถือทรัพย์สินโดยเจตนาจะยึดถื อเพื่ อตน ท่านว่าบุคคลนั้นได้ซ่ ึ ง สิ ท ธิ\nครอบครอง\nมาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้าของ ถ้าเป็ นอสังหาริ มทรัพย์ได้ครอบคอรงติดต่อกันเป็ นเวลาสิ บปี ถ้าเป็ นสังหาริ มทรัพย์ได้ครอบคอ\nรงติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1387 อสังหาริ มทรัพย์อาจต้องตกอยูใ่ นภาระจายอมอันเป็ นเหตุให้เจ้าของต้องยอมรับกรรม\nบางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรื อต้องงดเว้นการใช้สิทธิ บางอย่างอันมีอยู่ในกรรมสิ ทธิ์ นั้นเพื่อ\nประโยชน์แก่อสังหาริ มทรัพย์อื่น\nมาตรา 1401 ภาระจายอมอาจได้มาโดยอายุความ ท่านให้นาบทบัญญัติวา่ ด้วยอายุความได้สิทธิ อนั\nกล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บงั คับโดยอนุโลม","application":"ที่ดินมือเปล่าแปลงหนึ่งของโอ่งมีที่ดินมือเปล่าของอ่างอยู่ติดทางขวามือ และมีที่ดินมือเปล่าของเอียดติดอยู่\nทางด้านหลัง อ่างได้เข้าไปขุดหน่อไม้ในที่ดินของโอ่งมาขาย การเข้าไปขุดหน่อไม้มาขายไม่ก่อให้เกิดสิ ทธิ\nครอบครองบนที่ดินของโอ่งเพราะการเข้าไปเก็บหน่อไม้ยงั ไม่ได้เกี่ยวข้องใช้ประโยชน์ในทรัพย์ถึงขนาด\nเท่ากับผูท้ รงสิ ทธิ ครอบครองในที่ดินมือเปล่าที่ยึดถือใช้ที่ดินทาประโยชน์กับทรัพย์ จึงยังไม่เป็ นยึดถื อ\nทรั พ ย์สิ น โดยเจตนายึ ด ถื อ เพื่ อ ตน ตามมาตรา 1367 และไม่ ไ ด้ภ าระจ ายอมในที่ ดิ น ของโอ่ ง ตาม\nมาตรา 1387 ส่ วนเอียดก็ใช้ที่ดินของโอ่งเป็ นทางผ่านเข้าออกที่ดินของตนตลอดมาเกินกว่าสิ บปี โดยโอ่ง\nไม่รู้ ที่ดินของเอียดจึงได้ภาระจายอมโดยการครอบครองปรปั กษ์ที่ผ่านเข้าออกบนที่ดินของโอ่งแล้วตาม\nมาตรา 1401 ประกอบมาตรา 1382","conclusion":"สรุป 1 อ่างไม่มีสิทธิในที่ดินของโอ่ง\n2 เอียดได้ภาระจายอมโดยการครอบครองปรปักษ์ที่ผา่ นเข้าออกที่ดินของโอ่ง\nการสอบไล่ ภาคฤดูร้อน ปี การศึกษา 2550\nข้อสอบกระบวนวิชา LAW2001 (LA 201),(LW 204)\nกฎหมายแพ่งและพาณิชย์ว่าด้วยทรัพย์\nคาแนะนา ข้อสอบเป็ นอัตนัยล้วนมี 4 ข้อ","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2550-s-1-80","year":"2550","semester":"ภาคฤดูร้อน","number":1,"page":80,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2550 ภาคฤดูร้อน · ข้อ 1","sections":["1304","1382","1367"],"otherSections":["1306"],"question":"ข้ อ 1 นายท้วมและนายอ่าเป็ นเจ้าของที่ดินอยู่ติดต่อกัน และด้านทิศเหนื อของที่ดินทั้งสองแปลงต่างก็ติด\nกับแม่น้ าปิ ง เวลาฤดูน้ า น้ าท่วมเต็มตลิ่งทุกปี เวลาฤดูแล้งน้ าลดลงไป ทั้งนายท้วมและนายอ่าต่างก็เข้าไป\nปลุกผักในที่ดินริ มตลิ่งที่น้ าลดลงตรงหน้าที่ดินของตน ต่อมานายท้วมสุ ขภาพไม่ดีจึงเลิกปลูกผักและไม่ได้\nเข้าไปใช้ประโยชน์ในที่ดินริ มตลิ่งนั้นอีกเลย นายอ่าเห็นนายท้วมไม่ได้เข้าไปครอบครองทาประโยชน์ใน\nที่ดินดังกล่าวเป็ นเวลากว่า 1 ปี แล้ว\nนายอ่าจึงขยายพื้นที่ปลูกผักเข้าไปในที่ดินริ มตลิ่งหน้าที่ดินของนายท้วม โดยนายท้วมไม่ทกั ท้วง หลังจาก\nนั้น 3 ปี นายท้วมถึงแก่ความตาย นายเท่งบุตรของนายท้วมจดทะเบียนรับมรดกที่ดินของนายท้วม และ\nไม่ยอมให้นายอ่าปลูกผักในที่ดินริ มตลิ่งหน้าที่ดินที่ตนรับมรดก และต้องการจะเข้าไปปลูกผักเอง นายอ่า\nไ ม่ ย อ ม อ้ า ง ว่ า ไ ด้ ค ร อ บ ค ร อ ง ที่ ดิ น พิ พ า ท ซึ่ ง เ ป็ น ที่ ดิ น มื อ เ ป ล่ า ม า เ กิ น 1 ปี แ ล้ ว\nนายเท่ ง จึ ง ไม่ มี สิ ท ธิ ฟ้ อ งเอาคื น ซึ่ ง การครอบครอง เช่ น นี้ นายอ่ า จะได้ก รรมสิ ท ธิ์ หรื อ สิ ท ธิ\nครอบครองในที่ ดิ น พิ พ าทนั้ นอย่ า งไร หรื อไม่ และนายเท่ ง จะให้ น ายอ่ า ออกไปจากที่ พิ พ าทได้\nหรื อไม่ เพราะเหตุใด","rule":"มาตรา 1304 สาธารณะสมบัติข องแผ่นดิ นนั้น รวมทรั พ ย์สิ นทุ ก ชนิ ดของแผ่นดิ น ซึ่ ง ใช้เพื่ อ\nสาธารณะประโยชน์ หรื อสงวนไว้เพื่อประโยชน์ร่วมกัน เช่น\n(2) ทรัพย์สินสาหรับพลเมืองใช้ร่วมกัน เป็ นต้นว่าที่ชายตลิ่ง ทางน้ า ทางหลวง ทะเลสาบ\nมาตรา 1306 ท่านห้ามมิ ให้ยกอายุความขึ้นเป็ นข้อต่อสู ้กับแผ่นดิ นในเรื่ องทรั พย์สินอันเป็ นสา\nธารณสมบัติของแผ่นดิน","application":"ที่พิพาทเป็ นที่ดินริ มตลิ่งหน้าที่ดินของนายท้วมและนายอ่า ซึ่ งเวลาฤดูน้ า น้ าท่วมถึงเต็มตลิ่งทุกปี เวลาฤดู\nแล้งน้ าลดลงไป ที่ดินริ มตลิ่งทั้งสองแปลงดังกล่าว ย่อมถือได้ว่าเป็ นที่ชายตลิ่ง อันเป็ นสาธารณสมบัติของ\nแผ่นดินประเภททรัพย์สินสาหรับพลเมืองใช้ร่วมกัน ตามมาตรา 1304 (2) ผูใ้ ดหามีกรรมสิ ทธิ์ หรื อสิ ทธิ\nครอบครองไม่ ดังนั้นทั้งนายท้วมและนายอ่าจึงไม่มีกรรมสิ ทธิ์ หรื อสิ ทธิ์ ครอบครองในที่ดินพิพาทแต่อย่าง\nใด (ฎ. 2199/2515)\nนอกจากนี้ แม้นายท้วมและนายอ่าจะเข้าไปปลูกผักในที่ชายตลิ่งหน้าที่ดินของตนนานเท่าใด ก็ไม่\nสามารถยกอายุความการครอบครองปรปั กษ์ (มาตรา 1382) หรื อแม้แต่ในเรื่ องสิ ทธิ ครอบครอง (มาตรา\n1367) ขึ้นเป็ นข้อต่อสู ้กบั แผ่นดินได้ ตามมาตรา 1306\nแม้ ก ารยึ ด ถื อ ครอบครองสาธารณสมบั ติ ข องแผ่ น ดิ น จะไม่ ก่ อ ให้ เ กิ ด สิ ทธิ ใดๆ แก่ ผู ้ ยึ ด ถื อ\nครอบครอง หมายถึงใช้ยนั ต่อรัฐหรื อแผ่นดินไม่ได้ แต่ในระหว่างเอกชนด้วยกันนั้นใช้ยนั กันเองได้ โดยถือ\nหลักว่าผูท้ ี่เป็ นฝ่ ายครอบครองที่สาธารณสมบัติของแผ่นดิ นอยู่ก่อนและยังคงครอบครองอยู่ ผูน้ ้ นั ย่อมมี\nสิ ท ธิ ดี ก ว่ า (ฎ. 3908/2535) ซึ่ งสิ ท ธิ ดัง กล่ า วจะมี อ ยู่ ต ลอดเวลาที่ ค รอบครองเท่ า นั้ น ดัง นั้ น หากผู ้ที่\nครอบครองอยู่ก่อนแล้วสละการครอบคอรงที่พิพาทนั้นไป ผูค้ รอบครองรายหลังซึ่ งยังคงครอบครองทา\nประโยชน์อยูย่ อ่ มมีสิทธิดีกว่า\nกรณีตามอุทาหรณ์ นายท้วมไม่ได้เข้าไปครอบครองทาประโยชน์ในที่ดินดังกล่าวเป็ นเวลา 1 ปี แล้ว และ\nการที่นายอ่าขยายพื้นที่ปลูกผักเข้าไปในที่ดินริ มตลิ่งหน้าที่ดินของนายท้วม นายท้วมก็ไม่ได้ทกั ท้วงแต่อย่าง\nใด เช่นนี้ ถือว่า นายท้วมสละการครอบคอรงแล้ว เมื่อนายอ่าเข้าไปครอบครองทาประโยชน์ต่อ นายอ่าจึง\nเป็ นผูม้ ีสิทธิ ในที่พิพาทดีกว่านายท้วมและนายเท่ง ดังนั้นนายเท่งจึงไม่สามารถให้นายอ่าออกไปจากที่ดิน\nพิพาทได้ (ฎ. 279/2530)","conclusion":"สรุ ป นายอ่าไม่มีกรรมสิ ทธิ์หรื อสิ ทธิครอบครองในที่ดินพิพาทแต่อย่างใด และนายเท่งจะให้นาย\nอ่าซึ่งเป็ นผูม้ ีสิทธิดีกว่าตนออกไปจากที่ดินพิพาทไม่ได้เช่นกัน","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2550-s-4-83","year":"2550","semester":"ภาคฤดูร้อน","number":4,"page":83,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2550 ภาคฤดูร้อน · ข้อ 4","sections":["1382","1387","1401"],"otherSections":[],"question":"ข้ อ 4 นายสาลีมีอาชี พทาไร่ และเลี้ยงปลาขาย ที่ดินของสาลีที่ใช้ท้ งั อาศัยปลูกบ้านและทาไร่ เลี้ยงปลาอยู่\nตรงข้ามกับที่ดินของนายสายมีทางเดินเท้าสาธารณะคัน่ อยู่ ที่ดินของนายสายมีสระน้ าอยู่ในที่ดินนั้น นาย\nสาลีทาท่อฝังใต้ถนนสาธารณะสู บน้ าข้ามถนนเข้ามาในที่ดินของนายสาลีโดยไม่ได้ขออนุ ญาตนายสายแต่\nอย่างใด เพื่อใช้ทาไร่ เลี้ยงปลาประจามาได้แปดปี ต่อมานายสาลีได้ยกท่อน้ าขึ้นมาวางไว้บนถนน ทาให้\nชาวบ้านซึ่ งใช้ถนนเส้นนั้นเข้าออกไม่สะดวก ชาวบ้านจึงได้บอกกับกานันให้มาบอกให้นายสาลีร้ื อท่อน้ า\nนั้นออกไปจากถนน แต่นายสาลีไม่ยอมรื้ อ หลังจากนั้นมาได้สองปี ครึ่ งนายสายทราบจึงห้ามไม่ให้นายสาลี\nสู บน้ าจากที่ดินของตนและให้ร้ื อท่อน้ านั้นออกไป แต่นายสาลีไม่ยอม\nตามประมวลกฎหมายแพ่งและพาณิ ชย์ นายสาลีจะได้ภาระจายอมโดยการครอบครองปรปั กษ์ใน\nการใช้น้ าในบ่อนั้นหรื อไม่ เพราะเหตุใด","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้าของ ถ้าเป็ นอสังหาริ มทรัพย์ได้ครอบคอรงติดต่อกันเป็ นเวลาสิ บปี ถ้าเป็ นสังหาริ มทรัพย์ได้ครอบคอ\nรงติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1387 อสังหาริ มทรัพย์อาจต้องตกอยูใ่ นภาระจายอมอันเป็ นเหตุให้เจ้าของต้องยอมรับกรรม\nบางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรื อต้องงดเว้นการใช้สิทธิ บางอย่างอันมีอยู่ในกรรมสิ ทธิ์ นั้นเพื่อ\nประโยชน์แก่อสังหาริ มทรัพย์อื่น\nมาตรา 1401 ภาระจายอมอาจได้มาโดยอายุความ ท่านให้นาบทบัญญัติวา่ ด้วยอายุความได้สิทธิ อนั\nกล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บงั คับโดยอนุโลม","application":"นายสาลีมีอาชีพทาไร่ และเลี้ยงปลาขาย ที่ดินของสาลีที่ใช้ท้ งั อาศัยปลูกบ้านและทาไร่ เลี้ยงปลาอยู่ตรงข้าม\nกับที่ดินของนายสายมีทางเดินเท้าสาธารณะขั้นอยู่ ที่ดินของนายสายมีสระน้ าอยู่ในที่ดินนั้นนายสาลีทาท่อ\nฝังใต้ถนนสาธารณะสู บน้ าเข้ามาในที่ดินของนายสาลีโดยไม่ได้ขออนุญาตจากนายสายแต่อย่างใด เพื่อใช้ทา\nไร่ เลี้ยงปลาเป็ นการใช้เพื่อประโยชน์อสังหาริ มทรัพย์ทาให้ที่ดินของนายสาลีเข้าลักษณะภาระจายอมโดย\nการครอบครองปรปั ก ษ์แ ล้ว เมื่ อใช้ม าได้ป ระจาแปดปี นายส าลี ไ ด้ย กท่ อ น้ า นั้น ขึ้ น มาบนถนน ท าให้\nชาวบ้านซึ่งใช้ถนนเส้นนั้นเข้าออกไม่สะดวก ชาวบ้านจึงได้บอกกับกานันให้มาบอกให้นายสาลีร้ื อถอนท่อ\nน้ านั้นออกไปจากถนน แต่นายสาลีก็ยงั ไม่ยอมรื้ อออก หลังจากนั้นมาได้สองปี ครึ่ งนายสายทราบจึงห้าม\nไม่ให้นายสาลีสูบน้ าจากที่ดินของตนและรื้ อท่อน้ านั้นออกไป แต่นายสาลีไม่ยอม ดังนี้ นายสาลีได้ภาระจา\nย อมโดย ก ารครอบครองปรปั ก ษ์ ใ นก ารใ ช้ น้ าใ นบ่ อ นั้ นอั น ได้ ม าโดย อายุ ค วามแล้ ว ตาม\nมาตรา 1387 ประกอบมาตรา 1382 และมาตรา 1401","conclusion":"สรุป นายสาลียอ่ มได้ภาระจายอมโดยการครอบครองปรปักษ์ในการใช้น้ าในบ่อน้ านั้นแล้ว\nการสอบไล่ภาค 2 ปี การศึกษา 2550\nข้อสอบกระบวนวิชา LAW2001 (LA 201),(LW 204)\nกฎหมายแพ่งและพาณิชย์ว่าด้วยทรัพย์\nคาแนะนา ข้อสอบเป็ นอัตนัยล้วนมี 4 ข้อ","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2550-2-1-85","year":"2550","semester":"ภาค 2","number":1,"page":85,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2550 ภาค 2 · ข้อ 1","sections":["146"],"otherSections":[],"question":"ข้อ 1 ปริ ญญาเช่าที่ดินของดุษฎีเพื่อก่อสร้างโครงเหล็กติดป้ายโฆษณาเป็ นเวลา 5 ปี โดยสัญญาเช่าระบุว่า\nทรัพย์สินใดๆที่ได้ปลูกสร้างและติดตั้งในสถานที่เช่านี้ อนั เกิดจากการเช่าเป็ นกรรมสิ ทธิ์ ของผูเ้ ช่า และเมื่อ\nครบก าหนดสั ญ ญาเช่ า ผู ้เ ช่ า มี สิ ท ธิ์ รื้ อถอนคื น ไปได้ ท้ ัง สิ้ น หลัง จากปริ ญญาติ ด ตั้ง โครงเหล็ ก ไป\nได้ 4 ปี พอขึ้นปี ที่ 5 ปริ ญญาขอบอกเลิกสัญญาเช่าและขอรื้ อเฉพาะโครงเหล็กออกไปจากที่ดินเช่า ดุษฎี\nไม่ขดั ข้องแต่แจ้งให้ปริ ญญาส่ งมอบที่ดินคืนให้ดุษฎีในสภาพเดิม คือต้องรื้ อถอนตอม่อและเสาเข็มที่ ฝังไว้\nใต้ดินออกไปด้วย\nปริ ญญาไม่ตอ้ งการรื้ อถอนตอม่อกับเสาเข็มเพราะเสี ยค่าใช้จ่ายมาก\nปริ ญญาจึงมาปรึ กษาท่านว่า จะรื้ อเฉพาะโครงเหล็กอย่างเดียวไม่ร้ื อถอนตอม่อและเสาเข็มออกไป\nได้หรื อไม่ และดุษฎีจะฟ้องบังคับให้ปริ ญญาต้องรื้ อตอม่อและเสาเข็มออกไปด้วยได้หรื อไม่ เพราะเหตุใด","rule":"มาตรา 146 ทรัพย์ซ่ ึ งติดกับที่ดินหรื อติดกับโรงเรื อนเพียงชัว่ คราวไม่ถือว่าเป็ นส่ วนควบกับที่ดิน\nหรื อโรงเรื อนนั้น ความข้อนี้ให้ใช้บงั คับแก่โรงเรื อนหรื อสิ่ งปลูกสร้างอย่างอื่น ซึ่งผูม้ ีสิทธิในที่ดินของผูอ้ ื่น\nใช้สิทธิน้ นั ปลูกสร้างไว้ในที่ดินนั้นด้วย","application":"ปริ ญญาเป็ นผูม้ ี สิทธิ ใ นที่ ดินของดุ ษ ฎี ตามสั ญญาเช่ าที่ ดินเพื่ อก่ อสร้ างโครงเหล็ก ติ ดตั้งป้ ายโฆษณาเป็ น\nเวลา 5 ปี และได้ใ ช้สิท ธิ น้ ันปลู กสร้ า งเสาเข็ม ตอม่ อ ซึ่ ง เป็ นส่ วนประกอบของโครงเหล็กในที่ ดินที่\nเช่า ดังนั้นภายในระยะเวลาตามสัญญาเช่า เสาเข็ม ตอม่อ และโครงเหล็กจึงไม่เป็ นส่ วนควบของที่ดินตาม\nมาตรา 146 หลังจากปริ ญญาติดตั้งโครงเหล็กได้ 4 ปี พอขึ้นปี ที่ 5 ปริ ญญาขอบอกเลิกสัญญาเช่า\nแล้ว จะรื้ อเฉพาะโครงเหล็กออกไปจากที่ดินที่เช่าเพียงอย่างเดียวไม่ได้ ดุษฎีสามารถฟ้องบังคับให้ปริ ญญา\nรื้ อทั้ง ตอม่ อและเสาเข็ม ออกไปและส่ ง มอบที่ ดิ นคื นให้ แก่ ต นในสภาพเดิ ม ได้ โดยปริ ญญาเป็ นผู ้อ อก\nค่าใช้จ่ายในการรื้ อถอนดังกล่าว","conclusion":"สรุ ป ปริ ญญาต้องรื้ อทั้ง โครงเหล็ก ตอม่ อ และเสาเข็ม ออกไป หากปริ ญญาไม่ ร้ื อตอม่ อ และ\nเสาเข็ม ดุษฎีสามารถฟ้องบังคับให้ร้ื อถอนได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2550-1-1-89","year":"2550","semester":"ภาค 1","number":1,"page":89,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2550 ภาค 1 · ข้อ 1","sections":["1299"],"otherSections":["1300"],"question":"ข้อ 1 นายน้ าเข้าครอบครองที่ดินมีโฉนดของนายเปลวโดยสงบ เปิ ดเผย และมีเจตนาเป็ นเจ้าของติดต่อกัน\nได้เก้าปี พอขึ้นปี ที่ สิบ นายเปลวได้ฟ้องขับไล่ นายน้ าให้ออกไปจากที่ ดินแปลงนั้น คดีอยู่ระหว่า งการ\nพิ จารณาของศาล นายน้ า กับ นายเปลวตกลงยอมความกัน โดยนายเปลวยินยอมให้นายน้ า เช่ าซื้ อที่ ดิน\nพิพาท หากชาระค่าเช่าซื้อครบถ้วนแล้วนายเปลวยอมให้ที่ดินพิพาทตกเป็ นกรรมสิ ทธิ์ของนายน้ าทันที และ\nนายเปลวจะจดทะเบียนโอนกรรมสิ ทธิ์ ให้แก่นายน้ า หากไม่ปฏิบตั ิตามข้อตกลงให้ถือเอาคาพิพากษาแทน\nการแสดงเจตนา\nและศาลมีคาพิพากษาตามยอม คดีถึงที่สุดแล้ว หลังจากนายน้ าชาระราคาครบถ้วน นายเปลวยัง\nไม่ได้ไปจดทะเบียนโอนกรรมสิ ทธิ์ ที่ดินพิพาทให้นายน้ า นายเปลวก็ถึงแก่ความตาย นายเพลิงซึ่งเป็ นบุตร\nของนายเปลวได้จ ดทะเบี ย นรั บ มรดกที่ ดิ นพิ พ าทในฐานะทายาทโดยชอบธรรม และไม่ รู้เรื่ องสั ญ ญา\nประนีประนอมยอมความระหว่างนายน้ ากับนายเปลวแต่อย่างใด\nดังนี้ ให้ท่านวินิจฉัยว่า นายน้ าจะฟ้องขอให้เพิกถอนการจดทะเบียนรับมรดกที่ดินพิพาทและบังคับ\nให้นายเพลิงจดทะเบียนโอนกรรมสิ ทธิ์ให้แก่ตนได้หรื อไม่ เพราะเหตุใด","rule":"มาตรา 1299 ภายในบังคับแห่ งบทบัญญัติในประมวลกฎหมายนี้ หรื อกฎหมายอื่ น ท่านว่า การ\nได้มาโดยนิ ติกรรมซึ่งอสังหาริ มทรัพย์หรื อทรัพยสิ ทธิ อนั เกี่ยวกับอสังหาริ มทรัพย์น้ นั ไม่บริ บูรณ์ เว้นแต่นิติ\nกรรมจะได้ทาเป็ นหนังสื อและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่\nมาตรา 1300 ถ้ า ได้ จ ดทะเบี ย นการโอนอสั ง หาริ มทรั พ ย์ หรื อทรั พ ยสิ ทธิ อั น เกี่ ย วกั บ\nอสังหาริ มทรัพย์ เป็ นทางเสี ยเปรี ยบแก่ บุค คลผูอ้ ยู่ใ นฐานะอันจะให้จดทะเบี ยนสิ ทธิ ข องตนได้อยู่ ก่ อน\nไซร้ ท่านว่าบุคคลนั้นอาจเรี ยกให้เพิกถอนการจดทะเบียนนั้นได้ แต่การโอนอันมีค่าตอบแทน ซึ่งผูร้ ับโอน\nกระทาการโดยสุ จริ ตนั้น ไม่วา่ กรณีจะเป็ นประการใด ท่านว่าจะเรี ยกให้เพิกถอนทะเบียนไม่ได้","application":"นายน้ าแย่งการครอบครองปรปั กษ์ที่ดินของนายเปลวติดต่อกันยังไม่ครบสิ บปี ก็ถูกนายเปลวฟ้อง\nขับไล่จึงยังไม่ได้กรรมสิ ทธิ์ โดยการครอบครองปรปักษ์ แต่ขณะที่คดีอยู่ระหว่างการพิจารณาของศาลนาย\nน้ ากับนายเปลวตกลงยอมความกัน โดยนายเปลวยินยอมให้นายน้ าเช่าซื้ อที่ดินพิพาท หากชาระค่าเช่าซื้ อ\nครบถ้วนแล้วนายเปลวยอมให้ที่ดินพิพาทตกเป็ นกรรมสิ ทธิ์ ของนายน้ าทันที และนายเปลวจะจดทะเบียน\nโอนกรรมสิ ทธิ์ ให้แก่นายน้ า หากปฏิบตั ิตามข้อตกลงให้ถือเอาคาพิพากษาแทนการแสดงเจตนา และศาลมี\nค าพิ พ ากษาตามยอม คดี ถึ ง ที่ สุ ด แล้ว และนายน้ า ช าระราคาเช่ า ซื้ อ ครบถ้ว นแล้ว เช่ น นี้ นายน้ า จึ ง ได้\nกรรมสิ ทธิ์ที่ดินพิพาท โดยสัญญาประนีประนอม ยอมความในชั้นศาล ซึ่งเป็ นการได้มาโดยทางนิติกรรม\nตามมาตรา 1299 วรรคแรก เมื่อยังไม่ได้จดทะเบียนกับพนักงานเจ้าหน้าที่ การได้ซ่ ึ งกรรมสิ ทธิ์ จึงยังไม่\nบริ บูรณ์ในฐานะทรัพยสิ ทธิ แต่ยงั คงมีผลบังคับนายน้ ากับนายเปลวในฐานะบุคคลสิ ทธิ ซึ่ งนายน้ าสามารถ\nฟ้องบังคับให้นายเปลวไปจดทะเบียนโนกรรมสิ ทธิ์ให้แก่ตนได้\nหลังจากนั้น นายเปลวถึ งแก่ ความตาย นายเพลิงซึ่ งเป็ นบุตรของนายเปลวได้จดทะเบียนรับมรดกที่ ดิน\nพิ พ าทในฐานะทายาทโดยชอบธรรม ซึ่ ง เป็ นผูส้ ื บ สิ ท ธิ ของนายเปลวต้องรั บ ไปทั้ง สิ ทธิ และหน้า ที่ ของ\nเจ้าของมรดกและการจดทะเบียนรับมรดกดังกล่าวทาให้นายน้ าผูอ้ ยู่ในฐานะอันจะให้จดทะเบียนสิ ทธิ ของ\nตนได้ก่อนต้องเสี ยเปรี ยบนายน้ าจึงสามารถฟ้องศาลให้เพิกถอนการจดทะเบียนรับมรดกของนายเพลิงได้\nตามมาตรา 1300 เพราะเป็ นการได้ม าซึ่ ง กรรมสิ ท ธิ์ โดยไม่ มี ค่ า ตอบแทน และบัง คับ ให้นายเพลิ ง จด\nทะเบียนโอนกรรมสิ ทธิ์ให้แก่ตนได้","conclusion":"สรุ ป นายน้ าสามารถฟ้ องให้เพิกถอนการจดทะเบียนรับมรดกและบังคับให้นายเพลิงจดทะเบียน\nโอนกรรมสิ ทธิ์แก่ตนได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2550-1-2-90","year":"2550","semester":"ภาค 1","number":2,"page":90,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2550 ภาค 1 · ข้อ 2","sections":["144"],"otherSections":["1312"],"question":"ข้ อ 2 นายเอกมีที่ดินแปลงหนึ่ งอยู่ติดกับที่ดินของนายโท นายเอกได้สร้างบ้านบนที่ดินของตนโดยก่ อน\nปลูกสร้างได้เรี ยกเจ้าพนักงานมารังวัดสอบเขตแล้ว แต่เมื่อสร้างเสร็ จจึงพบว่ารั้วกาแพงและท่อระบายน้ ารุ ก\nล้ าอยูใ่ นเขตที่ดินของนายโท 1 ตารางวา\nดังนี้ นายเอกจะต้องรื้ อถอนรั้วกาแพงและท่อระบายน้ าหรื อไม่ นายเอกและนายโทมีหน้าที่จะต้อง\nปฏิบตั ิต่อกันอย่างไร หรื อไม่ จงอธิบาย","rule":"มาตรา 144 ส่ ว นควบของทรั พ ย์ หมายความว่า ส่ ว นซึ่ ง โดยสภาพแห่ ง ทรั พ ย์ห รื อ โดยจารี ต\nประเพณี แห่ งท้องถิ่นเป็ นสาระสาคัญในความเป็ นอยู่แห่ งทรัพย์น้ นั และไม่อาจแยกจากกันได้นอกจากจะ\nทาลาย ทาให้บุบสลาย หรื อทาให้ทรัพย์น้ นั เปลี่ยนแปลงรู ปทรงหรื อสภาพไป\nเจ้าของทรัพย์ยอ่ มมีกรรมสิ ทธิ์ในส่ วนควบของทรัพย์น้ นั\nมาตรา 1312 วรรคแรก บุคคลใดสร้างโรงเรื อนรุ กล้ าเข้าไปในที่ดินของผูอ้ ื่นโดยสุ จริ ตไซร้ ท่าน\nว่าบุคคลนั้นเป็ นเจ้าของโรงเรื อนที่ สร้ างขึ้น แต่ตอ้ งเสี ยเงิ นให้แก่ เจ้าของที่ ดินเป็ นค่าใช้ที่ดินนั้นและจด\nทะเบียนสิ ทธิเป็ นภาระจายอม ต่อภายหลังถ้าโรงเรื อนนั้นสลายไปทั้งหมด เจ้าของที่ดินจะเรี ยกให้เพิกถอน\nการจดทะเบียนเสี ยก็ได้","application":"การที่นายเอกทาการรังวัดสอบเขตก่อนปลูกบ้านเป็ นการปลูกสร้างที่สุจริ ต เพราะไม่ได้เพิกเฉยละเลยในการ\nตรวจสอบแนวเขต แต่เมื่อสร้างเสร็ จพบว่ารั้วกาแพงและท่อระบายน้ ารุ กล้ าอยูใ่ นเขตของนายโท นายเอกจึง\nต้องรื้ อถอนรั้ วก าแพงและท่ อระบายน้ า ออกจากที่ ดินของนายโท แม้ว่า จะเป็ นการปลูก สร้ า งที่ สุ จริ ตก็\nตาม เพราะรั้วกาแพงและท่อระบายน้ ามิใช่ส่วนควบของโรงเรื อน ตามมาตรา 144 จึงไม่อยู่ในความหมาย\nของการปลูกสร้ า งโรงเรื อนรุ กล้ าในมาตรา 1312 วรรคแรก ดังนั้น นายเอกจึ งมี หน้าที่ ต้องรื้ อถอนรั้ ว\nกาแพง และท่อระบายน้ าออกไปจากที่ดินของนายโท แม้วา่ จะเป็ นการสร้างรุ กล้ าที่สุจริ ตก็ตาม","conclusion":"สรุป นายเอกมีหน้าที่ตอ้ งรื้ อถอนรั้วกาแพงและท่อระบายน้ าออกไปจากที่ดินของนายโท","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2550-1-3-91","year":"2550","semester":"ภาค 1","number":3,"page":91,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2550 ภาค 1 · ข้อ 3","sections":["1382","1387","1401"],"otherSections":["1395","1399"],"question":"ข้ อ 3 นายสมเป็ นเจ้าของกรรมสิ ทธิ์ ในที่ดินแปลงหนึ่ งซึ่ งไดภาระจายอมในการใช้ทางผ่านที่ดินของนาย\nแสงตลอดไป และได้จดทะเบียนไว้แล้ว แต่เมื่อใช้ภาระจายอมไปได้ระยะหนึ่ ง นายสมได้ก้ นั รั้วแบ่งแยก\nที่ดินแปลงนั้นของตนออกเป็ นสองส่ วน ที่ดินอีกส่ วนที่แบ่งแยกออกไปได้ให้นายสดเช่าปลูกบ้าน นายสด\nปลูกบ้านอยู่บนที่ดินแปลงนั้น และใช้ทางผ่านเข้าออกบนที่ดินของนายสวยเพื่อออกสู่ ทางสาธารณะ และ\nไม่เคยได้ใช้ทางผ่านที่ดินของนายแสงอีกเลย มีเพียงแต่นายสมเท่านั้นใช้ทางผ่านที่ดินของนายแสง นายสด\nได้ใช้ถนนผ่านเข้าออกบนที่ดินของนายสวยเพื่อออกสู่สาธารณะโดยไม่เคยขอหรื อบอกนายสวยเลย\nให้นกั ศึกษาอธิบายว่า\n1 นายแสงจะขอให้ที่ดินส่วนที่นายสดครอบครองพ้นจากภาระจายอมได้หรื อไม่ เพราะเหตุใด\n2 ถ้านายสดใช้ทางผ่านที่ดินของนายสวยจะก่อให้เกิดภาระจายอมบนที่ดินของนายสมและส่ วน\nที่นายสดครอบครองนั้นได้หรื อไม่เพียงใด อธิบายให้ละเอียด","rule":"มาตรา 1382 บุคคลใดครอบครองทรัพย์สินของผูอ้ ื่นไว้โดยความสงบและโดยเปิ ดเผยด้วยเจตนา\nเป็ นเจ้า ของ ถ้า เป็ นอสั ง หาริ ม ทรั พ ย์ไ ด้ค รอบครองติ ด ต่ อ กัน เป็ นเวลาสิ บ ปี ถ้า เป็ นสั ง หาริ ม ทรั พ ย์ไ ด้\nครอบครองติดต่อกันเป็ นเวลาห้าปี ไซร้ ท่านว่าบุคคลนั้นได้กรรมสิ ทธิ์\nมาตรา 1387 อสังหาริ มทรัพย์อาจต้องตกอยูใ่ นภาระจายอมอันเป็ นเหตุให้เจ้าของต้องยอมรับกรรม\nบางอย่างซึ่งกระทบถึงทรัพย์สินของตน หรื อต้องงดเว้นการใช้สิทธิ บางอย่างอันมีอยู่ในกรรมสิ ทธิ์ นั้นเพื่อ\nประโยชน์แก่อสังหาริ มทรัพย์อื่น\nมาตรา 1395 ถ้ามีการแบ่งแยกสามยทรัพย์ ท่านว่าภาระจายอมยังคงมีอยู่เพื่อประโยชน์แก่ทุกส่ วน\nที่แยกออกนั้น แต่ถา้ ภาระจายอมนั้นไม่ใช้ และใช้ไม่ได้ตามรู ปการเพื่อประโยชน์แก่ส่วนใดไซร้ ท่านว่า\nเจ้าของภารยทรัพย์จะเรี ยกให้พน้ จากภาระจายอมอันเกี่ยวกับทรัพย์ส่วนนั้นก็ได้\nมาตรา 1399 ภาระจายอมนั้น ถ้ามิได้ใช้สิบปี ท่านว่าย่อมสิ้ นไป\nมาตรา 1401 ภาระจายอมอาจได้มาโดยอายุความ ท่านให้นาบทบัญญัติวา่ ด้วยอายุความได้สิทธิ อนั\nกล่าวไว้ในลักษณะ 3 แห่งบรรพนี้มาใช้บงั คับโดยอนุโลม","application":"นายสมเป็ นเจ้าของกรรมสิ ทธิ์ ในที่ดินแปลงหนึ่ ง ซึ่ งได้ภาระจายอมในการใช้ทางผ่านที่ดินของนายแสง\nตลอดไป และจดทะเบียนไว้แล้ว แต่เมื่อใช้ภาระจายอมไปได้ระยะหนึ่ ง นายสมได้แบ่งแยกกั้นรั้ วที่ ดิน\nแปลงนั้นของตนออกเป็ นสองส่ วน ส่ วนหนึ่ งให้นายสดปลูกบ้านเช่าอยู่ นายสดจึงปลูกบ้านอยู่บนที่ดิน\nแปลงนั้น และนายสดก็ไม่เคยใช้ทางผ่านที่ดินของนายแสงอีกเลย มีเพียงนายสมเท่านั้นใช้ทางผ่านที่ดิน\nของนายแสงนายสดใช้ถนนผ่านเข้าออกบนที่ดินของนายสวยเพื่อออกสู่ สาธารณะแทนโดยไม่เคยขอหรื อ\nบอกนายสวยเลย\n1 นายแสงจะขอให้ที่ ดิ น ส่ ว นที่ น ายสดครอบครองพ้น จากภาระจ ายอมไม่ ไ ด้ เพราะไม่ ใ ช่\nแบ่ ง แยกกรรมสิ ท ธิ์ ที่ ดินทั้ง แปลงยัง เป็ นของนายสม จึ ง ไม่ มี สิ ท ธิ์ ที่ จะขอให้พ น้ จากภาระจายอมตาม\nมาตรา 1395 และภาระจายอมก็ยงั ไม่สิ้นไปตามมาตรา 1399 เพราะนายสมยังคงใช้ภาระจายอมผ่านที่ดิน\nของนายแสงอยู่\n2 ถ้านายสดใช้ทางผ่านที่ดินของนายสวยจะก่อให้เกิดภาระจายอมบนที่ดินของนายสมทั้งแปลง\nทั้งส่ วนของนายสดที่ครอบครองอยู่ ในการผ่านที่ดินของนายสวยโดยการครอบครองปรปักษ์ไม่จาเป็ นต้อง\nเป็ นเจ้าของสามยทรั พย์ใครก็ตามที่ อยู่ในสามยทรั พย์ก่อให้เกิ ดภาระจายอมโดยการครอบครองปรปั ก ษ์\nได้ มาตรา 1387","conclusion":"สรุป 1 นายแสงไม่มีสิทธิที่จะขอให้พน้ จากภาระจายอมได้\n2 นายสดจะก่ อให้เกิ ดภาระจายอมบนที่ ดินของนายสมทั้ง แปลง รวมทั้ง ส่ วนของนายสด\nครอบครองอยูไ่ ด้โดยการครอบครองปรปักษ์","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2550-1-4-92","year":"2550","semester":"ภาค 1","number":4,"page":92,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2550 ภาค 1 · ข้อ 4","sections":["1367","1375"],"otherSections":["1381"],"question":"ข้อ 4 นายแดงได้กูย้ มื เงินนายดามาจานวน 500,000 บาท กาหนดชาระเงินคืนภายในสามปี และได้ให้นาย\nดาเข้าครอบคอรงทาประโยชน์บนที่ดินมือเปล่าแปลงหนึ่ งของนายแดงแทนค่าดอกเบี้ยเงินกู้ ต่อมาเมื่อกูย้ ืม\nเงินกันไปได้หนึ่งปี นายขาวบุตรชายของนายแดงได้มาทาสัญญาขายที่ดินแปลงนั้นกับนายดา โดยนายดา\nได้ใ ห้เงิ นนายขาวไปจานวน 200,000 บาท แต่ ก่ อนที่ จะครบสามปี ตามสั ญ ญากู้ยืม โดยนายดาได้น า\nเงิน 500,000 บาท มาชาระหนี้ เงินกู้ และเรี ยกที่ดินแปลงนั้นคืน แต่นายดาไม่ยอมรับและไม่ยอมออกไป\nจากที่ดินแปลงนั้นโดยอ้างว่าที่ดินแปลงนั้นนายขาวได้ขายให้ตนมาได้เกินกว่าหนึ่งปี แล้ว\nดังนี้ถา้ นายแดงมาปรึ กษาท่าน ท่านจะให้คาแนะนากับนายแดงอย่างไร เพราะเหตุใด","rule":"มาตรา 1367 บุคคลใดยึดถือทรัพย์สินโดยเจตนาจะยึดถื อเพื่ อตน ท่านว่าบุคคลนั้นได้ซ่ ึ ง สิ ท ธิ\nครอบครอง\nมาตรา 1375 ถ้า ผูค้ รอบครองถู ก แย่ ง การครอบครองโดยมิ ช อบด้ว ยกฎหมายไซร้ ท่ า นว่า ผู ้\nครอบครองมีสิทธิจะได้คืนซึ่งการครอบครอง เว้นแต่อีกฝ่ ายหนึ่งมีสิทธิเหนือทรัพย์สินดีกว่า ซึ่งจะเป็ นเหตุ\nให้เรี ยกคืนจากผูค้ รอบครองได้\nการฟ้ อ งคดี เ พื่ อ เอาคื น ซึ่ งการครอบครองนั้ น ท่ า นว่ า ต้อ งฟ้ อ งภายในหนึ่ งปี นั บ แต่ เ วลาถู ก แย่ ง การ\nครอบครอง\nมาตรา 1381 บุคคลใดยึดถือทรัพย์สินอยู่ในฐานะเป็ นผูแ้ ทนผูค้ รอบครอง บุคคลนั้นจะเปลี่ ยน\nลัก ษณะแห่ ง การยึดถื อได้ก็ แต่โดยบอกกล่า วไปยัง ผูค้ รอบครองว่า ไม่ เจตนาจะยึดถื อทรั พ ย์สิ นแทนผู ้\nครอบครองต่อไป หรื อตนเองเป็ นผูค้ รอบครองโดยสุจริ ต อาศัยอานาจใหม่อนั ได้จากบุคคลภายนอก","application":"นายแดงได้กูย้ มื เงินมาจากนายดาจานวน 500,000 บาท กาหนดชาระเงินคืนภายในสามปี และได้ให้นายดา\nเข้าใช้ประโยชน์บนที่ดินมือเปล่าแปลงหนึ่ งของนายแดงแทนค่าดอกเบี้ยเงินกู้ ต่อมาเมื่อกูย้ ืมเงินไปได้หนึ่ง\nปี นายขาวบุตรชายของนายแดงได้มาทาสัญญาขายที่ดินแปลงนั้นกับนายดาโดยนายดาได้ให้เงินนายขาวไป\nจานวน 200,000 บาท แต่ก่อนที่ครบสามปี ตามสัญญากูย้ ืมเงิน นายแดงได้นาเงิน 500,000 บาท มาชาระ\nหนี้เงินกูแ้ ละเรี ยกที่ดินแปลงนั้นคืน แต่นายดาไม่ยอมรับและก็ไม่ยอมออกไปจากที่ดินแปลงนั้น โดยอ้างว่า\nที่ดินแปลงนั้นนายขาวได้ขายที่ดินแปลงนี้ ให้ตนมาได้กว่าหนึ่ งปี แล้ว ดังนี้ นายแดงต้องฟ้องเรี ยกคืนที่ดิน\nแปลงนั้นจากนายดาภายในระยะเวลาหนึ่ งปี นับตั้งแต่นายแดงไปชาระหนี้ เงินกู้ และนายดาไม่ยอมรับชาระ\nหนี้ กูย้ ืมไม่ยอมออกไปและไม่ส่งที่ ดินแปลงนั้นคืนนายแดง โดยอ้างว่าได้ซ้ื อที่ ดินแปลงนั้นจากนายขาว\nบุตรชายของนายแดงแล้ว แสดงว่านายดาได้แย่งการครอบครองที่ดินมือเปล่าแปลงนั้นจากนายแดงสาเร็ จ\nแล้ว ตามมาตรา 1381 นายดาครอบครองที่ดินแปลงนั้นด้วยตนเองตามมาตรา 1367 นายแดงต้องฟ้องต่อ\nศาลเรี ยกคืนที่ดินแปลงนั้นภายในระยะเวลาหนึ่งปี ตามมาตรา 1375","conclusion":"สรุป ข้าพเจ้าจะแนะนาให้นายแดงฟ้องต่อศาลเรี ยกคืนที่ดินแปลงนั้นภายในระยะเวลา 1 ปี นับแต่\nวันที่นายดาไม่ยอมรับชาระหนี้เงินกู้ และไม่ยอมออกไปจากที่ดิน\nการสอบไล่ ภาคฤดูร้อน ปี การศึกษา 2549\nข้อสอบกระบวนวิชา LAW2001 (LA 201),(LW 204)\nกฎหมายแพ่งและพาณิชย์ว่าด้วยทรัพย์\nคาแนะนา ข้อสอบเป็ นอัตนัยล้วนมี 4 ข้อ","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2549-s-1-94","year":"2549","semester":"ภาคฤดูร้อน","number":1,"page":94,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2549 ภาคฤดูร้อน · ข้อ 1","sections":["144"],"otherSections":[],"question":"ข้ อ 1 นายคงทาสัญญาเช่าตึกแถวของนายมัน่ เพื่ออยู่อาศัยเป็ นเวลา 5 ปี โดยสัญญาเช่าระบุว่าทรัพย์ใดๆที่\nนายคงผูเ้ ช่าดัดแปลงหรื อต่อเติมลงในตึกแถวที่เช่าให้ทรัพย์น้ นั ตกเป็ นของนายมัน่ ผูใ้ ห้เช่าทันที หลังจากที่\nนายคงเข้าไปอยู่ในตึก แถวดังกล่า วได้ 2 ปี นายคงได้ทาฝากั้นห้องที่ บ ริ เวณชั้น 3 ของตึก และติ ดตั้ง\nเครื่ องปรับอากาศเพื่อใช้เป็ นห้องนอนเพิม่ อีกห้องหนึ่ง เมื่อครบกาหนดตามสัญญาเช่า นายคงจะรื้ อถอนเอา\nไม้ที่ทาเป็ นฝากั้นห้องและเครื่ องปรับอากาศออกไป\nนายมัน่ ไม่ยอมโดยอ้างว่าทั้งไม้และเครื่ องปรับอากาศเป็ นกรรมสิ ทธิ์ของนายมัน่ แล้วตามสัญญาเช่าดังกล่าว\nดั ง นี้ ให้ ท่ า นวิ นิ จ ฉั ย ว่ า นายคงจะรื้ อถอนไม้ ฝ ากั้ น ห้ อ งและเครื่ องปรั บ อากาศออกไปได้\nหรื อไม่ เพราะเหตุใด","rule":"มาตรา 144 ส่ ว นควบของทรั พ ย์ หมายความว่า ส่ ว นซึ่ ง โดยสภาพแห่ ง ทรั พ ย์ห รื อ โดยจารี ต\nประเพณี แห่ งท้องถิ่นเป็ นสาระสาคัญในความเป็ นอยู่แห่ งทรัพย์น้ นั และไม่อาจแยกจากกันได้นอกจากจะ\nทาลาย ทาให้บุบสลาย หรื อทาให้ทรัพย์น้ นั เปลี่ยนแปลงรู ปทรงหรื อสภาพไป\nเจ้าของทรัพย์ยอ่ มมีกรรมสิ ทธิ์ในส่ วนควบของทรัพย์น้ นั","application":"นายคงทาสัญญาเช่ า ตึ ก แถวของนายมัน่ เพื่ ออยู่อาศัย เป็ นเวลา 5 ปี หลังจากนายคงเข้าไปอยู่ใ นตึ ก แถว\nได้ 2 ปี นายคงได้ทาฝากั้นห้องที่บริ เวณชั้น 3 ของตึก และติดตั้งเครื่ องปรับอากาศเพื่อใช้เป็ นห้องนอน\nนั้น ทั้งฝากั้นห้องและเครื่ องปรับอากาศไม่เป็ นส่ วนควบของตึก เพราะไม่เป็ นสาระสาคัญในความเป็ นอยู่\nของตึกอันไม่อาจแยกออกได้นอกจากทาให้ตวั ตึกเสี ยรู ปทรง จึงไม่ตกเป็ นกรรมสิ ทธิ์ ของนายมัน่ ผูใ้ ห้เช่า\nตามมาตรา 144\nดัง นั้น เมื่ อ ครบก าหนดตามสั ญ ญาเช่ า นายคงสามารถรื้ อถอนเอาไม้ที่ ท าเป็ นฝากั้น ห้ อ งและ\nเครื่ องปรับอากาศออกไปได้ แม้ในสัญญาเช่าระบุว่าทรัพย์ใดๆที่นายคงผูเ้ ช่าดัดแปลงหรื อต่อเติมลงใน\nตึกแถวที่เช่า ให้ทรัพย์น้ นั ตกเป็ นของนายมัน่ ผูใ้ ห้เช่าทันทีก็ตาม แต่ท้ งั นี้ ทรัพย์ที่ต่อเติมนั้นหมายความถึง\nการกระทาที่มาเป็ นส่ วนควบของตึก เมื่อฝากั้นห้องและเครื่ องปรับอากาศไม่เป็ นส่ วนควบของตึกดังกล่าว\nแล้ว นายคงจึงสามารถรื้ อถอนออกไปได้","conclusion":"สรุป นายคงสามารถรื้ อถอนไม้ฝากั้นห้องและเครื่ องปรับอากาศออกไปได้","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2549-s-2-95","year":"2549","semester":"ภาคฤดูร้อน","number":2,"page":95,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2549 ภาคฤดูร้อน · ข้อ 2","sections":["1304"],"otherSections":["1305","1306"],"question":"ข้อ 2 นายก้องได้เข้าครอบครองทาไร่ ในที่ดินแปลงหนึ่งซึ่งมีสภาพเป็ นป่ าเสื่ อมโทรม แต่ทางราชการยังไม่\nออกพระราชกฤษฎี ก าเพิ ก ถอนการเป็ นที่ ป่ าสงวนแห่ ง ชาติ หลัง จากที่ น ายก้อ งท าไร่ ใ นที่ ดิ น ดัง กล่า ว\nได้ 5 ปี นายก้องได้ไปพบนายขาเพื่อนของตน และขอให้นายขาซึ่งเป็ นเจ้าพนักงานที่ดินช่วยออกหนังสื อ\nรับรองการทาประโยชน์ (น.ส.3) ให้ ทั้งที่กรมที่ดินยังไม่ได้ประกาศให้ประชาชนเช้าจับจองเป็ นเจ้าของ\nหรื อออกเอกสารสิ ทธิแต่อย่างใด\nเมื่อนายก้องได้หนังสื อรับรองการทาประโยชน์ (น.ส.3) มาแล้ว นายก้องได้ทาหนังสื อและจด\nทะเบียนกับพนักงานเจ้าหน้าที่ขายที่ดินดังกล่าวให้กบั นายแก้ว ต่อมาทางราชการได้แจ้งให้นายแก้วออกไป\nจากที่ดินดังกล่าว แต่นายแก้วไม่ยอมย้ายออกจากที่ดินแปลงนั้น โดยต่อสู ้วา่ ตนซื้อที่ดินมาโดยสุ จริ ตและจด\nทะเบียนสิ ทธิโดยสุจริ ต\nดังนี้ ให้ท่านวินิจฉัยว่า ข้อต่อสู้ของนายแก้วรับฟังได้หรื อไม่ เพราะเหตุใด","rule":"มาตรา 1304 สาธารณะสมบัติข องแผ่นดิ นนั้น รวมทรั พ ย์สิ นทุ ก ชนิ ดของแผ่นดิ น ซึ่ ง ใช้เพื่ อ\nสาธารณะประโยชน์ หรื อสงวนไว้เพื่อประโยชน์ร่วมกัน เช่น\n(1) ที่ดินรกร้างว่างเปล่า และที่ดินซึ่งมีผเู ้ วนคืนหรื อทอดทิง้ หรื อกลับมาเป็ นของแผ่นดินโดยประการอื่นตาม\nกฎหมายที่ดิน\nมาตรา 1305 ทรั พ ย์สิ นซึ่ ง เป็ นสาธารณสมบัติของแผ่นดิ นนั้นจะโอนแก่ กันมิ ได้ เว้นแต่อาศัย\nอานาจแห่งบทกฎหมายเฉพาะหรื อพระราชกฤษฎีกา\nมาตรา 1306 ท่านห้ามมิ ให้ยกอายุความขึ้นเป็ นข้อต่อสู ้กับแผ่นดิ นในเรื่ องทรั พย์สินอันเป็ นสา\nธารณสมบัติของแผ่นดิน","application":"ป่ าเสื่ อมโทรมที่ทางราชการยังไม่ออกพระราชกฤษฎีกาเพิกถอนการเป็ นที่ป่าสงวนแห่ งชาติน้ นั ยังมีสภาพ\nเป็ นสาธารณสมบัติของแผ่นดินตามมาตรา 1304(1) ดังนั้นแม้นายก้องจะเข้าไปครอบครองทาไร่ ในที่ดิน\nดังกล่าวนานเท่าใด นายก้องก็ไม่ได้กรรมสิ ทธิ์หรื อสิ ทธิครอบครองในที่ดินแปลงนั้น เพราะสาธารณสมบัติ\nของแผ่นดินไม่สามารถยกอายุความขึ้นต่อสู ้กบั แผ่นดินตามมาตรา 1306\nส่ วนการที่นายก้องไปพบนายขาเพื่ อนของตน และขอให้นายขาเป็ นเจ้าพนัก งานที่ ดินช่วยออกหนัง สื อ\nรับรองการทาประโยชน์ (น.ส.3) ให้ ทั้งที่กรมที่ดินยังไม่ได้ประกาศให้ประชาชนเข้าจับจองเป็ นเจ้าของ\nหรื อออกเอกสารสิ ทธิแต่อย่างใด จึงเป็ นการออกหนังสื อรับรองการทาประโยชน์ (น.ส.3) โดยมิชอบด้วย\nกฎหมาย กรมที่ดินสามารถเพิกถอนหนังสื อรับ รองการทาประโยชน์ (น.ส.3) นั้นได้ และนายก้องไม่\nสามารถทาสัญญาและจดทะเบียนขายที่ ดินนั้นให้กบั นายแก้ว เพราะมาตรา 1305 มีหลักกฎหมายความ\nว่า ทรัพย์สินซึ่งเป็ นสาธารณสมบัติของแผ่นดินนั้นจะโอนแก่กนั มิได้ เว้นแต่อาศัยอานาจแห่งบทกฎหมาย\nเฉพาะหรื อพระราชกฤษฎีกา ดังนั้นเมื่อทางราชการได้แจ้งให้นายแก้วออกไปจากที่ดินดังกล่าว นายแก้วจึง\nต้องย้ายออกไปจากที่ดินอันเป็ นสาธารณสมบัติของแผ่นดินนั้น ข้อต่อสู ้ของนายแก้วที่วา่ ตนซื้ อที่ดินมาโดย\nสุจริ ต และจดทะเบียนสิ ทธิโดยสุจริ ตจึงรับฟังไม่ได้","conclusion":"สรุป ข้อต่อสู ้ของนายแก้งฟังไม่ข้ นึ เพราะที่ดินดังกล่าวเป็ นสาธารณสมบัติของแผ่นดิน","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2549-s-3-96","year":"2549","semester":"ภาคฤดูร้อน","number":3,"page":96,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2549 ภาคฤดูร้อน · ข้อ 3","sections":["1368"],"otherSections":["1380"],"question":"ข้อ 3 นายชุ่มทาไร่ ในที่ดินมือเปล่าแห่งหนึ่ง ต่อมานายชุ่มได้ขายที่ดินแปลงนี้ให้นายชม และนายชมได้ให้\nนายชุ่มอยู่ทาไร่ ดูแลที่ดินแปลงนี้ ต่อให้ เมื่อนายชุ่มครอบครองที่ดินแปลงนี้ ต่อมาได้เจ็ดปี นายชุ่มได้นา\nที่ดินแปลงนี้ ไปขายให้นายชิ ตส่ งมอบการครอบครองให้นายชิ ต โดยนายชิ ตไม่ทราบว่าที่ดินแปลงนี้ เป็ น\nของนายชม นายชิตซื้อที่ดินแปลงนี้จากนายชุ่มมาได้สามเดือน\nเมื่อเจ้าพนักงานรังวัดสารวจเพื่อออกหนังสื อสาคัญสาหรับที่นายชิ ตได้แจ้งการครอบครองที่ดินแปลงนี้ ว่า\nเป็ นของตนต่อเจ้าพนักงาน นายชมได้ไปร้องคัดค้าน และฟ้องขับไล่นายชิตให้ออกไปจากที่ดินแปลงนี้\nให้ ท่ า นวิ นิ จ ฉั ย ว่ า ระหว่ า งนายชมและนายชิ ต ใครมี สิ ท ธิ ค รอบครองในที่ ดิ น แปลงนี้ ดี ก ว่ า\nกัน เพราะเหตุใด","rule":"มาตรา 1368 บุคคลอาจได้มาซึ่งสิ ทธิครอบครองโดยผูอ้ ื่นยึดถือไว้ให้\nมาตรา 1380 การโอนไปซึ่งการครอบครองย่อมเป็ นผลแม้ ผูโ้ อนยังยึดถือทรัพย์สินอยู่ ถ้าผูโ้ อน\nแสดงเจตนาว่าต่อไปจะยึดถือทรัพย์สินนั้นแทนผูร้ ับโอน\nถ้าทรัพย์สินนั้นผูแ้ ทนของผูโ้ อนยึดถืออยู่ การโอนไปซึ่ งการครอบครองจะทาโดยผูโ้ อนสั่งผูแ้ ทนว่า ต่อไป\nให้ยดึ ถือทรัพย์สินไว้แทนผูร้ ับโอนก็ได้","application":"นายชุ่มได้ทาไร่ ในที่ดินมือเปล่าแปลงหนึ่ง ต่อมานายชุ่มได้ขายที่ดินแปลงนี้ให้นายชมและนายชมได้ให้นาย\nชุ่มอยู่ทาไร่ ดูแลที่ดินแปลงนั้นให้ตน นายชุ่มจึงยึดถือที่ดินแปลงนั้นแทนนายชมตามมาตรา 1380 นายชม\nจึ งมี สิทธิ ครอบครองที่ ดินมื อเปล่าแปลงนั้นดี กว่านายชุ่ มตามมาตรา 1368 เมื่อนายชุ่มครอบครองที่ ดิน\nแปลงนั้นต่ อ มาได้เ จ็ ดปี นายชุ่ ม ได้นาที่ ดิ น แปลงนั้นไปขายให้น ายชิ ตส่ ง มอบการครอบครองให้ น าย\nชิต โดยนายชิตไม่ทราบว่าที่ดินแปลงนั้นเป็ นของนายชม เมื่อนายชิตรับโอนจากนายชุ่มซึ่งไม่มีสิทธิดีกว่า\nนายชม นายชิตจึงไม่มีสิทธิในที่ดินมือเปล่าแปลงนั้นดีกว่านายชม ดังนั้นระหว่างนายชมและนายชิตนายชม\nย่อมมีสิทธิครอบครองในที่ดินแปลงนั้นดีกว่านายชิต","conclusion":"สรุป นายชมย่อมมีสิทธิครอบครองในที่ดินแปลงนั้นดีกว่านายชิต","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2548-1-1-114","year":"2548","semester":"ภาค 1","number":1,"page":114,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2548 ภาค 1 · ข้อ 1","sections":["1299"],"otherSections":[],"question":"ข้อ 1 เมฆครอบครองที่ดินมีโฉนดแปลงหนึ่งของฝนมาเป็ นเวลากว่า 10 ปี โดยไม่ได้ดาเนินการเปลี่ยนชื่อ\nในโฉนดจนมาถึงปี ที่ 15 ฝนได้ขายที่ดินแปลงนี้ ให้พายุ โดยพายุไม่มีเวลาไปดูที่ดินที่จะซื้ อจึงไม่รู้ว่าเมฆ\nครอบครองอยู่ หลังจากจดทะเบียนซื้อขายกันเรี ยบร้อยแล้ว พายุนดั หมายนายดาผูร้ ับเหมาก่อสร้างไปดูที่ดิน\nที่ซ้ื อจากฝนเพื่อตกลงเรื่ องการปลูกบ้าน เมื่อไปดูที่ดินพบเมฆครอบครองอาศัยอยู่จึงแจ้งให้เมฆขนย้ายรื้ อ\nถอนบ้านออกไป แต่เมฆไม่สนใจ พายุจึงปรึ กษาทนายความ\nถ้าท่านเป็ นทนายความ จงให้คาแนะนาพายุว่าระหว่างพายุและเมฆ ใครมี สิทธิ ในที่ ดินแปลงนี้\nดีกว่ากัน เพราะเหตุใด","rule":"มาตรา 1299 วรรคสอง ถ้ า มี ผู ้ไ ด้ ม าซึ่ งอสั ง หาริ มทรั พ ย์ หรื อทรั พ ยสิ ทธิ อั น เกี่ ย วกั บ\nอสังหาริ มทรัพย์โดยทางอื่นนอกจากนิ ติกรรม สิ ทธิ ของผูไ้ ด้มานั้น ถ้ายังมิได้จดทะเบียนไซร้ ท่านว่าจะมี\nการเปลี่ยนแปลงทางทะเบียนไม่ได้ และสิ ทธิอนั ยังมิได้จดทะเบียนนั้น มิให้ยกเป็ นข้อต่อสู้บุคคลภายนอกผู ้\nได้สิทธิมาโดยเสี ยค่าตอบแทนและโดยสุจริ ตและได้จดทะเบียนสิ ทธิโดยสุจริ ตแล้ว","application":"เมฆครอบครองที่ดินของฝนมากว่า 10 ปี จึงเป็ นผูไ้ ด้กรรมสิ ทธิ์ มาโดยการครอบครองปรปั กษ์ เป็ นการ\nได้ม าตามวรรคสองของมาตรา 1299 แต่ เ มื่ อ ไม่ ไ ด้เ ปลี่ ย นแปลงทางทะเบี ย น จึ ง อาจมี สิ ท ธิ ด้อ ยกว่า\nบุคคลภายนอกที่ได้มาโดยสุจริ ต เสี ยค่าตอบแทนและจดทะเบียนสิ ทธิโดยสุจริ ตแล้ว\nพายุซ้ือที่ดินจากฝนโดยไม่เคยไปดูที่ดินก่อนซื้ อจึงไม่รู้ว่าเมฆครอบครองปรปั กษ์อยู่ แต่การซื้อขายที่ดินนั้น\nมีหลายรายที่ไม่เคยไปดูที่ก็ทาการซื้ อขายกัน จึงเป็ นการซื้ อที่สุจริ ต ดังนั้นพายุจึงเป็ นบุคคลภายนอกที่ได้\nที่ดินมาโดยสุจริ ต เสี ยค่าตอบแทนและจดทะเบียนสิ ทธิโดยสุจริ ต สิ ทธิของพายุจึงดีกว่าเมฆ","conclusion":"สรุป พายุมีสิทธิในที่ดินแปลงนี้ดีกว่าเมฆ","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"},{"id":"archive-2547-1-1-126","year":"2547","semester":"ภาค 1","number":1,"page":126,"course":"LAW2001 (LA 201 / LW 204)","title":"ปี 2547 ภาค 1 · ข้อ 1","sections":["146","1299"],"otherSections":[],"question":"ข้ อ 1 นายหลีทาสัญญาขายที่ดินมีโฉนดของตนแปลงหนึ่งให้กบั นายหลามในราคาห้าแสนบาท ในวันทา\nสัญญานายหลามได้ชาระราคาแล้วหนึ่งแสนบาท และนายหลีอนุญาตให้นายหลามเข้าไปในที่ดินเพื่อสร้าง\nบ้านอยู่อาศัยหรื อท าประโยชน์ใ นที่ดินตามสัญญาได้ โดยสัญญาซื้ อขายระบุว่าผูซ้ ้ื อและผูข้ ายจะไปจด\nทะเบียนโอนกรรมสิ ทธิ์ และชาระราคาส่ วนที่เหลือทั้งหมดภายใน 1 ปี นับแต่วนั ทาสัญญา หลังจากนาย\nหลามสร้างบ้านลงบนที่ดินนั้นได้เพียง 8 เดือน นายหลีทาสัญญาและจดทะเบียนกับพนักงานเจ้าหน้าที่ขาย\nที่ดินแปลงนี้ให้กบั นายแหลม\nโดยสัญญาซื้ อขายไม่ได้ระบุเรื่ องบ้านไว้ให้ชดั เจน และนายแหลมก็ไม่รู้ขอ้ เท็จจริ งเรื่ องการซื้ อขาย\nที่ดินระหว่างนายหลีกบั นายหลามมาก่อนหลังจากจดทะเบียนโอนกกรมสิ ทธิ์แล้ว นายแหลมได้แจ้งให้นาย\nหลามออกจากบ้านและที่ดินดังกล่าว\nดัง นี้ ใ ห้ท่ า นวิ นิจฉัย ว่า ระหว่างนายหลามกับนายแหลมผูใ้ ดมี กรรมสิ ท ธิ์ ในบ้า นและที่ ดินแปลง\nดังกล่าวดีกว่ากัน เพราะเหตุใด","rule":"มาตรา 146 ทรัพย์ซ่ ึ งติดกับที่ดินหรื อติดกับโรงเรื อนเพียงชัว่ คราวไม่ถือว่าเป็ นส่ วนควบกับที่ดิน\nหรื อโรงเรื อนนั้น ความข้อนี้ให้ใช้บงั คับแก่โรงเรื อนหรื อสิ่ งปลูกสร้างอย่างอื่น ซึ่งผูม้ ีสิทธิในที่ดินของผูอ้ ื่น\nใช้สิทธิน้ นั ปลูกสร้างไว้ในที่ดินนั้นด้วย\nมาตรา 1299 ภายในบังคับแห่ งบทบัญญัติในประมวลกฎหมายนี้ หรื อกฎหมายอื่ น ท่านว่า การ\nได้มาโดยนิ ติกรรมซึ่งอสังหาริ มทรัพย์หรื อทรัพยสิ ทธิ อนั เกี่ยวกับอสังหาริ มทรัพย์น้ นั ไม่บริ บูรณ์ เว้นแต่นิติ\nกรรมจะได้ทาเป็ นหนังสื อและได้จดทะเบียนการได้มากับพนักงานเจ้าหน้าที่","application":"สัญญาซื้ อขายที่ดินระหว่างนายหลีกบั นายหลามที่ระบุว่า ผูซ้ ้ื อและผูข้ ายจะไปจดทะเบียนโอนกรรมสิ ทธิ์\nและชาระราคาส่ วนที่เหลือทั้งหมดภายใน 1 ปี นับแต่วนั ทาสัญญา เป็ นเพียงสัญญาจะซื้ อจะขายกรรมสิ ทธิ์\nในที่ดินจึงยังไม่โอนไปยังนายหลามผูจ้ ะซื้ อ นายหลามจึงยังไม่ถือว่าเป็ นผูไ้ ด้มาซึ่งอสังหาริ มทรัพย์โยทาง\nนิติกรรมตาม ป.พ.พ. มาตรา 1299 วรรค 1 แต่เนื่องจากในวันทาสัญญา นายหลามได้ชาระราคาแล้วหนึ่ง\nแสนบาท และนายหลีอนุญาตให้นายหลามเข้าไปในที่ดินเพื่อสร้างบ้านอยู่อาศัยหรื อทาประโยชน์ในที่ดิน\nตามสัญญาได้ บ้านที่ นายหลามสร้ างขึ้นจึ งไม่ถือเป็ นส่ วนควบของที่ ดิน และยังเป็ นกรรมสิ ทธิ์ ของนาย\nหลามอยู่ เพราะนายหลามเป็ นผูม้ ี สิทธิ ในที่ดินของผื่นและนายหลามได้ใช้สิทธิ น้ นั ปลูกสร้างไว้ตาม ป.\nพ.พ. มาตรา 146\nหลังจากนายหลามสร้างบ้านลงบนที่ดินนั้นได้เพียง 8 เดือน นายหลีทาสัญญาและจดทะเบียนกับ\nพนั ก งานเจ้า หน้ า ที่ ข ายที่ ดิ น แปลงนี้ ให้ กับ นายแหลม โดยสั ญ ญาซื้ อ ขายไม่ ไ ด้ ร ะบุ เ รื่ องบ้า นไว้ใ ห้\nชัดเจน และนายแหลมก็ไม่รู้ขอ้ เท็จจริ งเรื่ องการซื้ อขายที่ ดินระหว่างนายหลี กับนายหลามมาก่ อน นาย\nแหลมจึงเป็ นผ้มีกรรมสิ ทธิ์ในที่ดินแปลงดังกล่าวโดยสมบูรณ์ และมีสิทธิดีกว่านายหลาม ส่ วนบ้านเมื่อไม่\nเป็ นส่ วนควบของที่ดินและยังคงเป็ นกรรมสิ ทธิ์ ของนายหลามอยู่ นายแหลมผูร้ ับโอนจึงไม่มีสิทธิ ดีกว่าผู ้\nโอน นายหลามจึงมีสิทธิในบ้านดีกว่านายแหลม","conclusion":"สรุป นายหลามมีสิทธิในบ้านดีกว่านายแหลม ส่วนนายแหลมมีสิทธิในที่ดินดีกว่านายหลาม","source":"แนวข้อสอบเก่าวิชาทรัพย์สิน.pdf","kind":"old-exam-source"}];})();